const items = $input.all();
if (!items || items.length === 0) return [];
let rawJson = items[0].json;
let body = rawJson.body || rawJson;
if (!body || !body.entry) {
  try { const hookJson = $('Order Webhook1').first().json; body = hookJson.body || hookJson; } catch (e) {}
}
if (!body || !body.entry || !Array.isArray(body.entry) || body.entry.length === 0) return [];
const entry = body.entry[0];
if (!entry.changes || !Array.isArray(entry.changes) || entry.changes.length === 0) return [];
const value = entry.changes[0].value;
if (!value || value.statuses) return [];
if (!value.messages || !Array.isArray(value.messages) || value.messages.length === 0) return [];

const msg = value.messages[0];
let text = "";
let isVoice = false;
let mediaId = null;
let isLocationPin = false;
let locationPin = null;
// A typed price list, a typed product, and a typed question all arrive here as text.
// The typing does not need to be perfect: the agent reads the words, not the spelling.

if (msg.type === "text" && msg.text) {
  text = msg.text.body || "";
} else if (msg.type === "location" && msg.location) {
  // A dropped WhatsApp pin is a fact, not a sentence. Keep the real coordinates the user
  // actually shared and let the map step turn them into a street address. Before this, a
  // pin fell through to the empty branch below and the whole run stopped with no reply.
  isLocationPin = true;
  const loc = msg.location;
  locationPin = {
    lat: Number(loc.latitude),
    lng: Number(loc.longitude),
    name: String(loc.name || '').trim(),
    address: String(loc.address || '').trim()
  };
  text = locationPin.name || locationPin.address || '[Location pin shared]';
} else if (msg.type === "audio" || msg.type === "voice") {
  isVoice = true;
  mediaId = (msg.audio && msg.audio.id) || (msg.voice && msg.voice.id);
  text = "[Voice Note]";
} else if (msg.type === "interactive" && msg.interactive) {
  text = msg.interactive.button_reply ? msg.interactive.button_reply.title : (msg.interactive.list_reply ? msg.interactive.list_reply.title : "Interactive");
} else if (msg.type === "image" && msg.image) {
  // An empty caption must not become fake text: the image is analysed on its own.
  text = msg.image.caption || "";
  mediaId = msg.image.id;
} else if (msg.type === "document" && msg.document) {
  text = msg.document.caption || msg.document.filename || "Document";
  if (msg.document.mime_type && msg.document.mime_type.startsWith('image/')) {
    msg.type = "image";
    mediaId = msg.document.id;
  }
} else {
  text = msg.caption || "";
  if (!text) return [];
}

const senderPhone = String(msg.from || '').replace(/[^0-9]/g, '');
// The shop line this message arrived on, read from the webhook itself. Nothing invents it: an
// empty value is passed through as empty so the page can leave the chat links out rather than
// print somebody else's number on the merchant's shop.
const businessNumber = String((value && value.metadata && value.metadata.display_phone_number) || '').replace(/[^0-9]/g, '');
const hasImage = msg.type === "image" && Boolean(mediaId);
const userUploadedImage = hasImage ? mediaId : null;
const isTyped = String(text || '').trim().length > 0 && !isVoice;
// A photo the merchant sends with no words IS the message: it is a picture of what they sell.
// It is recorded on its own so "there was no caption" can never be read as "nothing was sent".
const imageCaption = (msg.type === "image" && msg.image)
  ? String(msg.image.caption || '').trim()
  : ((msg.type === "document" && msg.document) ? String(msg.document.caption || '').trim() : '');

return [{
  json: {
    senderPhone: senderPhone || '',
    businessPhone: businessNumber,
    extractedMessage: text,
    isVoice: isVoice,
    mediaId: mediaId,
    messageId: msg.id,
    rawMessage: msg,
    user_uploaded_image: userUploadedImage,
    has_image: hasImage,
    messageType: isLocationPin ? 'location' : (isVoice ? 'voice' : (hasImage ? 'image' : (isTyped ? 'text' : 'unknown'))),
    // The exact point the merchant shared, when they shared one. Nothing invents it.
    isLocationPin: isLocationPin,
    locationPin: locationPin,
    // The words that came with the picture, if any. Empty means the photo is the whole message.
    imageCaption: imageCaption,
    // Set once when a voice note cannot be understood, so the reply afterwards can explain
    // that typing or sending a photo still works. Nothing else in the run reads it.
    voiceRetryHint: false
  }
}];

// A buyer who confirms an order arrives from the storefront already carrying
// "Order Confirmed - ID: ORD-...". That id is read straight out of the message, so the
// conversation is mapped to the order row without anyone typing a phone number.
// No order id in the message means this is ordinary chatter: zero items, nothing written.
const item = $input.first().json || {};
const raw = String(item.extractedMessage || '');
const match = raw.match(/ORD-[A-Z0-9]+-[0-9]{3}/i);
const orderId = match ? match[0].toUpperCase() : '';
if (!orderId) return [];

// When the buyer clicked a Click-to-Chat link from an ad, WhatsApp attaches the referral.
// It is kept for the audit trail; it is never required.
const referral = (item.rawMessage && item.rawMessage.referral) ? item.rawMessage.referral : null;
const buyerPhone = String(item.senderPhone || '').replace(/[^0-9]/g, '');

return [{
  json: {
    row_key: buyerPhone + '|order|' + orderId,
    buyer_phone: buyerPhone,
    order_id: orderId,
    store_slug: String((referral && referral.source_url) || ''),
    state_type: 'ORDER_THREAD',
    state_json: JSON.stringify({
      order_id: orderId,
      message: raw.slice(0, 500),
      message_id: String(item.messageId || ''),
      source_url: String((referral && referral.source_url) || ''),
      ctwa_clid: String((referral && referral.ctwa_clid) || ''),
      confirmed_at: new Date().toISOString()
    }),
    updated_date: new Date().toISOString()
  }
}];

const item = $input.item;
if (item.binary && item.binary.data) {
  item.binary.data.fileName = "voice_note.ogg";
  item.binary.data.mimeType = "audio/ogg";
}
return [item];

// Groq Whisper is the voice engine on this path: the note is transcribed once, in the language
// that was actually spoken, and that text goes to the agent. Nothing else is asked of the audio.
const safe = (fn) => { try { return fn(); } catch (e) { return null; } };
const groq = safe(() => $('Whisper Speech-to-Text2').first().json);

const LANG_NAMES = { eng:'English', lug:'Luganda', nyn:'Runyankole', ach:'Acholi', teo:'Ateso', lgg:'Lugbara', myx:'Lumasaba', xog:'Lusoga', ttj:'Rutooro', cgg:'Rukiga', koo:'Rukonjo', ruc:'Ruruuli', swa:'Swahili', kin:'Kinyarwanda', fra:'French', ara:'Arabic', arb:'Arabic', zho:'Chinese', cmn:'Chinese', hin:'Hindi', spa:'Spanish', por:'Portuguese', deu:'German', rus:'Russian', jpn:'Japanese', kor:'Korean', ita:'Italian', nld:'Dutch', tur:'Turkish', som:'Somali', hau:'Hausa', yor:'Yoruba', ibo:'Igbo', zul:'Zulu', xho:'Xhosa', lin:'Lingala', sna:'Shona', amh:'Amharic', und:'Unknown' };
const NAME_TO_CODE = { english:'eng', luganda:'lug', ganda:'lug', nyankole:'nyn', runyankole:'nyn', acholi:'ach', ateso:'teo', lugbara:'lgg', lumasaba:'myx', soga:'xog', lusoga:'xog', tooro:'ttj', rutooro:'ttj', kiga:'cgg', rukiga:'cgg', swahili:'swa', kinyarwanda:'kin', french:'fra', arabic:'ara', chinese:'zho', hindi:'hin', spanish:'spa', portuguese:'por', german:'deu', russian:'rus', japanese:'jpn', korean:'kor', italian:'ita', dutch:'nld', turkish:'tur', somali:'som', amharic:'amh', hausa:'hau', yoruba:'yor', igbo:'ibo', zulu:'zul', xhosa:'xho', lingala:'lin', shona:'sna', indonesian:'ind' };

const rawGroqText = (groq && typeof groq.text === 'string') ? groq.text.trim() : '';
// WHISPER ANSWERS ITS OWN PROMPT.
// A prompt is sent with every transcription to pin the language and the spelling of prices. Groq's
// whisper-large-v3 echoes that prompt back on a silent or clipped tail: one note ended with " The",
// another ended with a whole sentence of the prompt itself. That echo was handed to the agent as if
// the merchant had said it, so a shop could be built from instructions nobody spoke. Only a run of
// words at the very END that appears verbatim in the prompt is cut, and the rest of the text is kept
// character for character - casing, punctuation and all - so a merchant quoting those words
// mid-sentence keeps them.
const PROMPT_WORDS = ('The audio may be spoken in any language in the world: English, Luganda, Runyankole, Acholi, Ateso, Lugbara, Swahili, Kinyarwanda, Somali, Amharic, Hausa, Yoruba, Arabic, Hindi, Chinese, French, Portuguese, Spanish, German, Russian, Turkish, Indonesian or any other. '
  + 'Transcribe exactly what is said, in the language that is spoken. '
  + 'Never translate into English. '
  + 'Keep product names and prices exactly as spoken. '
  + 'The speaker may have unclear or slow speech, so transcribe the words they intended rather than dropping what you cannot hear.')
  .toLowerCase().replace(/[^a-z0-9' ]+/g, ' ').replace(/ +/g, ' ').trim();
const stripPromptEcho = (text) => {
  let out = String(text || '');
  for (let guard = 0; guard < 20; guard++) {
    const words = out.match(/[A-Za-z0-9'’]+/g) || [];
    if (words.length < 2) break;
    // The longest run of trailing words that also appears verbatim inside the prompt.
    let cutWords = 0;
    for (let take = Math.min(words.length, 30); take >= 2; take--) {
      const probe = words.slice(words.length - take).map(w => w.toLowerCase()).join(' ');
      if ((' ' + PROMPT_WORDS + ' ').indexOf(' ' + probe + ' ') >= 0) { cutWords = take; break; }
    }
    if (!cutWords) break;
    // Where that run starts in the original text, so everything before it is left untouched.
    let idx = out.length;
    let counted = 0;
    while (idx > 0 && counted < cutWords) {
      idx--;
      if (/[A-Za-z0-9'’]/.test(out[idx]) && (idx === 0 || !/[A-Za-z0-9'’]/.test(out[idx - 1]))) counted++;
    }
    out = out.slice(0, idx).replace(/[s,;:-–]+$/, '').trim();
  }
  // A ONE-WORD TAIL SUCH AS "The" IS THE COMMONEST ECHO OF ALL - the prompt's own first word,
  // repeated on the silent end of a note. It is removed only when a finished sentence ends right
  // before it, so a merchant who really says "the" keeps it.
  const tailEcho = out.match(/^(.*[.!?])\s+(the|a|an|and|in|of|to|so)\s*$/i);
  if (tailEcho) out = tailEcho[1].trim();
  if (/^(the|a|and|in|of|to|so)$/i.test(out)) out = '';
  return out.trim();
};
const groqText = stripPromptEcho(rawGroqText);
const groqLooksLikeError = !!groq && (Boolean(groq.error) || Boolean(groq.detail)) && rawGroqText.length < 2;

// Whisper names the spoken language on every verbose_json answer. Turn that name into the code the
// rest of the flow already understands, and never guess it.
let language = '';
try {
  const spoken = String((groq && groq.language) || '').toLowerCase().trim();
  if (spoken) {
    if (/^[a-z]{3}$/.test(spoken)) {
      language = spoken;
    } else {
      const firstWord = spoken.split(/[^a-z]+/).filter(Boolean)[0] || '';
      if (NAME_TO_CODE[spoken]) language = NAME_TO_CODE[spoken];
      else if (firstWord && NAME_TO_CODE[firstWord]) language = NAME_TO_CODE[firstWord];
    }
  }
} catch (e) {}
if (!language) language = 'unknown';

let transcribed = groqText;
let engine = '';
if (transcribed.length > 1) engine = 'groq-whisper-large-v3';
else if (groqLooksLikeError) engine = 'whisper-unavailable';

// Remove hesitation noise only. Never strip content words: a short real answer
// such as "yes" or "3 bags" must survive untouched.
transcribed = transcribed.replace(/(^| )(you know|um+|uh+|er|ah)(?= |$)/gi, ' ').replace(/  +/g, ' ').trim();

// Confidence signals. Whisper verbose_json gives avg_logprob / no_speech_prob; the transcript's own
// shape is checked as well, because a model that heard nothing often answers with an apology.
let avgLogprob = null;
let bestLogprob = null;
let noSpeechProb = null;
try {
  const segs = (groq && Array.isArray(groq.segments)) ? groq.segments : [];
  // WEIGHT EACH SEGMENT BY THE WORDS IT ACTUALLY CONTAINS, so one hallucinated filler on the
  // silent tail of a note cannot drag a perfectly clear note down to low confidence.
  const scored = segs.map((s) => {
    const wordCount = String(s.text || '').trim().split(/ +/).filter(Boolean).length;
    return { logprob: (typeof s.avg_logprob === 'number' ? s.avg_logprob : null), words: wordCount };
  }).filter((s) => s.logprob !== null && s.words > 0);
  if (scored.length > 0) {
    const totalWords = scored.reduce((a, s) => a + s.words, 0);
    avgLogprob = scored.reduce((a, s) => a + (s.logprob * s.words), 0) / totalWords;
    bestLogprob = scored.reduce((a, s) => (s.logprob > a ? s.logprob : a), scored[0].logprob);
    const noSpeech = segs.map((s) => (typeof s.no_speech_prob === 'number' ? s.no_speech_prob : 0));
    noSpeechProb = Math.max.apply(null, noSpeech);
  }
} catch (e) {}

const looksLikeRefusal = /\b(i (can'?t|cannot|am unable)|cannot transcribe|no speech|unintelligible|inaudible|sorry,? i)\b/i.test(transcribed);
const words = transcribed.split(/\s+/).filter((w) => w.length > 0);
const shortTokens = words.filter((w) => w.replace(/[^\p{L}]/gu, '').length <= 1).length;
const gibberish = words.length >= 4 && (shortTokens / words.length) > 0.6;
const noLetters = transcribed.length > 0 && !/\p{L}/u.test(transcribed);

const CONFIDENT_LOGPROB = -0.8;
const NO_SPEECH_LIMIT = 0.6;

const issues = [];
if (looksLikeRefusal || noLetters) {
  issues.push('no speech detected');
} else if (transcribed.length < 2) {
  issues.push('no speech detected');
} else if (gibberish) {
  issues.push('transcript looks garbled');
} else if (avgLogprob === null && transcribed.length < 3) {
  issues.push('transcript too short to act on');
}
if (avgLogprob !== null && avgLogprob < CONFIDENT_LOGPROB) {
  // A weak average only disqualifies the note when no stretch of it was heard clearly.
  const heardClearly = (bestLogprob !== null && bestLogprob >= CONFIDENT_LOGPROB && words.length >= 4);
  if (!heardClearly) issues.push('low confidence ' + avgLogprob.toFixed(2));
}
if (noSpeechProb !== null && noSpeechProb > NO_SPEECH_LIMIT) issues.push('no clear speech ' + noSpeechProb.toFixed(2));

// Unreliable audio must never reach the agent as if it were the customer's words.
// extractedMessage stays empty so the retry branch answers instead of building.
const reliable = issues.length === 0;
const prevData = $('Parse WhatsApp Message').first().json;
return [{ json: { ...prevData, extractedMessage: reliable ? transcribed : '', voiceRetryHint: !reliable, transcriptionDraft: transcribed, transcriptionEngine: engine || 'none', transcriptionLanguage: language, transcriptionLanguageName: LANG_NAMES[language] || '', transcriptionReliable: reliable, transcriptionIssue: issues.join('; '), transcriptionConfidence: avgLogprob, transcriptionBestConfidence: bestLogprob, transcriptionNoSpeech: noSpeechProb } }];

const item = $input.first();
const prev = $('Parse WhatsApp Message').first().json || {};
const j = (item && item.json) || {};
const text = j.extractedMessage || prev.extractedMessage || '';
// Carry the language the voice pipeline actually detected, so the agent replies in it
// instead of inferring it from a transcript that may be short or code-switched.
const fromVoice = Boolean(j.transcriptionLanguage && j.transcriptionLanguage !== 'unknown' && j.transcriptionLanguageName);
const customerLanguage = fromVoice ? String(j.transcriptionLanguageName) : '';
// Photos the merchant has sent for this number, newest last. The agent attaches these to the
// products it is building or editing, so one item can carry several pictures.
const uploadedImages = Array.isArray(j.uploadedImageUrls) ? j.uploadedImageUrls : [];
const uploadedImageUrls = uploadedImages.length ? uploadedImages.join(' | ') : 'none';
// What the picture actually is, and which product it shows. The agent never saw the file, so
// this is the only thing that can stop it treating a product photo as a shop photo (or as an
// invitation to rebuild the shop).
const uploadedProductPhoto = String(j.uploadedProductPhoto || '').trim();
const uploadedProductName = String(j.uploadedProductName || '').trim();
const uploadedPhotoQuality = String(j.uploadedPhotoQuality || '').toUpperCase();
const imageRole = String(j.imageRole || '').toUpperCase();
const imageCaption = String(j.imageCaption || prev.imageCaption || '').trim();
// The picture, stated plainly for the prompt. "No picture" and "a picture with no caption" must
// never look the same to the agent: the second one is a complete message.
const imageFact = (imageRole || uploadedProductPhoto)
  ? ('A picture WAS sent with this message. ' +
     (imageRole === 'FLYER' || imageRole === 'LOGO'
       ? 'It is a flyer/logo - a design reference, not a product photo.'
       : ('It is a PRODUCT PHOTO of ' + (uploadedProductName || 'the item shown') + '.')) +
     (uploadedPhotoQuality === 'POOR' ? ' The photo is POOR QUALITY - but it is NOT rejected: the system redraws a clean picture of this same item and puts it on that product card, so it is applied normally and the merchant is NEVER asked to send the picture again.' : '') +
     (uploadedProductPhoto ? ' Hosted URL: ' + uploadedProductPhoto + '.' : '') +
     (imageCaption ? '' : ' There is NO caption: the picture alone is the whole message.'))
  : 'No picture was sent with this message.';
// The merchant's real point, when they dropped a pin. It is handed to the agent as a fact so
// the agent never has to guess where the shop is, and so a typed "I am in Banda" cannot
// override a location the merchant physically pinned.
const pin = (j.locationPin && typeof j.locationPin.lat === 'number' && typeof j.locationPin.lng === 'number') ? j.locationPin : null;
const customerLocationPin = pin ? { lat: pin.lat, lng: pin.lng, name: pin.name || '', address: pin.address || '' } : null;
const customerLocationText = pin ? (pin.name || pin.address || 'shared location pin') : '';
// One clean item per inbound message: the agent must never run twice for one user message.
return [{ json: { ...prev, ...j, senderPhone: j.senderPhone || prev.senderPhone || '', businessPhone: j.businessPhone || prev.businessPhone || '', extractedMessage: text, customerLanguage: customerLanguage, customerLanguageFromVoice: fromVoice, uploadedImageUrls: uploadedImageUrls, uploadedImageCount: uploadedImages.length, uploadedProductPhoto: uploadedProductPhoto, uploadedProductName: uploadedProductName, uploadedPhotoQuality: uploadedPhotoQuality, imageRole: imageRole, imageFact: imageFact, merchantPhotoRecords: j.merchantPhotoRecords || [], customerLocationPin: customerLocationPin, customerLocationText: customerLocationText } }];

// One item in, one item out - and an EMPTY result for a message that was already handled.
// Zero items ends the branch, so a WhatsApp retry or a double tap produces no second reply
// and no second shop rebuild. A second input item is never introduced, because that would
// make every outbound node below send its message twice.
const item = $input.first().json || {};

// Manual runs (the Execute button, demo replays of a pinned payload) always walk the whole
// chain. The dedupe window below exists to stop WhatsApp retries from double-replying in
// production, and those always arrive as webhook executions.
if ($execution.mode === 'manual') return [{ json: { ...item, duplicateMessage: false } }];

const messageId = String(item.messageId || '').trim();
if (!messageId) return [{ json: { ...item, duplicateMessage: false } }];

const sd = $getWorkflowStaticData('global');
if (!sd.seenMessageIds || typeof sd.seenMessageIds !== 'object') sd.seenMessageIds = {};
const seen = sd.seenMessageIds;

// A short rolling window keeps the record small and still catches retries and double sends.
const now = Date.now();
for (const k of Object.keys(seen)) {
  if (!seen[k] || (now - seen[k]) > 1800000) delete seen[k];
}

if (seen[messageId]) {
  // Already answered. End the branch here, silently.
  return [];
}
seen[messageId] = now;

return [{ json: { ...item, duplicateMessage: false } }];

// The message item comes from the node that produced it, NOT from $input: the catalogue lookup
// in front of this one returns a single empty {} when the merchant has no saved row yet, and
// taking $input.first() there threw away the sender, the text and everything the agent needs.
let prev = {};
try {
  prev = $('Suppress Repeat Message1').first().json || {};
} catch (e) {}
if (!prev || !prev.senderPhone) {
  try { prev = $('Prepare Agent Input').first().json || {}; } catch (e) {}
}
if (!prev || !prev.senderPhone) {
  // Last resort only: never let an empty lookup upstream blank the message.
  const inItem = $input.first() && $input.first().json ? $input.first().json : {};
  if (inItem && inItem.senderPhone) prev = inItem;
}
const phone = String(prev.senderPhone || '').replace(/[^0-9]/g, '');

// The catalogue is the authority: it is written every time a shop is built or edited.
let rows = [];
try { rows = $('Lookup Saved Catalogue1').all().map(r => r.json || {}); } catch (e) {}
// ONE NUMBER CAN OWN MANY SHOPS, and every one of them has its own catalogue row. Taking the
// first row that has a catalogue handed the agent another business's products, so a merchant saw
// items they never mentioned and old items from past chats. Only a row belonging to the shop in
// this conversation is used: matched on the slug this message names, then on the slug the number
// currently serves, then only when a single row exists. Never the row order.
const catPhone = (e) => String(e && e.merchant_phone || '').replace(/[^0-9]/g, '');
const catSlug = (e) => String(e && e.store_slug || '').trim();
const phoneMatches = (e) => { const t = catPhone(e); return !phone || !t || t.slice(-9) === phone.slice(-9); };
// EVERY BUSINESS ON THIS NUMBER, from BOTH tables. The catalogue is not the only record of a
// shop: a site whose catalogue row was cleaned up (or never written because a save failed) still
// exists in the store table and is still a live website. Listing shops from the catalogue alone
// made a two-shop number look like a single shop, and the store-row fallback then edited whichever
// row came first - the merchant asked for one business by name and a different one was rebuilt.
const storeShops = [];
try {
  for (const r of $('Lookup Store By Phone1').all()) {
    const j = r.json || {};
    const rp = String(j.phone || j.senderPhone || '').replace(/[^0-9]/g, '');
    if (phone && rp && rp.slice(-9) !== phone.slice(-9)) continue;
    const sl = String(j.slug || '').trim();
    if (!sl || storeShops.some((s) => s.slug === sl)) continue;
    storeShops.push({ slug: sl, name: String(j.merchant_name || j.Name || j.name || sl).trim(), row: j });
  }
} catch (e) {}
const msgLowerAll = String(prev.extractedMessage || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
// Does the merchant's own sentence name this business? Read the typed words, never the agent's
// guess, so an unnamed edit cannot be pinned to whichever shop the model happened to mention.
const shopMentioned = (nm) => {
  if (!msgLowerAll || !nm) return false;
  const k = String(nm).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  if (k.length < 3) return false;
  if (msgLowerAll.indexOf(k) >= 0) return true;
  const words = k.split(' ').filter((w) => w.length > 2 && !/^[0-9]+$/.test(w));
  return words.length > 0 && words.every((w) => msgLowerAll.indexOf(w) >= 0);
};
// How many DISTINCT websites this number owns, counting both tables.
const allSlugs = rows.filter(phoneMatches).map(catSlug).concat(storeShops.map((s) => s.slug))
  .filter(Boolean).filter((v, i, a) => a.indexOf(v) === i);
const askedSlug = String(prev.activeSlug || prev.requestedSlug || prev.slugHint || '').trim();
let row = null;
let shopChoiceNeeded = false;
let namedStoreShop = null;
if (rows.length) {
  // ONE ROW PER BUSINESS, even after an address change. A shop whose slug was corrected used to
  // leave its old catalogue row behind, so the same business appeared twice and an edit could land
  // on the stale copy. Rows for one business name are collapsed to the most recently written one.
  // The address the store table is actually serving for this number. When a business owns two
  // catalogue rows, THIS is the copy a buyer sees, so it wins over whichever row was written last.
  const servingSlugEarly = (() => {
    try {
      for (const r of $('Lookup Store By Phone1').all()) {
        const j = r.json || {};
        const rp = String(j.phone || j.senderPhone || '').replace(/[^0-9]/g, '');
        if (j.slug && (!phone || !rp || rp.slice(-9) === phone.slice(-9))) return String(j.slug).trim();
      }
    } catch (e) {}
    return '';
  })();
  const nameKeyOf = (r) => {
    let nm = String((r && r.merchant_name) || '').trim();
    if (!nm) { try { nm = String((JSON.parse(String((r && r.catalogue_json) || '{}')) || {}).merchant_name || '').trim(); } catch (e) {} }
    return nm.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  };
  const stampOf = (r) => String((r && (r.updated_date || r.updatedAt || r.createdAt)) || '');
  const newestByName = new Map();
  rows.forEach((r) => {
    if (!r || !phoneMatches(r)) return;
    const k = nameKeyOf(r);
    if (!k) return;
    const seen = newestByName.get(k);
    const rServing = Boolean(servingSlugEarly) && catSlug(r) === servingSlugEarly;
    const seenServing = Boolean(servingSlugEarly) && Boolean(seen) && catSlug(seen) === servingSlugEarly;
    if (!seen || (rServing && !seenServing) || (rServing === seenServing && stampOf(r) > stampOf(seen))) newestByName.set(k, r);
  });
  const seenKeys = new Set();
  const live = rows.filter((r) => {
    if (!r || !r.catalogue_json || !phoneMatches(r)) return false;
    return newestByName.get(nameKeyOf(r)) === r;
  }).filter((r) => {
    const sl = catSlug(r);
    if (!sl) return true;
    if (seenKeys.has(sl)) return false;
    seenKeys.add(sl);
    return true;
  });
  const servingSlug = (() => {
    try {
      for (const r of $('Lookup Store By Phone1').all()) {
        const j = r.json || {};
        const rp = String(j.phone || j.senderPhone || '').replace(/[^0-9]/g, '');
        if (j.slug && (!phone || !rp || rp.slice(-9) === phone.slice(-9))) return String(j.slug).trim();
      }
    } catch (e) {}
    return '';
  })();
  // WHICH WEBSITE IS THIS MESSAGE ABOUT? One number can own several shops, and picking the row
  // that happens to be first - or whichever shop was read last - is exactly how two businesses
  // ended up sharing one page. The shop the message NAMES wins; a single shop is always safe;
  // with several shops and none named we ask instead of guessing.
  const msgLower = msgLowerAll;
  const namesShop = (r) => {
    if (!msgLower) return false;
    const nm = String(r.merchant_name || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    if (nm.length > 2 && msgLower.indexOf(nm) >= 0) return true;
    const slWords = catSlug(r).toLowerCase().replace(/-/g, ' ').split(' ').filter((w) => w.length > 2 && !/^[0-9]+$/.test(w));
    return slWords.length > 0 && slWords.every((w) => msgLower.indexOf(w) >= 0);
  };
  // An item name identifies its shop just as well as the business name: "change the silk dress"
  // is unambiguously the fashion shop, even with three sites on this number.
  const namesAnItem = (r) => {
    if (!msgLower) return false;
    let list = [];
    try { list = (JSON.parse(String(r.catalogue_json || '{}')) || {}).products_and_services || []; } catch (e) { list = []; }
    return list.some((it) => {
      const nm = String((it && it.name) || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
      if (!nm) return false;
      if (msgLower.indexOf(nm) >= 0) return true;
      const words = nm.split(' ').filter((w) => w.length >= 4);
      return words.length > 0 && words.some((w) => msgLower.indexOf(w) >= 0);
    });
  };
  let namedRow = null;
  for (const r of live) { if (namesShop(r)) { namedRow = r; break; } }
  if (!namedRow) { for (const r of live) { if (namesAnItem(r)) { namedRow = r; break; } } }
  if (namedRow) row = namedRow;
  if (!row && askedSlug) row = live.find((r) => catSlug(r) === askedSlug) || null;
  if (!row && live.length === 1) row = live[0];
}
// THIS RUNS EVEN WHEN THE CATALOGUE TABLE IS EMPTY.
// A website can exist only in the store table - its catalogue row was cleaned up, or a save failed
// after the page went live. Those shops still belong to this number, so the name match and the
// "which website?" question must work without a single catalogue row. Otherwise a two-shop number
// looked like a one-shop number and the store-row fallback edited whichever row came first.
if (!row) {
  const namedStore = storeShops.find((s) => shopMentioned(s.name) || shopMentioned(String(s.slug).replace(/-/g, ' ')));
  if (namedStore) namedStoreShop = namedStore;
}
if (!row && !namedStoreShop && allSlugs.length > 1) { row = null; shopChoiceNeeded = true; }

let catalogue = null;
if (row) {
  try { catalogue = JSON.parse(String(row.catalogue_json)); } catch (e) {}
}

let slug = row ? String(row.store_slug || '') : '';
let merchantName = row ? String(row.merchant_name || '') : '';
let productCount = Array.isArray(catalogue && catalogue.products_and_services) ? catalogue.products_and_services.length : 0;

// A store saved before the catalogue table existed still exists in the store table. The rows come
// from Lookup Store By Phone1, which runs BEFORE the agent so the shop is known on the first turn.
// (It used to read Lookup Store in Baserow1, a node that only runs after the storefront has been
// rebuilt, so on the live path this fallback could never fire.)
// NOTE: no backticks in this comment - it lives inside a JS template literal.
let storeRow = null;
if (!slug && namedStoreShop) {
  // The merchant named this shop, and it lives only in the store table.
  storeRow = namedStoreShop.row;
  slug = String(namedStoreShop.slug).trim();
  merchantName = String(namedStoreShop.name || namedStoreShop.slug).trim();
}
if (!slug) {
  try {
    for (const r of $('Lookup Store By Phone1').all()) {
      const j = r.json || {};
      const rowPhone = String(j.senderPhone || j.phone || '').replace(/[^0-9]/g, '');
      if (j.slug && phone && rowPhone.slice(-9) === phone.slice(-9)) {
        storeRow = j;
        slug = String(j.slug).trim();
        merchantName = String(j.merchant_name || j.Name || j.name || merchantName || slug).trim();
        break;
      }
    }
  } catch (e) {}
}

// The shop page exists but its catalogue row is gone (a rebuild that failed before the save, or a
// shop built before the catalogue table was added). Report the shop as it really is, with what the
// store row itself knows, instead of telling the merchant they have nothing.
if (slug && (!catalogue || !Array.isArray(catalogue.products_and_services) || catalogue.products_and_services.length === 0)) {
  catalogue = {
    merchant_name: merchantName || slug,
    location: String((storeRow && storeRow.location) || (catalogue && catalogue.location) || ''),
    business_category: String((storeRow && storeRow.business_category) || (catalogue && catalogue.business_category) || ''),
    products_and_services: Array.isArray(catalogue && catalogue.products_and_services) ? catalogue.products_and_services : []
  };
  productCount = catalogue.products_and_services.length;
}

// The shop is live at this very URL, whatever the address looks like - the stored page and the
// saved catalogue both belong to this number.
const hasShop = Boolean(slug);
const shopUrl = slug ? ('https://orchid-frigatebird.pikapod.net/webhook/storefront?slug=' + slug) : '';

let allShops = [];
try {
  // The list a merchant is shown must have one line per BUSINESS, not per leftover catalogue row:
  // a corrected address used to show the same shop twice. Keep the newest row per business name.
  const seenSlugs = {};
  const keptNames = {};
  // The address the store table is serving for this number is the copy buyers actually see, so it
  // is listed first and wins any tie. Remaining rows are newest-first.
  let servingSlugNow = '';
  try {
    for (const r of $('Lookup Store By Phone1').all()) {
      const j = r.json || {};
      const rp = String(j.phone || j.senderPhone || '').replace(/[^0-9]/g, '');
      if (j.slug && (!phone || !rp || rp.slice(-9) === phone.slice(-9))) { servingSlugNow = String(j.slug).trim(); break; }
    }
  } catch (e) {}
  const ranked = rows.filter((r) => r && phoneMatches(r) && catSlug(r)).sort((a, b) => {
    if (servingSlugNow) {
      const as = catSlug(a) === servingSlugNow ? 1 : 0;
      const bs = catSlug(b) === servingSlugNow ? 1 : 0;
      if (as !== bs) return bs - as;
    }
    const sa = String(a.updated_date || a.updatedAt || a.createdAt || '');
    const sb = String(b.updated_date || b.updatedAt || b.createdAt || '');
    return sb > sa ? 1 : (sb < sa ? -1 : 0);
  });
  ranked.forEach((r) => {
    const sl = catSlug(r);
    if (!sl || seenSlugs[sl]) return;
    let nm = String(r.merchant_name || '').trim();
    if (!nm) { try { nm = String((JSON.parse(String(r.catalogue_json || '{}')) || {}).merchant_name || '').trim(); } catch (e) {} }
    const nmKey = String(nm || sl).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    if (nmKey && keptNames[nmKey]) return;
    if (nmKey) keptNames[nmKey] = true;
    seenSlugs[sl] = true;
    allShops.push({ slug: sl, name: nm || sl });
  });
  // Websites that exist only in the store table are still this number's shops, and must be shown
  // in the "which one?" question. Leaving them out is what let a second business sit on the number
  // invisibly while an edit was applied to the first.
  storeShops.forEach((s) => {
    if (seenSlugs[s.slug]) return;
    const nmKey = String(s.name || s.slug).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    if (nmKey && keptNames[nmKey]) return;
    if (nmKey) keptNames[nmKey] = true;
    seenSlugs[s.slug] = true;
    allShops.push({ slug: s.slug, name: s.name || s.slug });
  });
} catch (e) { allShops = []; }

// ── HOW MANY WEBSITES THIS NUMBER OWNS, AND HOW MANY IT MAY STILL BUILD ─────
// Every number gets TWO free websites. The count is taken from the shops that really exist (in
// both tables), so a shop whose catalogue row was cleaned up still counts against the allowance
// and a merchant can never end up with three pages by accident. The list is carried to the agent
// so it knows the difference between "build me another website" and "change the one I have".
const SITE_ALLOWANCE = 2;
const siteList = allShops.map((s) => ({
  name: String(s.name || s.slug),
  slug: String(s.slug),
  url: 'https://orchid-frigatebird.pikapod.net/webhook/storefront?slug=' + String(s.slug)
}));
if (hasShop && !siteList.some((s) => s.slug === slug)) {
  siteList.unshift({ name: String(merchantName || slug), slug: slug, url: shopUrl });
}
const siteCount = siteList.length;

let savedShop = { has_shop: false };
if (hasShop) {
  savedShop = {
    has_shop: true,
    merchant_name: merchantName || (catalogue && catalogue.merchant_name) || slug,
    slug: slug,
    shop_url: shopUrl,
    product_count: productCount,
    products: Array.isArray(catalogue && catalogue.products_and_services) ? catalogue.products_and_services.map(p => p && p.name).filter(Boolean) : [],
    promotion: String((catalogue && catalogue.promotion) || (row && row.promotion) || ''),
    location: String((catalogue && catalogue.location) || ''),
    background_color: String((catalogue && catalogue.background_color) || ''),
    catalogue: catalogue,
    catalogue_row_key: row ? String(row.row_key || '') : '',
    catalogue_slug: row ? catSlug(row) : slug,
    other_shops: allShops.filter((sh) => sh.slug !== slug).map((sh) => sh.name),
    site_count: siteCount,
    site_allowance: SITE_ALLOWANCE,
    sites_left: Math.max(0, SITE_ALLOWANCE - siteCount),
    site_list: siteList,
    // THE SHOP WAS NOT CHOSEN. Several websites exist, this message named none, and the slug below
    // came only from the store table's own row - which is one of them, not necessarily the one the
    // merchant meant. That is reported so the caller asks which website instead of editing the
    // wrong business. Without this flag the store-row fallback made a 3-shop number look like a
    // single shop, and an unnamed edit silently landed on one merchant's site.
    several_shops: allShops.length > 1 ? true : undefined,
    needs_shop_choice: (allShops.length > 1 && shopChoiceNeeded) ? true : undefined,
    shops: allShops.length > 1 ? allShops : undefined
  };
} else if (allShops.length > 1) {
  // More than one website on this number and this message named none of them: the caller must ask
  // which shop, so an edit can never land on the wrong business.
  savedShop = {
    has_shop: false,
    several_shops: true,
    needs_shop_choice: shopChoiceNeeded,
    shops: allShops,
    catalogue_row_key: '',
    catalogue_slug: '',
    site_count: siteCount,
    site_allowance: SITE_ALLOWANCE,
    sites_left: Math.max(0, SITE_ALLOWANCE - siteCount),
    site_list: siteList
  };
}

return [{ json: { ...prev, savedShop: savedShop } }];

const item = $input.first().json || {};
const text = String(item.extractedMessage || '').trim().toLowerCase();
const phone = String(item.senderPhone || '').replace(/[^0-9]/g, '');

// Only an explicit instruction counts, and it has to be about the memory or the saved data -
// not a passing word. "wipe the page", "start again", "reset the shop", "delete everything".
//
// THE SUBJECT IS WHAT DECIDES, NOT A WORD FLYING PAST IN A SENTENCE.
// This used to be a plain "a verb anywhere AND a target anywhere" test. The text handed here is
// not only what the merchant typed: once a picture has been read, the message also carries the
// image hand-off line and the whole vision answer. So "remove it" sent WITH a photo read as verb
// "remove" + target "products" and the run took the memory-wipe exit - the shop and its catalogue
// were cleared and the merchant was told "Memory cleared for this number" instead of the picture
// being removed. The match is now made on the merchant's own words, and a target only counts when
// the shop, the memory or everything is what they asked to clear.
const ownWords = String(item.extractedMessage || item.imageCaption || '')
  .replace(/^\s*\[customer typed\]\s*:?/i, ' ')
  .replace(/\[[^\]]*\]/g, ' ')
  .trim()
  .toLowerCase();
const purgeVerb = /(^|[^a-z])(wipe|erase|purge|forget|reset|clear)([^a-z]|$)/.test(ownWords)
  || /(start (again|over)|from scratch|delete everything|remove everything|clear everything)/i.test(ownWords);
const purgeTarget = /(^|[^a-z])(memory|memories|everything|shop|store|storefront|website|site|catalogue|catalog|records?|history)([^a-z]|$)/.test(ownWords)
  || /(my|the) (shop|store|website|site|page|catalogue|catalog|memory|data|records)/i.test(ownWords);
// "REMOVE THE PHOTO" IS NOT "CLEAR MY SHOP". Plain "remove" and "delete" are what a merchant types
// about one product, one picture or one price far more often than about the whole shop, so neither
// is a wipe verb any more. Only the words above, aimed at the shop itself, can clear anything.
const wantsPurge = purgeVerb && purgeTarget;
if (!wantsPurge) {
  return [{ json: { ...item, memoryPurged: false } }];
}
// A wipe REQUEST is honoured even when nothing is left to delete. Deciding on what happened to be
// stored meant a second "wipe everything" fell through and rebuilt the shop from old chat memory.
if (!phone) {
  return [{ json: { ...item, memoryPurged: true, memoryClearedKeys: '' } }];
}

let cleared = [];
try {
  const sd = $getWorkflowStaticData('global');

  // Which shops belong to this number. Only their keys are removed.
  const entry = sd.merchants && sd.merchants[phone] ? sd.merchants[phone] : null;
  const ownSlugs = [];
  if (entry) {
    if (Array.isArray(entry.stores)) entry.stores.forEach(st => { if (st && st.slug) ownSlugs.push(String(st.slug)); });
    if (entry.currentSlug) ownSlugs.push(String(entry.currentSlug));
    if (entry.savedStore && entry.savedStore.slug) ownSlugs.push(String(entry.savedStore.slug));
  }
  if (sd.merchants && sd.merchants[phone]) { delete sd.merchants[phone]; cleared.push('merchants'); }

  // The built pages this number published. Another merchant's page is left alone.
  if (sd.stores) {
    ownSlugs.forEach(s => { if (sd.stores[s]) { delete sd.stores[s]; cleared.push('page:' + s); } });
  }

  // The photo archive, keyed number|shop, and the same key without a shop suffix.
  const keys = [phone].concat(ownSlugs.map(s => phone + '|' + s));
  if (sd.merchantPhotos) {
    keys.forEach(k => { if (sd.merchantPhotos[k]) { delete sd.merchantPhotos[k]; cleared.push('photos:' + k); } });
  }
  if (sd.merchantPhotoRecords) {
    keys.forEach(k => { if (sd.merchantPhotoRecords[k]) { delete sd.merchantPhotoRecords[k]; cleared.push('photoRecords:' + k); } });
  }

  // The platform-wide ledger of search pictures. It only ever holds OTHER shops' pictures from this
  // merchant's point of view, so wiping it for one merchant risks a small repeat for the rest -
  // which the per-shop rules already refuse. Only dropped when the merchant is wiping everything.
  if (/\b(everything|all|memory|memories|reset|wipe it all)\b/.test(text)) {
    if (Array.isArray(sd.usedSearchImages) && sd.usedSearchImages.length) {
      sd.usedSearchImages = [];
      cleared.push('imageLedger');
    }
  }
} catch (e) {}

// wipesRequested tells the router this is an explicit wipe even if the store was already empty.
return [{ json: { ...item, memoryPurged: true, memoryWipeRequested: true, memoryClearedKeys: cleared.join(',') } }];

