parameters.jsCode:
const prev = $('Prepare Agent Input').first().json || {};
const raw = $('X-Link Guardrail Engine1').first().json.output;
let intent = 'UNKNOWN';
try {
  const str = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const a = str.indexOf('{');
  const b = str.lastIndexOf('}');
  if (a !== -1 && b > a) {
    const obj = JSON.parse(str.substring(a, b + 1));
    if (obj && obj.intent) intent = String(obj.intent);
  }
} catch (e) {}
// A buyer who came in from the storefront says which order they are here about. That message is
// a hand-off, not a shop change: it is flagged here so the shop is never rebuilt because of it.
const orderRef = String(prev.extractedMessage || '').match(/ORD-[A-Z0-9]+-[0-9]{3}/i);
const orderThreadId = orderRef ? orderRef[0].toUpperCase() : '';
// Keep the raw reply on the item so the next node can still read it as before.
return [{ json: { ...prev, output: raw, intent: intent, orderThreadId: orderThreadId, isOrderThread: Boolean(orderThreadId) } }];

// Insights used to reply with a link to a page that does not exist, so the merchant was shown
// an address that went nowhere. The numbers are now read from this merchant's own orders and
// reported as plain counts - no link is invented.
const NL = String.fromCharCode(10);
const shop = (() => {
  try { return $('Attach Saved Shop1').first().json.savedShop || {}; } catch (e) { return {}; }
})();
let phone = '';
try { phone = String($('Parse WhatsApp Message').first().json.senderPhone || ''); } catch (e) {}

const say = (msg, extra) => [{ json: { senderPhone: phone, whatsapp_reply: msg, ...(extra || {}) } }];

// Several websites on one number and this message named none of them: ask, never guess.
if (shop && shop.several_shops && shop.needs_shop_choice) {
  const names = (shop.shops || []).map(s => '• ' + String(s.name || s.slug || '')).join(NL);
  return say('You have ' + (shop.shops || []).length + ' websites on this number:' + NL + names + NL + NL + 'Which one do you want the numbers for?');
}

// No shop at all: say so plainly rather than pointing at a page that does not exist.
if (!shop || shop.has_shop !== true) {
  return say('There is no website on this number yet, so there is nothing to report. Send me your business name, where you are and what you sell, and I will build it.');
}

const slug = String(shop.catalogue_slug || shop.slug || '').trim();
const shopName = String(shop.merchant_name || slug).trim();

let rows = [];
try {
  rows = $input.all().map(i => i.json || {}).filter(r => Object.keys(r).length > 0);
} catch (e) { rows = []; }
// Only this shop's orders, whatever the table returned.
rows = rows.filter(r => !slug || String(r.slug || '') === slug);

const money = (n) => {
  const v = Number(n) || 0;
  return 'USh ' + Math.round(v).toLocaleString('en-US', { maximumFractionDigits: 0 });
};

if (!rows.length) {
  const liveUrl = String(shop.shop_url || '');
  return say('📊 *' + shopName + '* has no sales recorded yet.' + NL + NL +
    (shop.product_count ? 'You have ' + shop.product_count + ' item(s) on the website.' + NL : '') +
    (liveUrl ? 'Your website: ' + liveUrl : ''));
}

const paid = rows.filter(r => String(r.status || '').toUpperCase() === 'PAID');
const pending = rows.filter(r => /PENDING|AWAITING/i.test(String(r.status || '')));
let revenue = 0;
paid.forEach(r => { revenue += Number(r.amount_usd) || 0; });

// The best-selling item name, from the saved items summary of paid orders.
const tally = {};
paid.forEach(r => {
  String(r.items_summary || '').split(/[,;]/).forEach(part => {
    const m = part.trim().match(/^(.*?)s*(?:xs*(d+))?$/);
    if (!m) return;
    const item = m[1].replace(/d+/g, '').replace(/[^a-z0-9 &'-]/gi, '').trim();
    if (!item) return;
    tally[item] = (tally[item] || 0) + (Number(m[2]) || 1);
  });
});
const top = Object.keys(tally).sort((a, b) => tally[b] - tally[a])[0];

const lines = [
  '📊 *' + shopName + ' - your numbers*',
  '',
  '• Orders received: ' + rows.length,
  '• Paid orders: ' + paid.length,
  '• Money collected: ' + money(revenue),
  '• Waiting for payment: ' + pending.length
];
if (top) lines.push('• Best seller: ' + top);
if (shop.product_count) lines.push('• Items on the website: ' + shop.product_count);
if (shop.shop_url) { lines.push(''); lines.push('Your website: ' + String(shop.shop_url)); }

return say(lines.join(NL), { slug: slug, orders: rows.length, paid: paid.length, revenue_usd: revenue });

// The agent's answer is read by node name: a lookup step now sits between the agent and
// this node, so $input is that lookup's result, not the agent's JSON.
let raw = "";
try { raw = $('Parse Agent Intent').first().json.output || ''; } catch (e) { raw = ''; }
let parsed = null;

if (typeof raw === 'object' && raw !== null) {
  parsed = raw;
} else {
  const rawStr = String(raw).trim();
  const firstBrace = rawStr.indexOf('{');
  const lastBrace = rawStr.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    try {
      parsed = JSON.parse(rawStr.substring(firstBrace, lastBrace + 1));
    } catch (e) {}
  }
}

const prev = $('Parse WhatsApp Message').first().json;
