} catch (e) {}
let phone = prev.senderPhone || '';
let extractedMessage = prev.extractedMessage || "";

// The static edit confirmation is assembled from a real before/after comparison of the shop, so
// these carry that result out of the merge step to the reply below.
let editChangeList = [];
let editOtherChanges = [];
let editAppliedNames = [];
let freshPhoto = '';
let freshPhotoItem = '';
// WHICH ITEMS THIS MESSAGE IS ACTUALLY ABOUT.
// A merchant who changes one thing must see only that thing change. "Change the photo on the
// iPhone" used to travel the whole picture pipeline, so every other card was searched and redrawn
// as well and the shop came back with different pictures the merchant never asked for. These
// lists carry the scope of the edit out of this step: the items the merchant named, and the items
// whose photo they asked to place, remove or replace. Nothing outside them is touched.
let editTouchedKeys = [];
let editPhotoKeys = [];
// The price this edit decided per card, carried out of the merge so the later price pass cannot
