let editPicturesUntouched = false;
// True when the merchant named no item at all ("make my background black", "change the story").
// A shop-level edit changes no card, so every card keeps the picture it already shows.
let editItemless = false;
// Pictures this message took off the shop, so the receipt can say so honestly.
let photoRemoved = [];
let editConfirmReply = '';
let editConfirmLines = [];
let editConfirmIssue = '';
// True when this message builds a DIFFERENT business on a number that already owns a website.
