let isNewSiteBuild = false;
let orderIssue = '';
let isEditRequest = false;

const slugify = (v) => String(v || '').toLowerCase().replace(/&/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const normalize = (v) => String(v || '').toLowerCase().replace(/[^a-z0-9]/g, '');

// ── WHAT PRICE DID THE MERCHANT ACTUALLY MEAN? ────────────────────────────────
// A merchant prices by hand, and writes it the way people speak: "50k", "50K", "UGX 50k",
// "shs 50k", "50 thousand", "fifty thousand", "1.5m", "50,000", "50.000". Every one of those is
// a real price and every one has to land on the card as a number the page can charge.
// Two different readers used to do this job, and both were wrong in different ways:
//   - one kept only digits and a trailing k/m, so "50 thousand" became 50 and "50.000" became 50;
//   - the other stripped everything but digits and a dot, so "50k" became 50 and "1.5m" became 1.5.
// There is now ONE reader, used everywhere, and it reads the figure, the multiplier word, a dot
// used as a thousands separator, a grouping space, a range, and a price spelled out in words.
const readPrice = (v) => {
    if (typeof v === 'number') return isFinite(v) ? v : 0;
    let s = String(v === undefined || v === null ? '' : v).toLowerCase().replace(/\u00a0/g, ' ').replace(/,/g, '');
    if (!s.trim()) return 0;
    // "1 500 000" is one figure with spaces for grouping, not three figures.
    s = s.replace(/ (?=\d{3}(\D|$))/g, '');
    const MULT = {
        k: 1000, ks: 1000, thousand: 1000, thousands: 1000, thou: 1000, ths: 1000, grand: 1000,
        m: 1000000, mn: 1000000, mil: 1000000, mill: 1000000, million: 1000000, millions: 1000000,
        bn: 1000000000, billion: 1000000000
    };
    // The multiplier word that belongs to a figure: "50k" is its own word, "50 thousand" is the
    // next one. "Ksh" and "ugx" are currency words, never multipliers, so they are not matched.
    const factorOfWord = (w) => {
        if (!w) return 0;
        if (Object.prototype.hasOwnProperty.call(MULT, w)) return MULT[w];
        if (w.length > 1 && MULT[w.charAt(0)] > 1) return MULT[w.charAt(0)];
        return 0;
    };
    const nums = s.match(/\d[\d.]*/g);
    if (nums && nums.length) {
        const tailWord = (rawNum) => {
            const at = s.indexOf(rawNum);
            if (at < 0) return '';
            const m = s.slice(at + rawNum.length).match(/^ *([a-z]+)/);
            return m ? m[1] : '';
        };
        let raw = nums[0];
        let factor = factorOfWord(tailWord(raw));
        // "50-60k" and "50k-60k" mean a range; the honest figure is the lower end, so the shop
        // never advertises a price above what the merchant actually asked for.
        if (!factor) {
            for (let i = nums.length - 1; i > 0; i--) {
                const f = factorOfWord(tailWord(nums[i]));
                if (f) { factor = f; break; }
            }
        }
        if (!factor) factor = 1;
        // A dot used as a thousands separator: "50.000" and "5.000.000" are shillings, not
        // fifty and five. A real decimal (1.5, 45.50) is left alone.
        if (factor === 1 && /^\d{1,3}(\.\d{3})+$/.test(raw)) raw = raw.replace(/\./g, '');
        const n = parseFloat(raw);
        if (isFinite(n)) return n * factor;
    }
    // A price spelled in words. "fifty thousand" is 50000, and refusing it left the card on
    // "Ask the merchant for the price" while the merchant had told us the price plainly.
    const WORD = {
        zero: 0, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9,
        ten: 10, eleven: 11, twelve: 12, thirteen: 13, fourteen: 14, fifteen: 15, sixteen: 16,
        seventeen: 17, eighteen: 18, nineteen: 19, twenty: 20, thirty: 30, forty: 40, fifty: 50,
        sixty: 60, seventy: 70, eighty: 80, ninety: 90
    };
    let total = 0;
    let current = 0;
    let found = false;
    s.split(/[^a-z]+/).forEach((w) => {
        if (!w) return;
        if (Object.prototype.hasOwnProperty.call(WORD, w)) { current += WORD[w]; found = true; return; }
        if (w === 'hundred') { current = (current || 1) * 100; found = true; return; }
        if (w === 'thousand') { total += (current || 1) * 1000; current = 0; found = true; return; }
        if (w === 'million') { total += (current || 1) * 1000000; current = 0; found = true; }
    });
    total += current;
    return found && isFinite(total) ? total : 0;
};

// A merchant can run many businesses on one number, so stores are kept as a LIST per phone.
let stores = [];
try {
  const staticData = $getWorkflowStaticData('global');
  const entry = staticData && staticData.merchants ? staticData.merchants[phone] : null;
  if (entry) {
    if (Array.isArray(entry.stores)) stores = [];
    else if (entry.savedStore) stores = [entry.savedStore];   // migrate the old single-store shape
    // One business per number: the store this number owns is the single source of truth, so a
    // stale second entry can never overwrite the shop the merchant is looking at.
    const current = entry.currentSlug ? (entry.stores || []).find((st) => st && st.slug === entry.currentSlug) : null;
    if (current) stores = [current];
    else if (Array.isArray(entry.stores) && entry.stores.length === 1) stores = entry.stores;
