}

// The merchant's saved catalogue as it was actually built. This is what lets a later edit
// update a shop instead of rebuilding it, and it is read by name so the change of flow order
// above cannot hand this node the wrong item.
let savedCatalogue = null;
let shopOwnerPhone = '';
try {
  // WHICH SHOP IS THIS? The row chosen upstream, by key. Reading the first row here is what put
  // another business's products in front of a merchant running several shops on one number.
  let wantedKey = '';
  let wantedSlug = '';
  try {
    const ss = $('Attach Saved Shop1').first().json || {};
    wantedKey = String((ss.savedShop && ss.savedShop.catalogue_row_key) || '');
    wantedSlug = String((ss.savedShop && ss.savedShop.catalogue_slug) || (ss.savedShop && ss.savedShop.slug) || '').trim();
  } catch (e) {}
  const allRows = $('Lookup Saved Catalogue1').all().map(r => r.json || {}).filter(r => r && r.catalogue_json);
  let cat = null;
  if (wantedKey) cat = allRows.find(r => String(r.row_key || '') === wantedKey) || null;
  if (!cat && wantedSlug) cat = allRows.find(r => String(r.store_slug || '').trim() === wantedSlug) || null;
  if (!cat && allRows.length === 1) cat = allRows[0];
  if (!cat && allRows.length > 1) cat = null;
  if (!cat && !allRows.length) { try { cat = $('Lookup Saved Catalogue1').first().json || null; } catch (e) { cat = null; } }
