} catch (e) {}
if (!savedCatalogue) {
  try {
    const sd = $getWorkflowStaticData('global');
    const e2 = sd && sd.merchants ? sd.merchants[phone] : null;
    if (e2 && e2.catalogue) savedCatalogue = e2.catalogue;
  } catch (e) {}
}

// A merchant answering the payment question for a domain that was already priced.
// This has to come before the store logic: a reply of "1" would otherwise be read as a
// store instruction and could rebuild or overwrite the shop.
let pendingDomain = null;
// The priced domain is tracked as a row in the domain orders table, so the answer still
// resolves after a restart (workflow static data is not kept between runs).
try {
  const row = $('Read Pending Domain Row').first().json || {};
  const rowStatus = String(row.status || '').toUpperCase();
  if (row.id && row.domain && (rowStatus === 'AWAITING_CHOICE' || rowStatus === 'AWAITING_PAYMENT' || rowStatus === 'AWAITING_MERCHANT_PAYMENT')) {
    pendingDomain = {
      domain: String(row.domain),
      price: String(row.price_usd || ''),
      currency: String(row.currency || 'USD'),
      priceUsd: String(row.price_usd || ''),
      slug: String(row.store_slug || ''),
      merchantName: String(row.merchant_name || '')
    };
  }
} catch (e) {}
const answerText = String(extractedMessage || '').toLowerCase().trim();
// A payment answer is a short standalone reply. Before this, ANY message containing "card" or
// "mobile" - "I sell memory cards", "I am on mobile now" - was swallowed as a domain payment
// choice, so those messages got a payment reply instead of the edit the merchant asked for.
const looksLikeAnswer = answerText.length > 0 && answerText.split(/\s+/).length <= 4;
const wantsCard = looksLikeAnswer && (/^(1|card|paypal|pay pal)\b/.test(answerText) || /\bcard\b/.test(answerText) || /\bpaypal\b/.test(answerText));
const wantsMobile = looksLikeAnswer && (/^(2|mobile|momo|airtel|mtn)\b/.test(answerText) || answerText.indexOf('mobile money') >= 0);
