  return [{
    json: {
      isSearch: false,
      isComplete: false,
      isDomainRequest: true,
      isDomainPaymentChoice: true,
      chosenMethod: wantsCard ? 'CARD' : 'MOBILE_MONEY',
      domainName: String(pendingDomain.domain),
      domainPrice: String(pendingDomain.price || ''),
      domainCurrency: String(pendingDomain.currency || 'USD'),
      slug: String(pendingDomain.slug || ''),
      merchantName: String(pendingDomain.merchantName || ''),
      merchantPhone: phone,
      missingPrompt: 'Setting up your payment now...',
      senderPhone: phone,
      businessPhone: shopLine}
  }];
}

if (parsed?.intent === 'SEARCH_MERCHANTS') {
  return [{
    json: {
      isSearch: true,
      isComplete: false,
      slug: stores.length === 1 ? stores[0].slug : '',
      missingPrompt: parsed.conversational_reply || "🔎 Searching the local marketplace...",
      senderPhone: phone,
      businessPhone: shopLine}
