// A domain request is answered from the real registrar check, never from the agent's guess.
// It leaves the store path entirely so nothing is rebuilt or overwritten while pricing a name.
if (parsed?.intent === 'DOMAIN_REQUEST') {
  const domainStore = stores.length === 1
    ? stores[0]
    : (stores.find((st) => normalize(st.parsedData?.merchant_name) === normalize(parsed?.merchant_name)) || null);
  // Plain string work, no pattern matching: the source is stored escaped, and a regex
  // written here would reach the runtime with its slashes stripped.
