      merchantName: String((parsed && parsed.merchant_name) || (savedCatalogue && savedCatalogue.merchant_name) || ''),
      // The buyer and the shop are answered differently: the shop gets the agent's own reply,
      // the buyer gets a confirmation written for a customer, never shop-owner chatter.
