      businessPhone: shopLine}
  }];
}

let intent = parsed?.intent || 'BUILD_STORE';

// Which business is this message about? Match on the business name the agent extracted.
let chosen = null;
if (stores.length === 1) {
  chosen = stores[0];
} else if (stores.length > 1) {
  const wanted = normalize(parsed?.merchant_name);
  if (wanted) chosen = stores.find((st) => normalize(st.parsedData?.merchant_name) === wanted) || null;
}

// Several businesses and we cannot tell which one: ask, and do not touch any store.
if (stores.length > 1 && !chosen) {
  const names = stores.map((st) => '• ' + (st.parsedData?.merchant_name || st.slug)).join(String.fromCharCode(10));
  return [{
    json: {
      isSearch: false,
      isComplete: false,
      needsBusinessChoice: true,
      businesses: stores.map((st) => st.parsedData?.merchant_name || st.slug),
      slug: '',
      parsedData: {},
      missingPrompt: 'You have more than one business with us. Which one is this about?' + String.fromCharCode(10) + names + String.fromCharCode(10) + String.fromCharCode(10) + 'Reply with the business name and I will update that store.',
      senderPhone: phone,
      businessPhone: shopLine}
  }];
}

let savedStore = chosen;

// A dropped location pin is the merchant telling us where the shop is. On a shop that already
// exists that is an edit, not a rebuild, and the shop's own name and catalogue stay as they are.
const sharedPin = prev.locationPin || null;
const hasSharedPin = prev.isLocationPin === true && sharedPin && typeof sharedPin.lat === 'number' && typeof sharedPin.lng === 'number';
if (hasSharedPin && savedStore) {
  intent = 'UPDATE_STORE';
}
if (hasSharedPin) {
  // The pin's own label is the location until the map resolves the exact address.
  parsed = parsed || {};
  // A BARE COORDINATE IS NOT A PLACE NAME.
  // The agent is shown the pin as "lat,lng", and it sometimes repeats those figures back as the
  // shop's location. The page then printed that latitude where the area belongs - the badge read
  // "Live on X-Link Map (0.3447626)". The pin's own label is what a buyer can read, so it wins.
  const isJustCoords = (v) => {
    const s = String(v || '').trim();
    if (!s) return false;
    if (/[a-zA-Z]/.test(s)) return false;
    const parts = s.split(/[,|;]+/).map(p => p.trim()).filter(Boolean);
    if (!parts.length) return false;
    let numeric = 0;
    for (const p of parts) {
      let ok = p.length > 0;
      for (let i = 0; i < p.length; i++) {
        const c = p.charCodeAt(i);
        const allowed = (c >= 48 && c <= 57) || c === 45 || c === 43 || c === 46 || c === 176 || c === 32 || c === 44;
        if (!allowed) { ok = false; break; }
      }
      if (ok) numeric++;
    }
    return numeric === parts.length;
  };
  if (!String(parsed.location || '').trim() || isJustCoords(parsed.location)) {
    parsed.location = String(sharedPin.name || sharedPin.address || 'Shared location').trim();
  }
}

// An edit needs a shop to edit. The saved catalogue is the authority; the in-run static record
// is only a fallback for a number whose shop was built before the catalogue existed.
let editBase = savedCatalogue || (savedStore && savedStore.parsedData) || null;
// Is the merchant asking for a change to a shop that already exists? Only then is a static
// "what I applied" confirmation built and delivered.
isEditRequest = String(intent).toUpperCase() === 'UPDATE_STORE' && Boolean(editBase);

// ── A SECOND WEBSITE IS A DIFFERENT BUSINESS, NOT AN EDIT OF THE FIRST ────────
// Every number gets TWO free websites. A merchant who describes a business with its own name and
// its own goods is BUILDING A NEW SITE: it gets its own page, its own catalogue row and its own
// products. Sent down the edit path instead, the new business was merged into the shop that
// already existed - one page carrying both businesses' items - and a third request was accepted
// silently. The count is taken from the shops that really exist (both tables), so a shop whose
// catalogue row was cleaned up still counts against the allowance.
const siteCtx = (() => {
  try { return ($('Attach Saved Shop1').first().json || {}).savedShop || {}; } catch (e) { return {}; }
})();
const siteAllowance = Number(siteCtx.site_allowance) > 0 ? Number(siteCtx.site_allowance) : 2;
const siteList = Array.isArray(siteCtx.site_list) ? siteCtx.site_list : [];
const siteCount = siteList.length || Number(siteCtx.site_count) || 0;
const nameKeyOfSite = (v) => String(v || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/[ ]+/g, ' ').trim();
const sameBusinessName = (a, b) => {
  const x = nameKeyOfSite(a), y = nameKeyOfSite(b);
  if (!x || !y) return false;
  if (x === y) return true;
  if (x.indexOf(y) >= 0 || y.indexOf(x) >= 0) return true;
  const xs = x.split(' ').filter((w) => w.length > 2);
  const ys = y.split(' ').filter((w) => w.length > 2);
  if (!xs.length || !ys.length) return false;
  const shorter = xs.length <= ys.length ? xs : ys;
  const longer = xs.length <= ys.length ? ys : xs;
  return shorter.every((w) => longer.indexOf(w) >= 0);
};
const requestedBusiness = String((parsed && parsed.merchant_name) || '').trim();
const knownSiteNames = siteList.map((s) => String((s && (String(s.name || '') + ' ' + String(s.slug || ''))) || ''));
knownSiteNames.push(String((savedCatalogue && savedCatalogue.merchant_name) || ''));
knownSiteNames.push(String((savedStore && savedStore.parsedData && savedStore.parsedData.merchant_name) || ''));
const matchesKnownSite = knownSiteNames.some((nm) => Boolean(nameKeyOfSite(nm)) &&
  (sameBusinessName(requestedBusiness, nm) || sameBusinessName(requestedBusiness, String(nm).replace(/-/g, ' '))));
const newSiteProducts = Array.isArray(parsed && parsed.products_and_services) ? parsed.products_and_services : [];
// Words are matched as whole words on purpose: a substring test made "make the background black"
// look like "make a site" and "update my store" like a new business.
const flatSiteMsg = ' ' + String(extractedMessage || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/[ ]+/g, ' ').trim() + ' ';
const saysWord = (w) => flatSiteMsg.indexOf(' ' + w + ' ') >= 0;
const saysBuildSite = ['build','create','make','generate','design','develop','start','launch','open','register','add']
    .some((w) => saysWord(w))
  && (['website','site','page','homepage','shop','store','business','company','brand'].some((w) => saysWord(w))
    || flatSiteMsg.indexOf(' web site ') >= 0);
const saysRename = saysWord('rename') || saysWord('renamed') || saysWord('renaming')
  || flatSiteMsg.indexOf(' now called ') >= 0 || flatSiteMsg.indexOf(' call it ') >= 0;
const agentWantsBuild = String((parsed && parsed.intent) || intent || '').toUpperCase().indexOf('BUILD_STORE') >= 0;
const distinctNewBusiness = Boolean(nameKeyOfSite(requestedBusiness)) && nameKeyOfSite(requestedBusiness).length >= 2
  && !matchesKnownSite && siteCount > 0 && !saysRename;
// A distinct business name the agent itself routes as BUILD_STORE is a new site, with or without
// a price list: a showcase site ("just a page showing what we do") has no items at all.
if (distinctNewBusiness && (saysBuildSite || agentWantsBuild)) {
  if (siteCount >= siteAllowance) {
    // THE FREE ALLOWANCE IS SPENT. Say so plainly, and offer the change that IS possible.
    const listedSites = (siteList.length ? siteList : [{ name: requestedBusiness, slug: '', url: '' }]);
    const siteLines = listedSites.map((s) => '• *' + String(s.name || s.slug) + '*' + (s.url ? String.fromCharCode(10) + '   ' + s.url : '')).join(String.fromCharCode(10));
    const firstSiteName = String((listedSites[0] && (listedSites[0].name || listedSites[0].slug)) || 'my shop');
    const limitReply = [
      '⛔ *Your free website generation limit has been reached.*',
      'This number already has ' + siteCount + ' websites, which is the whole free allowance of ' + siteAllowance + ':',
      siteLines,
      '',
      'A third website is not included in the free allowance. I can still change either of these two sites for you - tell me which one and what to change, for example "' + firstSiteName + ' change the Samsung S26 price to 5,200,000".'
    ].join(String.fromCharCode(10));
    return [{
      json: {
        isSearch: false,
        isComplete: false,
        isQuestionOnly: true,
        intent: 'ANSWER_ONLY',
        siteLimitReached: true,
