                // identified as, even when the agent's card carried no image of its own.
                const savedImages = Array.isArray(sp.images) ? sp.images.filter(Boolean) : [];
                const agentImages = Array.isArray(ap.images) ? ap.images.filter(Boolean) : [];
                if (freshPhoto && freshPhotoItem && similarity(sp.name, freshPhotoItem) >= 0.5 && agentImages.indexOf(freshPhoto) < 0) agentImages.push(freshPhoto);
                const combined = savedImages.slice();
                // Only a picture for a card this message is about is added, and only when the
                // message is about a picture at all. A picture the agent echoed (or invented) for
                // another card is not this message's to add.
                if (cardInScope && pictureTalked) {
                    agentImages.forEach(u => { if (combined.indexOf(u) < 0) combined.push(u); });
                }
                // A picture the agent attached on its own is never put on a card the merchant did
                // not name - that is how an untouched card came back with a searched picture.
                if (!combined.length && ap.image && cardInScope && pictureTalked) combined.push(ap.image);
                // A REMOVAL THE MERCHANT ASKED FOR IS APPLIED, ON THIS CARD ONLY.
                // Everything else on the shop keeps its pictures exactly as they were saved.
                const removal = removalFor(sp.name);
                let finalImages = combined;
                if (removal) {
                    finalImages = removal.url
                        ? combined.filter(u => String(u).trim() !== removal.url)
                        : [];
                    if (removal.url && finalImages.length === combined.length) finalImages = [];
                    photoRemoved.push({ name: String(sp.name || ''), count: Math.max(1, combined.length - finalImages.length) });
                }
                // A PICTURE THE MERCHANT SENT FOR THIS CARD IS THE PICTURE THIS CARD SHOWS.
                // It used to be appended to the end of the gallery, so the page kept the old
                // first picture as the card's photo and the merchant's new one appeared only as
                // a small thumbnail - to them, "it refused to add my image". The card they named
                // now leads with their picture, and the earlier ones stay behind it in the strip.
                const sentForThisCard = Boolean(freshPhoto) && Boolean(freshPhotoItem) && similarity(sp.name, freshPhotoItem) >= 0.5;
                if (sentForThisCard) {
                    finalImages = [freshPhoto].concat(finalImages.filter(u => String(u).trim() !== freshPhoto));
                }
                if (finalImages.length) out.images = finalImages;
                else if (removal) { delete out.images; delete out.image; }
                if (!removal) { if (!out.img && finalImages.length) out.img = finalImages[0]; }
                else if (!finalImages.length) { delete out.img; delete out.image; }
                else out.img = finalImages[0];
                // A price the merchant did not give keeps the saved one. Never invent, never wipe.
                // AND A PRICE ON A CARD THIS MESSAGE IS NOT ABOUT IS NOT THIS MESSAGE'S TO CHANGE.
                // An agent that echoed the catalogue - or guessed a figure for a card nobody asked
                // about - used to move that card's price. Only a card the merchant named can have
                // its price changed; every other card keeps the saved figure exactly.
                const typedPrice = (cardInScope && !itemlessEdit && priceTalked) ? priceOf(ap.price) : 0;
                out.price = typedPrice > 0 ? typedPrice : priceOf(sp.price);
                out.currency = String(ap.currency || sp.currency || 'UGX');
                // Bargaining and stock are the merchant's own settings on that card. An echoed
                // catalogue must not quietly re-enable offers or change the stock figure.
                if (sp.bargain !== undefined) out.bargain = sp.bargain;
                if (sp.stock !== undefined) out.stock = sp.stock;
                if (sp.min_price_local !== undefined) out.min_price_local = sp.min_price_local;
                if (sp.price_usd !== undefined) out.price_usd = sp.price_usd;
                if (sp.price_local !== undefined) out.price_local = sp.price_local;
                if (sp.category !== undefined) out.category = sp.category;
                return out;
            });

            // AN ITEM THE MERCHANT NEVER MENTIONED IS NOT AN ITEM ON THEIR SHOP.
            // The model writes a plausible extra product from its own memory - a screen protector
            // nobody sells, with an invented description and a stock photo found on the web - and
            // appending that is how a line the merchant never typed appeared on their card list.
            // Only what the merchant themselves named may be added: a word in this message, or the
            // subject of a photo they sent. Nothing else is ever appended.
            const merchantSaid = (() => {
                let said = String(extractedMessage || '');
                if (freshPhotoItem) said += ' ' + String(freshPhotoItem);
                return said.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
            })();
            const merchantNamed = (nm) => {
                const full = String(nm || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
                if (!full || !merchantSaid) return false;
                if (merchantSaid.indexOf(full) >= 0) return true;
                const bits = full.split(' ').filter(w => w.length > 2);
                return bits.length > 0 && bits.every(w => merchantSaid.indexOf(w) >= 0);
            };
            agentProducts.forEach((ap, i) => {
                if (usedAgent.has(i)) return;
                // Nothing to add from an item with neither a real price nor a description.
                if (priceOf(ap.price) <= 0 && !String(ap.description || '').trim()) return;
                // And nothing to add from an item the merchant did not actually name.
                if (!merchantNamed(ap.name)) return;
                const newImages = Array.isArray(ap.images) ? ap.images.filter(Boolean) : [];
                if (!newImages.length && ap.image) newImages.push(ap.image);
                const newItem = { ...ap, price: priceOf(ap.price) };
                if (newImages.length) { newItem.images = newImages; if (!newItem.img) newItem.img = newImages[0]; }
                mergedProducts.push(newItem);
            });

            merged.products_and_services = mergedProducts;
        } else if (editBase && Array.isArray(editBase.products_and_services) && editBase.products_and_services.length > 0) {
            // The merchant changed the shop but said nothing about the catalogue, so the saved
            // items stand exactly as they were. Losing them would empty the shopfront.
            // A removal is the exception: it is an explicit instruction about the catalogue, so
            // the already-filtered list is kept instead of putting the removed item back - which
            // is what made "remove the samsung" report success while the item was still there.
            if (!(Array.isArray(merged.products_and_services) && merged.products_and_services.length)) {
                merged.products_and_services = editBase.products_and_services;
            }
        }
        // ── WHAT THE MERCHANT ACTUALLY CHANGED ─────────────────────────────
        // The confirmation the merchant reads is built from a real comparison of the shop before
        // and after this edit. That is the only way to say honestly what was applied, and to say
        // it the same way every time instead of re-phrasing it per run.
        let beforeList = [];
        try {
            beforeList = Array.isArray(savedCatalogue && savedCatalogue.products_and_services)
                ? savedCatalogue.products_and_services
                : (Array.isArray(editBase.products_and_services) ? editBase.products_and_services : []);
        } catch (e) { beforeList = []; }
        const afterList = Array.isArray(merged.products_and_services) ? merged.products_and_services : [];
        const normKey = (n) => String(n || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
        // THE PRICE THE MERGE DECIDED IS THE PRICE THIS EDIT SHIPS WITH.
        // A later pass in this node re-reads prices with its own tolerant reader ("50 thousand",
        // "1,5m") and used to write its reading back over every card - including cards this
        // message is not about, and cards whose price the merge had just decided to keep. This map
        // is that decision, and the later pass is not allowed to overturn it.
        priceFromMerge = new Map();
        afterList.forEach((ap) => {
            const k = normKey(ap && ap.name);
            if (k) priceFromMerge.set(k, readPrice(ap && ap.price));
        });
        // The same reader as everywhere else. The old one kept only digits and a dot, so the
        // receipt compared "50k" as 50 against a saved 5,200,000 and announced a price change
        // that had not happened the way it was written.
        const numOf = readPrice;
        const beforeByKey = {};
        beforeList.forEach(sp => { const k = normKey(sp.name); if (k) beforeByKey[k] = sp; });
        // A renamed card is the SAME card under a new name. Comparing the two names as text made
        // one rename read as an addition plus a removal; the rename map keeps it as one change.
        const renamedFromKey = {};
        const renamedToKey = {};
        renames.forEach((rn) => {
            const fromKey = normKey(rn.from);
            const toKey = normKey(rn.to);
            if (!fromKey || !toKey) return;
            renamedFromKey[fromKey] = true;
            renamedToKey[toKey] = fromKey;
        });
        const moneyNote = (v) => {
            const n = numOf(v);
            if (!(n > 0)) return '';
            // Group the thousands properly: 6500000 reads as 6,500,000. Escaped for the template
            // literal this code lives in, so the runtime sees a real thousands separator.
            return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
        };
        // THE SCOPE OF THIS EDIT IS DECIDED HERE, ONCE.
        // A merchant who changes one thing must see only that thing change. Two questions answer
        // it: which saved items the merchant's own words name, and the extra items the assistant
        // listed in remove_items / remove_photos. Everything downstream - which card is redrawn,
        // which card is searched again, which card is left exactly as it is - is read from these
        // two lists, so an item outside them cannot be touched by this message.
        const scopeSaid = (() => {
            let said = String(editMsgRaw || '');
            if (freshPhotoItem) said += ' ' + String(freshPhotoItem);
            return normKey(said);
        })();
        const scopeWords = (n) => String(n || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(w => w.length > 2);
        const GENERIC_SCOPE = ['the', 'and', 'for', 'with', 'item', 'product', 'shop', 'store', 'price', 'photo', 'picture', 'image', 'them', 'its', 'this', 'that', 'new'];
        const namesSavedItem = (nm) => {
            const full = String(nm || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
            if (!full || !scopeSaid) return false;
            if (scopeSaid.indexOf(normKey(nm)) >= 0) return true;
            const bits = scopeWords(nm);
            if (bits.length > 0 && bits.every(w => scopeSaid.indexOf(w) >= 0)) return true;
            return bits.some(w => w.length >= 4 && GENERIC_SCOPE.indexOf(w) < 0 && scopeSaid.indexOf(w) >= 0);
        };
        const touchedSet = {};
        let photoSet = {};
        beforeList.forEach((sp) => {
            if (sp && sp.name && namesSavedItem(sp.name)) {
                touchedSet[normKey(sp.name)] = true;
                photoSet[normKey(sp.name)] = true;
            }
        });
        [].concat(
            Array.isArray(parsed && parsed.remove_items) ? parsed.remove_items : [],
            Array.isArray(parsed && parsed.removed_items) ? parsed.removed_items : []
        ).forEach((x) => {
            const nm = String((x && x.name) || x || '').trim();
            if (nm) { touchedSet[normKey(nm)] = true; photoSet[normKey(nm)] = true; }
        });
        (Array.isArray(parsed && parsed.remove_photos) ? parsed.remove_photos : []).forEach((x) => {
            const nm = String((x && x.name) || (typeof x === 'string' ? x : '') || '').trim();
            if (nm) { touchedSet[normKey(nm)] = true; photoSet[normKey(nm)] = true; }
        });
        renames.forEach((rn) => {
            if (normKey(rn.from)) touchedSet[normKey(rn.from)] = true;
        });
        // A CARD NAMED FOR A PRICE OR A NAME IS NOT A CARD WHOSE PICTURE MOVED.
        // Only a message that actually talks about a picture - or that carries one, or removes one -
        // may change the pictures on the cards it names. "Change the iPhone to 6,500,000" is a
        // price, so every picture on the shop stays exactly as it is.
        const photoTalkedAbout = /(photo|photos|picture|pictures|image|images|pic|shot|banner|cover photo|thumbnail|gallery)/i.test(String(editMsgRaw || ''))
            || Boolean(freshPhoto)
            || (Array.isArray(parsed && parsed.remove_photos) && parsed.remove_photos.length > 0);
        if (!photoTalkedAbout) photoSet = {};
        // "REFRESH THE PHOTOS ON ALL MY PRODUCTS" IS A PICTURE ORDER FOR THE WHOLE SHOP.
        // Without this the scope would be empty and the request would do nothing. Every saved card
        // is put in scope, which is exactly what the merchant asked for - and nothing more.
        const everyCardAsked = photoTalkedAbout && / (all|every|each|whole|entire) /i.test(String(editMsgRaw || ''))
            && /(product|item|card|shop|catalogue)/i.test(String(editMsgRaw || ''));
        if (everyCardAsked) {
            beforeList.forEach((sp) => {
                if (sp && sp.name) { touchedSet[normKey(sp.name)] = true; photoSet[normKey(sp.name)] = true; }
            });
        }
        if (freshPhotoItem && normKey(freshPhotoItem) && photoTalkedAbout) {
            touchedSet[normKey(freshPhotoItem)] = true;
            photoSet[normKey(freshPhotoItem)] = true;
        }
        editItemless = !Object.keys(touchedSet).length;
        editTouchedKeys = Object.keys(touchedSet);
        editPhotoKeys = Object.keys(photoSet);
        // NO PICTURE IS REBUILT BY THIS MESSAGE AT ALL.
        // Either it named no item, or it named items but never mentioned a picture. The picture
        // stage reads this one flag and leaves every card as it is.
        editPicturesUntouched = !Object.keys(photoSet).length;

        const changes = [];
        const removed = [];
        const seenKeys = {};
        afterList.forEach(ap => {
            const k = normKey(ap.name);
            seenKeys[k] = true;
            const before = beforeByKey[k] || (renamedToKey[k] ? beforeByKey[renamedToKey[k]] : undefined);
            const priceNow = numOf(ap.price);
            if (!before) {
                changes.push('• Added *' + String(ap.name || 'item') + '*' + (priceNow > 0 ? ' - ' + moneyNote(priceNow) : ''));
                return;
            }
            const priceWas = numOf(before.price);
            if (priceNow > 0 && priceNow !== priceWas) {
                changes.push('• *' + String(before.name || ap.name) + '* price: ' + (priceWas > 0 ? moneyNote(priceWas) + ' -> ' : '') + moneyNote(priceNow));
            }
            const descWas = String(before.description || '').trim();
            const descNow = String(ap.description || '').trim();
            if (descNow && descNow !== descWas && !(priceNow > 0 && priceNow !== priceWas)) {
                changes.push('• *' + String(before.name || ap.name) + '* description updated');
            }
            const imgsWas = Array.isArray(before.images) ? before.images.length : (before.img ? 1 : 0);
            const imgsNow = Array.isArray(ap.images) ? ap.images.length : (ap.img ? 1 : 0);
            if (imgsNow > imgsWas) {
                changes.push('• *' + String(before.name || ap.name) + '* photo applied');
            }
        });
        // A rename is reported by its own before/after line. Without this a rename that really did
        // happen was reported as "nothing to change", which is the opposite of the truth.
        renames.forEach((rn) => {
            changes.push('• Renamed *' + rn.from + '* to *' + rn.to + '*');
        });
        beforeList.forEach(sp => {
            const k = normKey(sp.name);
            // An old name that was renamed (not deleted) is not a removal.
            if (k && !seenKeys[k] && !renamedFromKey[k]) removed.push('• Removed *' + String(sp.name || 'item') + '*');
        });
        changes.push.apply(changes, removed);
        const otherChanges = [];
        if (String(merged.merchant_name || '').trim() && String(merged.merchant_name || '').trim() !== String(savedCatalogue && savedCatalogue.merchant_name || '').trim()) {
            otherChanges.push('• Business name: ' + String(merged.merchant_name).trim());
        }
        if (String(merged.tagline || '').trim() && String(merged.tagline || '').trim() !== String(savedCatalogue && savedCatalogue.tagline || '').trim()) {
            otherChanges.push('• Tagline: ' + String(merged.tagline).trim());
        }
        if (String(merged.about_story || '').trim() && String(merged.about_story || '').trim() !== String(savedCatalogue && savedCatalogue.about_story || '').trim()) {
            otherChanges.push('• Story updated');
        }
        if (String(merged.location || '').trim() && String(merged.location || '').trim() !== String(savedCatalogue && savedCatalogue.location || '').trim()) {
            otherChanges.push('• Location: ' + String(merged.location).trim());
        }
        if (String(merged.background_color || '').trim() && String(merged.background_color || '').trim() !== String(savedCatalogue && savedCatalogue.background_color || '').trim()) {
            otherChanges.push('• Background colour: ' + String(merged.background_color).trim());
        }
        if (String(merged.brand_color || '').trim() && String(merged.brand_color || '').trim() !== String(savedCatalogue && savedCatalogue.brand_color || '').trim()) {
            otherChanges.push('• Brand colour: ' + String(merged.brand_color).trim());
        }
        // THE FRONT PAGE IS ITS OWN THING, AND IT IS REPORTED LIKE ONE.
        // A merchant who changes only the picture at the top used to be told "I could not find
        // anything to change", because the receipt only compared products and a short list of
        // shop fields - the front page was not on it. The change had gone through; the reply said
        // it had not. The picture is compared on its own slot so this line can never be confused
        // with a product photo moving.
        // Every front page slot is compared on its own, so it does not matter which of them the
        // assistant filled in - "use this as my banner" lands in hero_image, "change the picture at
        // the top" lands in homepage_image, and both have to be reported.
        const frontPageSlots = ['homepage_image', 'hero_image', 'cover_image', 'banner_image'];
        const frontPageWas = frontPageSlots.map((k) => String((savedCatalogue && savedCatalogue[k]) || '').trim()).filter(Boolean).join(' ');
        const frontPageNow = frontPageSlots.map((k) => String((merged && merged[k]) || '').trim()).filter(Boolean).join(' ');
        if (frontPageNow && frontPageNow !== frontPageWas) {
            otherChanges.push('• Front page picture updated (your products kept their own pictures)');
        }
        if (String(merged.hero_headline || '').trim() && String(merged.hero_headline || '').trim() !== String(savedCatalogue && (savedCatalogue.hero_headline || savedCatalogue.tagline) || '').trim()) {
            otherChanges.push('• Headline: ' + String(merged.hero_headline).trim());
        }
        if (String(merged.promotion || '').trim() !== String((savedCatalogue && savedCatalogue.promotion) || '').trim()) {
            otherChanges.push(String(merged.promotion || '').trim() ? '• Promotion: ' + String(merged.promotion).trim() : '• Promotion removed');
        }
        if (freshPhoto) otherChanges.push('• Your photo was placed on ' + freshPhotoItem);
        // A REMOVED PICTURE IS REPORTED, OR THE MERCHANT SEES IT GONE AND NO WORD ABOUT IT.
        photoRemoved.forEach((pr) => {
            if (!pr || !pr.name) return;
            otherChanges.push('• *' + pr.name + '* photo removed - the item stays on your shop');
        });

        editChangeList = changes;
        editOtherChanges = otherChanges;
        editAppliedNames = afterList.map(ap => String(ap.name || '').trim()).filter(Boolean);

        // Only things that genuinely did not land are reported as a problem. Nothing here is
        // guessed: an item with neither a price nor a description was dropped, and a photo that
        // matched no card was not placed. Everything else went through.
        if (freshPhoto && !freshPhotoItem && afterList.length > 1) {
            orderIssue = 'your photo arrived, but I could not tell which item it belongs to. Tell me the item name and I will put it on that card.';
        }
        if (!changes.length && !otherChanges.length) {
            orderIssue = 'I could not find anything to change in that message. Say the item and the new value, for example "change the iPhone 18 to 6,500,000".';
        }
        // The shop-level fields are compared AFTER the item list, so a rename or a price can never
        // hide behind the "nothing changed" message when the edit itself was carried out.
        if (changes.length || otherChanges.length) orderIssue = '';

        parsed = merged;
        parsed.intent = 'UPDATE_STORE';
    } else {
        intent = 'BUILD_STORE';
    }
}

// ── EVERY PRICE THAT LEAVES THIS NODE IS A NUMBER ────────────────────────────
// A merchant building their first shop types "50k" or "50 thousand" just as readily as they
// type it on an edit, and the model hands that straight back as text. This node already turned
// text prices into numbers on the EDIT path; the BUILD path never did, so the raw "50k" travelled
// into the saved catalogue and into the page builder, which read "50 thousand" as fifty
// shillings and put "USh 50" on the card. Normalising once, here, means every later step - the
// page, the saved catalogue, the receipt, the cart - receives one honest number.
// Only a real figure is written. A price the merchant never gave stays exactly as it is, so it
// still reads as "ask the merchant" instead of becoming a made-up zero.
if (parsed && typeof parsed === 'object' && Array.isArray(parsed.products_and_services)) {
    // An edit path already decided every card's price. This pass never re-opens a figure the
    // merge settled, and never writes a figure onto a card the merchant did not name.
    const keepDecided = intent === 'UPDATE_STORE';
    const decidedKeys = (() => {
        const m = {};
        if (!keepDecided) return m;
        (Array.isArray(savedCatalogue && savedCatalogue.products_and_services) ? savedCatalogue.products_and_services : [])
            .forEach((sp) => { const k = String(sp && sp.name || '').toLowerCase().replace(/[^a-z0-9]+/g, ''); if (k) m[k] = true; });
        return m;
    })();
    parsed.products_and_services = parsed.products_and_services.map((it) => {
        if (!it || typeof it !== 'object') return it;
        const out = { ...it };
        const itemKey = String(out.name || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
        // This card was already on the shop and this message is an edit: the merge owns its price.
        if (keepDecided && decidedKeys[itemKey] && priceFromMerge && priceFromMerge.has(itemKey)) {
            const decided = priceFromMerge.get(itemKey);
            if (decided > 0) out.price = decided;
            else delete out.price;
        }
        const asked = readPrice(out.price);
        if (asked > 0) out.price = asked;
        else if (typeof out.price !== 'number' || !isFinite(out.price) || out.price <= 0) delete out.price;
        const floor = readPrice(out.min_price);
        if (floor > 0) out.min_price = floor;
        else if (out.min_price !== undefined) delete out.min_price;
        // A price is quoted in a currency. When the merchant named one ("$10", "UGX 50k") it is
        // kept; otherwise the shop's own currency stands and is never left blank.
        out.currency = String(out.currency || (parsed.currency || (parsed.currencies && parsed.currencies.currency)) || 'UGX').toUpperCase();
        return out;
    });
}



// THE ADDRESS IS THE BUSINESS NAME. A shop called "Entropic" must live at /entropic-7863, not at
// whatever address happened to be saved before. The old rule only replaced a generic name, so a
// slug inherited from another business on the same number was kept forever and every shop on that
// number kept showing the same address. The rule now is: the saved slug is kept ONLY while it
// still reads as this business's own name.
const slugifyName = (v) => String(v || '')
  .toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/['’]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');
const nameForSlug = String(parsed?.merchant_name || '').trim();
const nameSlug = slugifyName(nameForSlug);
const slugSuffix = phone.slice(-4);
const wantedSlug = nameSlug ? (nameSlug + '-' + slugSuffix) : '';
// The address this number is on right now. The catalogue row gives it; a shop built before the
// catalogue existed is found through the saved shop the previous step attached.
// A brand-new second website starts with NO address of its own: borrowing the existing shop's
// slug is what made the second business overwrite the first one's page.
let existingSlug = isNewSiteBuild ? '' : String(savedStore?.slug || '').trim();
if (!existingSlug && !isNewSiteBuild) {
  try { existingSlug = String(($('Attach Saved Shop1').first().json || {}).savedShop?.slug || '').trim(); } catch (e) {}
}
let slug = existingSlug;
// Does the saved address belong to the business being built right now? Every real word of the
// business name has to appear in it; a slug built from a different shop's name does not.
const slugWords = String(slug).split('-').filter((w) => w.length > 2);
const nameWordsForSlug = nameSlug.split('-').filter((w) => w.length > 2);
const slugMatchesName = Boolean(slug) && (slug === wantedSlug ||
  (nameWordsForSlug.length > 0 && nameWordsForSlug.every((w) => String(slug).indexOf(w) >= 0)) ||
  (slugWords.length > 0 && nameWordsForSlug.length > 0 && slugWords[0] === nameWordsForSlug[0]));
if (wantedSlug && !slugMatchesName) {
  // The previous address is remembered so nothing that still points at it goes dark silently.
  if (slug && slug !== wantedSlug) parsed = { ...(parsed || {}), previous_slug: slug };
  slug = wantedSlug;
}
if (!slug) {
  // No name at all yet (a question, not a build): fall back to a neutral address.
  slug = 'site-' + slugSuffix;
}

let conversationalReply = parsed?.conversational_reply || '';
const missingFields = [];

const name = (parsed?.merchant_name || '').trim();
if (!name || name.length < 2 || name.toLowerCase() === 'null') missingFields.push('Business Name');
const location = (parsed?.location || '').trim();
// Location is deliberately NOT a blocking field. It used to be, and that stopped the portal
// from being built at all: a merchant who described their goods but had not yet said where
// they are got a question instead of their website. The map step asks for the exact point
// right after the shop is built, so an instant portal is never held hostage to a missing area.
const locationMissing = !location && !hasSharedPin;
const products = Array.isArray(parsed?.products_and_services) ? parsed.products_and_services : [];
// A WEBSITE THAT SHOWS WHAT THE BUSINESS IS IS NOT A PRICE LIST.
// This used to demand "at least one Product or Menu Item" before anything could be built. A
// merchant who asked only for a showcase page - "we just want a website showcasing what we are
// about, I don't have time, generate it for me" - got the agent's promise of a link and then no
// site at all: the missing product kept isComplete false, Is Store Ready?1 sent the run down the
// reply-only branch, and the compiler never ran. The merchant waited for a website that was never
// built, on a shop the system had already agreed to make.
// So: a shop the merchant described as a SHOWCASE is buildable as soon as it has a name and a
// story. A shop that trades through the site still needs something to sell, because an empty shop
// floor is not a shop. The stated shop type and site tier say which kind this is.
const statedShopTypeForGap = String(parsed?.shop_type || '').toUpperCase();
const statedTierForGap = String(parsed?.site_tier || '').toUpperCase();
const showcaseRequested = statedShopTypeForGap === 'PRESENCE'
  || statedTierForGap === 'PRESENCE'
  || parsed?.showcase_only === true
  || parsed?.presence_only === true;
const describesTheBusiness = Boolean(String(parsed?.about_story || '').trim())
  || Boolean(String(parsed?.tagline || '').trim())
  || Boolean(String(parsed?.business_category || '').trim());
// A SHOWCASE SHOP THAT IS ALREADY BUILT IS NEVER "INCOMPLETE".
// The rule above only had to decide whether a NEW showcase shop could be built. It also ran on a
// shop that has already been built and saved with no priced items - a pharmacy, a salon, a
// service business - and called it incomplete every time. The build branch was skipped, the
// merchant's edit went nowhere, and the agent answered "I don't have a live shop for this number".
// A saved shop with a link is complete by definition: it exists.
const shopAlreadyBuilt = (() => {
  try {
    const ss = ($('Attach Saved Shop1').first().json || {}).savedShop || {};
    return ss.has_shop === true && Boolean(String(ss.slug || '').trim());
  } catch (e) { return false; }
})();
if (products.length === 0 && !shopAlreadyBuilt && !(showcaseRequested && describesTheBusiness)) {
  missingFields.push('At least one Product or Menu Item');
}

const isComplete = missingFields.length === 0;

// A QUESTION IS NOT A BUILD ORDER.
// Before this, every message from a number that already had a shop was forced down UPDATE_STORE,
// which rebuilds and re-publishes the whole site. So "does this shop look ok?" or "what did I
// save?" re-ran the entire build and the merchant saw the site being built again for a question.
// A question, a greeting, or a remark about the shop is now answered and STOPPED here: the reply
// goes out, isQuestionOnly is set, and the build branch never runs. A real request to change
// something is untouched - that still updates the shop.
// Only an ACTION verb can request a change. Nouns the merchant might merely be asking about -
// picture, photo, price, item, colour - are deliberately NOT in this list: "does the picture show
// on my site?" asks about the picture, it does not ask to change it.
const changeVerbs = /\b(add|remove|delete|change|update|rename|replace|set|make|put|edit|correct|increase|reduce|lower|raise|fix|apply|upload|publish|clear|swap|switch|move|insert|append|stop|start|reword)\b/i;
const questionWords = /(\?|^\s*(what|why|how|when|which|who|where|is|are|do|does|did|can|could|would|should|have|has|will)\b)/i;
const msgText = String(extractedMessage || '').trim();
const agentSaidNoChange = parsed?.no_change === true || parsed?.asks_a_question === true;
const agentAnsweredOnly = String(parsed?.intent || '').toUpperCase() === 'ANSWER_ONLY';

// IS THIS A QUESTION OR AN INSTRUCTION? A question can contain a change verb by accident:
// "can buyers make offers?", "how do I set the price?", "do you put my photo on the card?" are
// questions, and answering them by rebuilding the site is the exact complaint this guards.
// So a question is recognised whenever it is phrased as a question AND carries no concrete
// new value to apply (a price, a colour, a photo, a quoted new name). An instruction - "make
// the background black", "rename the samsung to Galaxy S26 Ultra" - always carries that value.
const asksAQuestion = questionWords.test(msgText);
// A message that carries something concrete to apply - a figure, a colour, a link, a rename or a
// removal - is an instruction even when it is written as a question: "can you change the iPhone to
// 6,500,000?" must be carried out, not just answered. A value-less question is answered.
const carriesNewValue = /(\d[\d,.]*|#[0-9a-f]{3,6}\b|https?:\/\/\S+|\b(rename|re-?name|call it|call the|name it|now called)\b|\b(remove|delete|drop|stop selling)\b)/i.test(msgText);
const isQuestionOnly = Boolean(msgText) && !carriesNewValue
  && (agentSaidNoChange || agentAnsweredOnly || asksAQuestion);
// ASKING FOR THE ADDRESS IS ANSWERED HERE, WITHOUT A REBUILD.
// "send link", "what is my link?", "where is my website?" must always return the address. Left to
// the model this was answered from memory and sometimes not at all, so the address is assembled
// from the shop's own saved slug and sent back with no change to the site.
// "BUILD MY WEBSITE" IS NOT "SEND ME MY LINK".
// The link rule below matches the words "my website" - so a merchant writing "My business is
// Bros... build my website" was answered with the address of their existing shop and NOTHING was
// built. Any message that asks for work to be done has to fall through to the build/update path,
// however it phrases it. Only a message that asks for the address and asks for nothing else is
// answered here.
const buildVerbs = /\b(build|create|make|design|redo|rebuild|add|remove|delete|change|update|edit|set|rename|replace|re-?name|fix|apply|upload|publish|insert|append|start|switch|move|lower|raise|increase|reduce|reword|swap|sell|why|how)\b/i;
const askingForLink = /(send (me )?(the )?(link|address|url|site|website)|(what|whats|what is|where is|give me|share|resend|repeat)[^.]{0,25}(link|address|url|site|website)|my (link|address|url|website|site))/i.test(msgText)
  && !buildVerbs.test(msgText);
if (askingForLink && String(slug || '').trim()) {
  const linkReply = [
    '🌐 *' + String(parsed && parsed.merchant_name || savedCatalogue && savedCatalogue.merchant_name || 'Your shop') + '*',
    'https://orchid-frigatebird.pikapod.net/webhook/storefront?slug=' + slug,
    '',
    'That address always shows your latest products and pictures - just refresh the page.',
    'Tell me a change any time and it updates there.'
  ].join(String.fromCharCode(10));
  return [{
    json: {
      isSearch: false,
      isComplete: false,
      isQuestionOnly: true,
      intent: 'ANSWER_ONLY',
      slug: slug,
      locationMissing: locationMissing,
      parsedData: parsed || {},
      missingPrompt: linkReply,
      senderPhone: phone,
      businessPhone: shopLine,
      customerLocationPin: null,
      isLocationPin: hasSharedPin
    }
  }];
}

// A memory wipe clears and stops. Nothing is rebuilt: the whole point is that the old page, the
// old product list and the archived photos are gone, so regenerating them from here would undo it.
if (isMemoryWipe) {
  const wipeReply = [
    '✅ *Memory cleared for this number.*',
    '• The saved shop page and its product list are gone',
    '• Photos archived against this shop are gone',
    '• Nothing from an earlier chat is being reused',
    '',
    'Send your business name and what you sell, and I will build a fresh website for you.'
  ].join(String.fromCharCode(10));
  return [{
    json: {
      isSearch: false,
      isComplete: false,
      isQuestionOnly: true,
      intent: 'ANSWER_ONLY',
      slug: '',
      locationMissing: false,
      parsedData: {},
      missingPrompt: wipeReply,
      senderPhone: phone,
      businessPhone: shopLine,
      customerLocationPin: null,
      isLocationPin: hasSharedPin
    }
  }];
}

// WHICH ITEM? A merchant who says "change the price" or "edit it" has not told us what to
// change, and guessing is how an unrelated product ends up on their shop. Instead the real item
// names off their own saved catalogue are read back, so they can point at one. This runs BEFORE
// anything is built, so an unclear instruction can never reach the storefront.
const savedItemNames = (() => {
  const fromCat = Array.isArray(savedCatalogue && savedCatalogue.products_and_services)
    ? savedCatalogue.products_and_services
    : (Array.isArray(editBase && editBase.products_and_services) ? editBase.products_and_services : []);
  return fromCat.map(sp => String((sp && sp.name) || '').trim()).filter(Boolean);
})();
if (isEditRequest && savedItemNames.length > 0) {
  // Words that describe goods in general rather than one item on this shop. Matching on these
  // would let "the price of the phone" claim whichever phone happened to be saved.
  const GENERIC_ITEM_WORDS = ['phone', 'mobile', 'item', 'product', 'price', 'shop', 'store', 'offer', 'goods', 'service', 'piece', 'size', 'colour', 'color', 'something', 'thing'];
  const flatMsg = String(msgText).toLowerCase().replace(/[^a-z0-9]+/g, ' ');
  const saysWhichItem = savedItemNames.some(nm => {
    const full = String(nm).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    if (!full) return false;
    if (flatMsg.indexOf(full) >= 0) return true;
    const wordsOf = full.split(' ').filter(w => w.length > 2);
    // All the words of the name, in any order: "tempered glass premium" still means that item.
    if (wordsOf.length > 0 && wordsOf.every(w => flatMsg.indexOf(w) >= 0)) return true;
    // Or one distinctive word the merchant actually said: "the glass", "the samsung". This is
    // how people shorten a product name, and it is what lets "remove the glass" reach the card.
    return wordsOf.some(w => w.length >= 4 && GENERIC_ITEM_WORDS.indexOf(w) < 0 && flatMsg.indexOf(w) >= 0);
  });
  const agentAddsItem = Array.isArray(parsed?.products_and_services)
    && parsed.products_and_services.some(ap => {
      const nm = String((ap && ap.name) || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
      return nm && !savedItemNames.some(sn => String(sn).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() === nm);
    });
  const menuReply = /^(menu|list|what do i have|what have i got|my items|my products|show my items|show my products)/i.test(msgText.trim());
  // Only an instruction that is clearly about ONE OF THE ITEMS can be ambiguous. A change to the
  // shop itself - a colour, the name, the story, the pin, the banner - names no item by design
  // and must go through untouched, or every restyle would be answered with "which item?".
  const aboutAnItem = /(price|cost|amount|rate|stock|quantity|delete|remove|rename|item|product|them|it)/i.test(msgText);
  const aboutTheShop = /(colour|color|background|theme|name|title|tagline|slogan|about|story|promotion|discount|offer|location|address|map|pin|photo|picture|image|hero|banner|logo|payment|deliver|welcome|headline)/i.test(msgText);
  const ambiguousItemEdit = !saysWhichItem && !agentAddsItem && !menuReply && aboutAnItem && !aboutTheShop;
  if (ambiguousItemEdit) {
    const listLines = savedItemNames.map(nm => '• ' + nm).join(String.fromCharCode(10));
    const whichReply = [
      'Which item do you mean? Your shop has:',
      listLines,
      '',
      'Reply with the item and the change, for example "' + savedItemNames[0] + ' price 5000".'
    ].join(String.fromCharCode(10));
    return [{
      json: {
        isSearch: false,
        isComplete: false,
        isQuestionOnly: true,
        intent: 'ANSWER_ONLY',
        slug: slug,
        locationMissing: locationMissing,
        parsedData: parsed || {},
        missingPrompt: whichReply,
        senderPhone: phone,
      businessPhone: shopLine,
        customerLocationPin: null,
        isLocationPin: hasSharedPin
      }
    }];
  }
}

// WHICH WEBSITE? Several shops on one number and a message that names none of them: say so and
// stop. Building on top of whichever shop was read last is what merged two businesses together.
let needsShopChoice = false;
let shopChoices = [];
try {
  const shopCtx = ($('Attach Saved Shop1').first().json || {}).savedShop || {};
  needsShopChoice = shopCtx.needs_shop_choice === true;
  shopChoices = Array.isArray(shopCtx.shops) ? shopCtx.shops : [];
} catch (e) { needsShopChoice = false; }
// A brand-new business a merchant wants to add is NOT ambiguous: it has its own name and its own
// items, so it gets its own row and its own page. Only a request that points at no particular shop
// is asked about.
const namedNewBusiness = Boolean(name) && products.length > 0
  && String(name).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() !== String(savedCatalogue?.merchant_name || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()
  && savedItemNames.length > 0
  && savedItemNames.every((sn) => {
    const a = String(sn).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    return !products.some((pp) => String((pp && pp.name) || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() === a);
  });
const wantsShopWork = isEditRequest || isComplete
  || String(intent || '').toUpperCase().indexOf('UPDATE_STORE') >= 0
  || String(intent || '').toUpperCase().indexOf('BUILD_STORE') >= 0;
// A BUSINESS NONE OF THESE SHOPS IS, IS A NEW SHOP.
// The question above exists so an edit cannot land on the wrong shop. It also caught merchants
// asking for a new business with no price list yet - "we are odi pharmacy, just a website
// showcasing what we are about, generate it for me" - and answered "which of your 3 websites do
// you want to change?", which is wrong twice: Odi is not one of them, and the merchant asked for a
// new site, not a change. A distinct business name is decisive on its own; it never needed items
// to prove it. (A name that matches one of the shops still gets the question, which is the point.)
const shopNameKey = (v) => String(v || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const requestedNameKey = shopNameKey(name);
const matchesSavedShopName = Boolean(requestedNameKey) && shopChoices.some((sh) => {
  const shName = shopNameKey(sh && (sh.name || sh.slug));
  if (!shName) return false;
  return shName === requestedNameKey || shName.indexOf(requestedNameKey) >= 0 || requestedNameKey.indexOf(shName) >= 0;
});
const newBusinessRequested = requestedNameKey.length >= 2 && !matchesSavedShopName;
// A merchant who NAMES one of their existing shops in their OWN MESSAGE has already answered the
// question, so the guard must not ask it again: "Entropic Samsung S26 to 5,200,000" was being
// answered with "which of your 3 websites do you want to change?".
// The check reads the merchant's typed words, NOT the agent's merchant_name field: on an unnamed
// edit ("change the price") the agent still fills merchant_name with a shop it saw, so trusting
// that field would let an unnamed edit land on whichever shop the model happened to pick - the
// very merge this guard exists to prevent.
const namesShopInMessage = (() => {
  const said = shopNameKey(extractedMessage || '');
  if (!said) return false;
  return shopChoices.some((sh) => {
    const shName = shopNameKey(sh && (sh.name || sh.slug));
    return Boolean(shName) && shName.length >= 3 && said.indexOf(shName) >= 0;
  });
})();
if (needsShopChoice && wantsShopWork && !isMemoryWipe && !isQuestionOnly && !namedNewBusiness && !newBusinessRequested && !namesShopInMessage) {
  // Several shops on this number: the reply lists them so the merchant can point at one.
  const firstShop = String((shopChoices[0] && (shopChoices[0].name || shopChoices[0].slug)) || 'my shop');
  const shopLines = shopChoices.map((sh) => '• ' + String((sh && (sh.name || sh.slug)) || '')).join(String.fromCharCode(10));
  const pickReply = [
    'You have ' + shopChoices.length + ' websites on this number:',
    shopLines,
    '',
    'Which one do you want to change? Start your message with the shop name, for example "' + firstShop + ' price 5000".',
    'Send a new business name and what it sells to build another separate website.'
  ].join(String.fromCharCode(10));
  return [{
    json: {
      isSearch: false,
      isComplete: false,
      isQuestionOnly: true,
      intent: 'ANSWER_ONLY',
      slug: '',
      locationMissing: false,
      parsedData: {},
      missingPrompt: pickReply,
      senderPhone: phone,
      businessPhone: shopLine,
      customerLocationPin: null,
      isLocationPin: hasSharedPin
    }
  }];
}

if (isQuestionOnly && isComplete) {
  const askReply = conversationalReply.length > 2
    ? conversationalReply
    : 'Here is your shop as it stands. Tell me what you would like changed and I will apply it.';
  return [{
    json: {
      isSearch: false,
      isComplete: false,
      isQuestionOnly: true,
      intent: 'ANSWER_ONLY',
      slug: slug,
      locationMissing: locationMissing,
      parsedData: parsed || {},
      missingPrompt: askReply,
      senderPhone: phone,
      businessPhone: shopLine,
      customerLocationPin: null,
      isLocationPin: hasSharedPin
    }
  }];
}

// The agent sets user_is_finished_speaking:false whenever it still has something to say, so
// gating the publish on it means a finished store never goes live. Publish whenever the required
// business details are present; keep asking only while a required field is still missing.
const shouldAsk = !isComplete;
let missingPrompt = '';

if (shouldAsk) {
  if (conversationalReply.length > 5) {
    missingPrompt = conversationalReply;
  } else {
    missingPrompt = `Welcome to X-Link! I need just a bit more info:\n` + missingFields.map(f => `• *${f}*`).join('\n') + `\nReply with these details!`;
  }
} else {
  missingPrompt = conversationalReply.length > 5 ? conversationalReply : `Got it! I am updating your storefront right now. Give me just a few seconds... 🚀`;
}

// THE CONFIRMATION IS BUILT HERE, NOT BY THE MODEL.
// The merchant asked for their edit to be confirmed the same way every time: what was applied,
// and whether anything went wrong. So the reply is assembled from the real before/after
// comparison above - never from a sentence the model wrote, which changed wording every run and
// sometimes claimed an edit that never touched the shop.
// Did this shop already exist before this message? An edit to a shop the merchant already owns
// refreshes the page they already have, so the address does not need to be repeated on every
// single change - it only goes out on the first build or when they ask for it.
const hadShopBefore = Boolean(savedCatalogue && (
    (Array.isArray(savedCatalogue.products_and_services) && savedCatalogue.products_and_services.length)
    || String(savedCatalogue.merchant_name || '').trim()
)) || Boolean(String(existingSlug || '').trim());

if (intent === 'UPDATE_STORE' && isEditRequest) {
    const shopLink = 'https://orchid-frigatebird.pikapod.net/webhook/storefront?slug=' + slug;
    // The link goes out only when the message actually asks for it. Otherwise the merchant is
    // told the site is already updated and to refresh the page they have open.
    const wantsLinkNow = !hadShopBefore
        || /(link|hyperlink|web address|website address|send (me )?(the )?link|send (me )?(the )?site|where is my (site|shop|website|link)|share (the )?(link|site)|what is my (link|address))/i.test(String(msgText || ''));
    const applied = editChangeList.filter(Boolean);
    const extras = editOtherChanges.filter(Boolean);
    const lines = [];
    // The assistant's own sentence opens the message, so it speaks to the merchant in its own
    // professional words about the change - but only after every false-completion claim is
    // removed. A sentence that says "done" or "published" before the shop is rebuilt is the
    // exact lie this message exists to prevent, so those words are stripped here and the
    // measured receipt below always follows.
    const agentLine = (() => {
        // The assistant's own sentence is kept whole - only a sentence that claims the work is
        // already finished is dropped, because at this point the shop has not been rebuilt yet.
        // Words are never stripped out of a sentence: doing that produced broken English like
        // "I have the iPhone price. It now.", which is worse than saying nothing.
        const text = String(conversationalReply || '').replace(new RegExp(String.fromCharCode(10) + '|' + String.fromCharCode(13), 'g'), ' ').trim();
        if (!text) return '';
        // Escaped for the template literal this code lives in: the runtime must see real word
        // boundaries, not the backspace character a single backslash produces.
        const CLAIM = new RegExp('(^|' + '\\b' + ')(done|finished|published|all set|already)(\\b' + '|$)|' + '\\b' + '(is|are|has been|have been|was|were|now)\\s+(done|saved|published|live|updated|applied|ready|refreshed|changed|finished)' + '\\b', 'i');
        const sentences = text.split(/(?<=[.!?])\s+/).map((x) => x.trim()).filter(Boolean);
        const honest = sentences.filter((x) => !CLAIM.test(x));
        const kept = honest.join(' ').trim();
        if (kept.length < 3) return '';
        return kept.length > 220 ? kept.slice(0, 217).trim() + '...' : kept;
    })();
        if (agentLine) { lines.push(agentLine); lines.push(''); }
    lines.push('✅ *Applied to ' + String(parsed && parsed.merchant_name || 'your shop').trim() + '*');
    if (applied.length || extras.length) {
        applied.concat(extras).forEach(l => lines.push(l));
    } else {
        lines.push('• Your shop is unchanged: I could not find a difference to apply.');
    }
    lines.push('');
    lines.push('• Everything else on your shop is untouched.');
    lines.push('');
    if (orderIssue) {
        lines.push('⚠️ *One part did not go through:* ' + orderIssue);
    } else {
        lines.push('✅ *Problem with the edit: none.* Every change you asked for went through.');
    }
    lines.push('');
    if (wantsLinkNow) {
        lines.push('🌐 ' + shopLink);
    } else {
        lines.push('🔄 *Your website is already updated.* Open the page you have and refresh it - the change is there now.');
        lines.push('Need the address again? Just say *send link*.');
    }
    lines.push('');
    lines.push('Tell me another change any time.');
    editConfirmReply = lines.join(String.fromCharCode(10));
    editConfirmLines = applied.concat(extras);
    editConfirmIssue = orderIssue;
    orderThreadReply = editConfirmReply;
    conversationalReply = editConfirmReply;
}

return [{
  json: {
    isSearch: false,
    isComplete: isComplete,
    isQuestionOnly: false,
    intent: intent,
    slug: slug,
    locationMissing: locationMissing,
    // NEVER STORE THE "THIS MESSAGE WAS FRONT-PAGE-ONLY" FLAG WITH THE SHOP.
    // That flag means "this one message only styled the front page, so leave the cards alone".
    // It was being written into the saved catalogue, so it came back true on the NEXT message -
    // every later edit then restored the old product list and skipped the picture work entirely.
    // That is why a photo sent for a product never reached its card. It is per-message state and
    // must not outlive the message it came from.
    parsedData: (() => {
      const clean = (parsed && typeof parsed === 'object') ? parsed : {};
      const out = {};
      for (const k in clean) { if (k !== 'front_page_only') out[k] = clean[k]; }
      return out;
    })(),
    missingPrompt: missingPrompt,
    senderPhone: phone,
      businessPhone: shopLine,
    // The static edit confirmation, carried all the way to the message that is actually
    // delivered, so the merchant is told exactly what was applied and whether anything failed.
    isEditRequest: isEditRequest,
    // TRUE when this run builds a SECOND, SEPARATE website on a number that already owns one.
    // Carried to the page, store-row and catalogue writers so the new business gets its own page
    // and its own row instead of overwriting the shop that was already there.
    isNewSiteBuild: isNewSiteBuild,
    site_count: siteCount,
    site_allowance: siteAllowance,
    editConfirmReply: editConfirmReply,
    editConfirmLines: editConfirmLines,
    editConfirmIssue: editConfirmIssue,
    editAppliedNames: editAppliedNames,
    // WHICH CARDS THIS EDIT WAS ACTUALLY ABOUT.
    // Only these may have their picture searched, generated or replaced. A card the merchant did
    // not name keeps the picture it already shows, however many products the catalogue carries.
    editTouchedKeys: editTouchedKeys,
    editPhotoKeys: editPhotoKeys,
    editItemless: editItemless,
    editPicturesUntouched: editPicturesUntouched,
    // Carried forward so the map step can place the shop on the exact point the merchant
    // shared instead of guessing an area.
    customerLocationPin: hasSharedPin ? { lat: sharedPin.lat, lng: sharedPin.lng, name: sharedPin.name || '', address: sharedPin.address || '' } : null,
    isLocationPin: hasSharedPin
  }
}];

const route = $('Validate & Route Intent').first().json || {};
const chosen = String(route.chosenMethod || 'CARD');
const domain = String(route.domainName || '');
const price = String(route.domainPrice || '');
const currency = String(route.domainCurrency || 'USD');

let pay = {};
try { pay = $input.first().json || {}; } catch (e) { pay = {}; }

let reply = '';
if (chosen === 'MOBILE_MONEY') {
  reply = 'Mobile Money selected for *' + domain + '*.' + String.fromCharCode(10) + String.fromCharCode(10) +
    'Send ' + currency + ' ' + price + ' to the X-Link line and reply here with the transaction code.' + String.fromCharCode(10) +
    'As soon as it is confirmed, ' + domain + ' is registered and pointed at your store.';
} else {
  const link = String(pay.approve_url || '');
  if (link) {
    reply = 'Pay securely for *' + domain + '*' + (price ? ' (' + currency + ' ' + price + ' for the first year)' : '') + ':' + String.fromCharCode(10) + String.fromCharCode(10) +
      link + String.fromCharCode(10) + String.fromCharCode(10) +
      'Once payment goes through, the domain is registered and connected straight to your store.';
  } else {
    reply = 'I could not start the card payment for *' + domain + '* just now. Nothing has been charged.' + String.fromCharCode(10) + String.fromCharCode(10) +
      'Reply *1* to try card or PayPal again, or reply *2* to pay by Mobile Money.';
  }
}

return [{ json: { ...route, domainOrderReference: pay.order_id || '', whatsapp_reply: reply } }];

const route = $('Validate & Route Intent').first().json || {};
const agentOut = $('Parse Agent Intent').first().json || {};
// Plain string work: the source is stored escaped, so a pattern written here would
// reach the runtime with its slashes stripped and never match.
const asked = String(route.domainRequested || '').toLowerCase().trim()
  .split('?')[0].split('#')[0]
  .replace('https://', '').replace('http://', '').replace('www.', '')
  .split('/')[0]
  .replace(/[^a-z0-9.-]/g, '');
const tldRaw = String(route.domainTld || '').toLowerCase().trim().replace('.', '').split('.')[0];

// The merchant may write either the whole name (acmecorp.com) or only the name plus the ending
// they want (acmecorp, .com). Both shapes resolve to one candidate the registrar can check.
let candidate = asked;
if (candidate && candidate.indexOf('.') < 0 && tldRaw) candidate = candidate + '.' + tldRaw;
const hasTld = candidate.indexOf('.') > 0;

// A name the merchant never gave cannot be guessed: ask for it instead of pricing a random one.
if (!candidate || !hasTld) {
  return [{
    json: {
      ...route,
      needsDomainName: true,
      domainCandidate: '',
      senderPhone: route.senderPhone || (agentOut.senderPhone || ''),
      missingPrompt: 'Sure - what exact web address would you like? For example *mybusiness.com* or *mybusiness.co.ug*. Tell me the name and I will check whether it is free and what it costs.'
    }
  }];
}

return [{
  json: {
    ...route,
    needsDomainName: false,
    domainCandidate: candidate,
    domainTld: tldRaw || candidate.split('.').slice(1).join('.'),
    senderPhone: route.senderPhone || (agentOut.senderPhone || '')
  }
}];

const prepped = $('Prepare Domain Check').first().json || {};
let res = {};
try { res = $input.first().json || {}; } catch (e) { res = {}; }

const result = res.result || res.body?.result || res.body || res;
const list = Array.isArray(result.domains) ? result.domains : [];
const entry = list.length > 0 ? list[0] : {};
const candidate = String(entry.name || prepped.domainCandidate || '').toLowerCase();
const registrable = entry.registrable === true;
const pricing = entry.pricing || {};
const price = String(pricing.registration_cost || '').trim();
const currency = String(pricing.currency || 'USD').toUpperCase();
const reason = String(entry.reason || '').trim();

const reasonText = {
  domain_unavailable: 'that name is already taken.',
  domain_premium: 'that name is premium priced and cannot be sold here.',
  extension_not_supported: 'that ending is not supported.',
  extension_not_supported_via_api: 'that ending can only be bought through the registrar dashboard.',
  extension_disallows_registration: 'that ending is not accepting new registrations.'
}[reason] || 'that name cannot be bought right now.';

// The registrar can be unreachable or the credential rejected. Say so plainly instead of
// telling the merchant a name is taken when the check never actually answered.
const checkFailed = !res.success && Object.keys(entry).length === 0;

let reply = '';
if (checkFailed) {
  reply = 'I could not reach the domain checker just now, so I cannot confirm whether ' + (candidate || 'that name') + ' is free. Please try again in a moment - your store itself is unaffected.';
} else if (registrable) {
  reply = 'Good news - *' + candidate + '* is available' + (price ? ' at ' + currency + ' ' + price + ' for the first year.' : '.') + String.fromCharCode(10) + String.fromCharCode(10) + 'How would you like to pay for it?' + String.fromCharCode(10) + '1 - Card or PayPal' + String.fromCharCode(10) + '2 - Mobile Money' + String.fromCharCode(10) + String.fromCharCode(10) + 'Reply with 1 or 2 and I will set it up on your store.';
} else {
  const stem = candidate.indexOf('.') > 0 ? candidate.slice(0, candidate.indexOf('.')) : candidate;
  const ending = candidate.indexOf('.') > 0 ? candidate.slice(candidate.indexOf('.')) : '';
  reply = 'Sorry - ' + reasonText + String.fromCharCode(10) + String.fromCharCode(10) + 'We can try another name, for example *' + stem + 'store' + ending + '*, *' + stem + 'ug' + ending + '* or *my' + stem + ending + '*. Send me any name and I will check it straight away.';
}

return [{
  json: {
    ...prepped,
    domainName: candidate,
    domainAvailable: registrable,
    domainCheckFailed: checkFailed,
    domainReason: reason,
    domainPrice: price,
    domainCurrency: currency,
    // The registrar quotes the registration cost in its own currency. When that is USD the same
    // figure IS the card amount; when it is anything else there is no dollar figure to charge and
    // the card path must say so rather than send an empty or wrongly-scaled amount.
    domainPriceUsd: String(currency === 'USD' ? price : ''),
    domainAwaitingPayment: registrable,
    whatsapp_reply: reply
  }
}];

let inputJson = $input.first().json || {};
let parsedData = inputJson.parsedData || {};
let intent = inputJson.intent || 'BUILD_STORE';

const isUsableImage = (u) => typeof u === 'string' && /^(https?:\/\/|data:image\/)/i.test(u.trim()) && !u.includes('placehold');

// ── 1. Capture the merchant's uploaded photo: ImgBB result first, then webhook metadata ──
const uploadCandidates = [];
try {
  // Settle Photo Hosting1 holds the address whichever host answered, or none of them.
  const up = $('Settle Photo Hosting1').first().json || {};
  const d = up.data || up;
  uploadCandidates.push(up.hostedPhotoUrl, d.display_url, d.url, d.image && d.image.url, d.thumb && d.thumb.url);
} catch (e) {
  try {
    const up = $('Upload Merchant Photo1').first().json || {};
    const d = up.data || up;
    uploadCandidates.push(d.display_url, d.url, d.image && d.image.url, d.thumb && d.thumb.url);
  } catch (e2) {}
}
try {
  const wa = $('Parse WhatsApp Message').first().json || {};
  uploadCandidates.push(
    wa.uploaded_image_url, wa.image_url, wa.imageUrl, wa.user_uploaded_image,
    wa.rawMessage && wa.rawMessage.image && wa.rawMessage.image.link,
    wa.rawMessage && wa.rawMessage.document && wa.rawMessage.document.link
  );
} catch (e) {}
uploadCandidates.push(inputJson.uploaded_image_url, inputJson.image_url, inputJson.imageUrl, inputJson.user_uploaded_image);

// A FLYER is a design reference, not a product photo - never claim it for a card.
const imageRole = String(parsedData.image_role || '').toUpperCase();
// The vision step names the picture explicitly; that verdict wins over the agent's own reading,
// because the agent never saw the file. A photo identified as a product shot is ALWAYS a product
// shot - otherwise a merchant's own picture was treated as decoration and replaced.
const visionProductPhoto = String(inputJson.uploadedProductPhoto || '').trim();
const visionRole = String(inputJson.imageRole || '').toUpperCase();
const uploadIsProductPhoto = Boolean(visionProductPhoto) || imageRole === 'PRODUCT_PHOTO';

let userUploadedImage = '';
for (const candidate of uploadCandidates) {
  if (isUsableImage(candidate)) { userUploadedImage = String(candidate).trim(); break; }
}
// The hosted URL of the picture identified on this message, when there is one.
if (visionProductPhoto && isUsableImage(visionProductPhoto)) userUploadedImage = visionProductPhoto;

const products = Array.isArray(parsedData.products_and_services) ? parsedData.products_and_services : [];

// ── ONLY THE ITEMS THIS MESSAGE IS ABOUT MAY BE REDRAWN ──────────────────────
// A merchant who changes one price or one picture must get exactly that change. Every card used
// to be sent back through the search/generator pipeline on every message, so an edit they never
// asked for came back with different product photos - the complaint this block exists to end.
// The router marked the edit and which cards it named; here each card decides for itself whether
// it is in scope. A card outside the scope is marked pictureLocked, which means: keep the picture
// that is already on the shop, do not search for a new one, do not generate one.
const editScopeActive = (() => {
  try {
    const routedEdit = inputJson.isEditRequest === true || String(intent || '').toUpperCase() === 'UPDATE_STORE';
    if (!routedEdit) return false;
    // A ROUTED EDIT ALWAYS NARROWS TO WHAT WAS ASKED.
    // isEditRequest alone is not enough: an edit can reach this stage down the rebuild path (a
    // first build that has just been saved, or a run started from the trigger directly), and on
    // that path no scope arrives at all. A shop with products already saved is still a shop whose
    // unnamed cards must not be repainted, so the absence of an explicit scope means "nothing
    // beyond the items named is in scope".
    return true;
  } catch (e) { return false; }
})();
const photoScope = (() => {
  if (!editScopeActive) return null;
  const touched = Array.isArray(inputJson.editPhotoKeys) ? inputJson.editPhotoKeys.map(k => String(k || '')) : [];
  // No picture is in scope: either no item was named, or the message only changed prices, names
  // or wording. Either way every card keeps the picture it already shows.
  if (inputJson.editPicturesUntouched === true) return { keys: [], itemless: true };
  return { keys: touched, itemless: inputJson.editItemless === true };
})();
const scopeKeyOf = (v) => String(v || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const inPhotoScope = (name) => {
  if (!photoScope) return true;              // not an edit: a build draws every card
  if (photoScope.itemless) return false;     // a shop-level edit names no card
  const k = scopeKeyOf(name);
  return Boolean(k) && photoScope.keys.indexOf(k) >= 0;
};

// A MESSAGE ABOUT THE FRONT PAGE IS NOT A MESSAGE ABOUT THE PRODUCTS.
// "Use this as my home page picture" used to travel the whole picture pipeline: every saved card
// was searched again, the results were written over the pictures the merchant already had, and
// the shop came back with different product photos than it went in with. The routing step now
// marks such a message, and here that means the cards keep the pictures they already carry.
const frontPageOnlyMessage = (() => {
  try { return parsedData.front_page_only === true; } catch (e) { return false; }
})();

// Photos are per SHOP, not per number. This is the key this shop's photo archive is read under.
// THIS SHOP'S OWN ADDRESS - not the one it replaced. previous_slug points at the address a shop
// MOVED AWAY from, so reading it first pulled the old shop's photo archive into the new one: that
// is how a brand new pharmacy was built with a food shop's picture at the top of its page.
const photoScopeKey = (() => {
  const slugNow = String((parsedData && (parsedData.slug || parsedData.previous_slug)) || '').trim();
  return String(inputJson.senderPhone || inputJson.merchantPhone || '').replace(/[^0-9]/g, '') + (slugNow ? '|' + slugNow : '');
})();
// A FRONT PAGE PICTURE IS NOT A PRODUCT PICTURE, whichever shop sent it.
// The compiler refuses to print an uploaded product shot as the front page, but the page builder
// decides the front page picture FIRST, off the item itself, so that refusal never reached it. The
// vision verdict now travels with the item, so one rule holds in both places.
let uploadedPhotoRole = String(inputJson.imageRole || '').toUpperCase();
try {
  const firstRecord = Array.isArray(inputJson.merchantPhotoRecords) ? inputJson.merchantPhotoRecords[0] : null;
  if (firstRecord && firstRecord.role) uploadedPhotoRole = String(firstRecord.role).toUpperCase();
} catch (e) {}
const uploadedPhotoIsProduct = Boolean(String(inputJson.uploadedProductPhoto || '').trim())
  || uploadedPhotoRole === 'PRODUCT_PHOTO';
const ownArchivedPhotos = (() => {
  try {
    const sd = $getWorkflowStaticData('global');
    const list = sd && sd.merchantPhotos && sd.merchantPhotos[photoScopeKey];
    return Array.isArray(list) ? list.slice() : [];
  } catch (e) { return []; }
})();
const ownArchivedRecords = (() => {
  try {
    const sd = $getWorkflowStaticData('global');
    const list = sd && sd.merchantPhotoRecords && sd.merchantPhotoRecords[photoScopeKey];
    return Array.isArray(list) ? list.slice() : [];
  } catch (e) { return []; }
})();

// The item the merchant's photo was identified as. When the picture is of one product, it is
// THIS product's picture - so it is matched by name first, and only falls back to the only
// product in the message. Nothing else may take its place.
let uploadedProductName = '';
try { uploadedProductName = String(inputJson.uploadedProductName || '').trim(); } catch (e) {}
// A freshly sent photo always belongs to the product the merchant is talking about, so when a
// photo came in with this message it is placed even on a shop that already has a card.
let freshUpload = '';
try { freshUpload = String(inputJson.uploadedProductPhoto || '').trim(); } catch (e) {}
const singleProductUpload = Boolean(userUploadedImage) && uploadIsProductPhoto && products.length <= 1;
// THE CARD THE MERCHANT NAMED WHEN THEY SENT THE PICTURE.
// The vision step describes what it sees ("a Crochet Handbag"); the merchant describes where it
// goes ("ADD THIS IMAGE ON THE Handcrafted Bags SECTION"). When those two names differ, only the
// merchant's own words identify the card, so the caption is read here and offered to every card
// as a second name for the picture. Read only when this message actually carried a photo.
const captionTargetName = (() => {
  try {
    if (!userUploadedImage) return '';
    const text = String(inputJson.imageCaption || inputJson.caption || '').trim();
    if (!text) return '';
    // "add this image on the X section", "put this on my X card", "use this photo for X".
    const m = text.match(/(?:image|photo|picture|pic)s+(?:on|to|for|in|onto|into)s+(?:thes+|mys+)?(.+?)(?:s+section|s+card|s+item|s+product|s+page)?[.!,]*$/i)
      || text.match(/(?:use|put|place|add)s+(?:this|it|that)s+(?:image|photo|picture|pic)s+(?:on|to|for|in|onto|into)s+(?:thes+|mys+)?(.+?)(?:s+section|s+card|s+item|s+product|s+page)?[.!,]*$/i);
    return m ? String(m[1] || '').trim() : '';
  } catch (e) { return ''; }
})();
// A PICTURE THAT IS TOO POOR TO PRINT IS NOT PUT ON THE CARD AS IT IS.
// When the vision step reports the merchant's photo as blurred, too dark, taken from a screen or a
// plain screenshot, the card it names is NOT given that file. It is given a clean generated picture
// of the same item instead - the item is still the merchant's, only the photograph is redrawn.
// The captured file is kept in their photo record, so nothing is lost and the merchant can always
// send a better shot, but buyers never see the poor one.
const photoNeedsImprovement = (() => {
  try { return inputJson.uploadedPhotoNeedsImprovement === true; } catch (e) { return false; }
})();
const improvementReason = (() => {
  try { return String(inputJson.uploadedPhotoImprovementReason || '').trim(); } catch (e) { return ''; }
})();
let uploadClaimed = false;

const sameProduct = (a, b) => {
  const norm = (v) => String(v || '').toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const A = norm(a).split(' ').filter(Boolean);
  const B = norm(b).split(' ').filter(Boolean);
  if (!A.length || !B.length) return false;
  const singular = (w) => (w.length > 3 ? w.replace(/ies$/, 'y').replace(/(es|s)$/, '') : w);
  const hits = A.filter(w => B.some(u => singular(w) === singular(u))).length;
  return hits / Math.max(A.length, B.length) >= 0.5;
};

const productItems = products.map((product, index) => {
  const rawName = product.name || ('Item ' + (index + 1));
  // The shop this card belongs to, so a generated picture looks like it came from this catalogue.
  const shopKind = String(parsedData.business_category || '').trim() || 'shop';
  const shopPlace = String(parsedData.location || '').trim();

  // The product's own image (agent-extracted or previously saved).
  //
  // A URL the AGENT typed is not trusted as a product picture. The model happily writes a
  // plausible-looking link from memory - a Samsung campaign banner, an Apple Open Graph
  // preview - and because a URL was present this whole branch then marked the card
  // skipSearch true and skipped both the search AND the image generator. That is exactly how
  // the two wrong pictures stayed on the live shop. A web URL only counts when the model
  // identifies it as a picture the MERCHANT sent; anything else falls through to a real search
  // and, if that finds no genuine product photo, to the generator.
  const agentUrl = (v) => (isUsableImage(v) ? String(v).trim() : '');
  const merchantTyped = agentUrl(product.merchant_supplied_image) || agentUrl(product.merchant_image);
  let finalImage = merchantTyped;
  let userPhotoOnThisCard = false;
  // Set when this card must be redrawn by the picture generator instead of using the merchant's
  // captured file (a poor photo or a screenshot). See photoNeedsImprovement above.
  let improveThisCard = false;

  // The merchant's own photo goes on the product it shows. This is placed BEFORE the saved image
  // is considered, because a photo they sent now is the picture they want on the shop now - it is
  // never a lower-priority fallback that a previously saved picture can beat.
  // A PICTURE THE MERCHANT ASSIGNED TO THE FRONT PAGE IS NOT A CARD PICTURE.
  // "I want this as the homepage picture" means the top of their shop. The photo still shows
  // something they sell, so the vision step calls it a product shot of that item - and it was then
  // claimed by that card as well, which is how a home-page change rewrote a product. The sentence
  // that named the front page settles it: the picture goes there and nowhere else, and every card
  // keeps the photo it already had.
  const uploadIsForFrontPage = frontPageOnlyMessage;
  // THE ITEM THE MERCHANT NAMED IN THE CAPTION IS THE ITEM THE PHOTO BELONGS TO.
  // "ADD THIS IMAGE ON THE Handcrafted Bags SECTION" is an instruction naming the card, and the
  // vision step's own reading of the picture was "Crochet Handbag" - a different name for the
  // same thing. Matching only the vision name meant neither the caption name nor the card agreed
  // with it, so the photo was claimed by NO card: it was dropped, the named card was sent to the
  // picture search, and it came back with a generated picture instead of the merchant's own.
  // The caption is the merchant speaking, so it is read first and the vision name second.
  const namesThisProduct = Boolean(uploadedProductName) && sameProduct(uploadedProductName, rawName);
  const captionNamesThisProduct = Boolean(captionTargetName) && sameProduct(captionTargetName, rawName);
  if (userUploadedImage && uploadIsProductPhoto && !uploadClaimed && !uploadIsForFrontPage) {
    const onlyProduct = singleProductUpload;
    // A fresh photo with no recognised name is attached to the one product it could belong to.
    if (namesThisProduct || captionNamesThisProduct || onlyProduct || (!finalImage && !uploadedProductName)) {
      uploadClaimed = true;
      if (photoNeedsImprovement) {
        // Claimed, but NOT printed: this card is handed to the picture generator with the item's
        // name and this poor photo as its reference, so the shop shows a clean picture of the same
        // thing. finalImage stays empty on purpose - the captured file must not reach the page.
        improveThisCard = true;
      } else {
        finalImage = userUploadedImage;
        userPhotoOnThisCard = true;
      }
    }
  }

  // A card only skips the search when it already carries a picture we can trust: the merchant's
  // OWN upload. A URL the agent invented no longer skips anything - it has to be searched and,
  // failing a genuine product photo, generated. An edit still keeps the pictures the shop already
  // has, because re-searching for a price change was what made a simple edit slow.
  // THE PICTURE A CARD ALREADY HAS TRAVELS WITH IT ON A FRONT-PAGE-ONLY MESSAGE.
  // Skipping the search alone left the item with no picture at all, so the card arrived empty and
  // the shop came back with its products stripped of their photos. The saved picture is carried on
  // the item, which is also what lets the page builder recognise it as this card's own.
  if (frontPageOnlyMessage) {
    // A photo sent WITH this message is the merchant talking about that item, so it still lands on
    // its card even on a front-page-only message. The front page and the products are separate,
    // but refusing the card here threw the picture away entirely: nothing was stored and the
    // merchant saw the old photo - or an empty tile - and had no way to tell why.
    if (!finalImage) {
      const savedCardImage = [].concat(Array.isArray(product.images) ? product.images : [], product.img, product.image, product.image_urls)
        .map(u => (isUsableImage(u) ? String(u).trim() : ''))
        .find(Boolean) || '';
      if (savedCardImage) finalImage = savedCardImage;
    }
  }

  let skipSearch = false;
  if (finalImage && !finalImage.includes('placehold') && userPhotoOnThisCard) skipSearch = true;
  // Every card keeps the picture it already has: this is the front-page-only case, and it is the
  // rule that stops a banner change from rewriting the product photos underneath it.
  // ...unless this very message carried a photo that belongs to this card, which must still be
  // looked at and improved rather than skipped over.
  if (frontPageOnlyMessage && !userPhotoOnThisCard && !improveThisCard) skipSearch = true;
  if (merchantTyped && !finalImage.includes('placehold')) skipSearch = true;
  // A card whose merchant picture had to be redrawn still travels the picture pipeline, because
  // THAT is the only route to the generator. Setting skipSearch true here sent the item down the
  // "no search needed" shortcut, which bypasses the inspector AND the generator entirely, so an
  // improved card reached the page with no picture at all and the merchant was asked to send the
  // photo again. It now stays on the search branch; the inspector refuses every searched stranger
  // and hands this card to the generator using its own item name (see improvePhoto in the
  // inspector).
  if (improveThisCard) skipSearch = false;
  // AN ITEM THE MERCHANT DID NOT NAME KEEPS THE PICTURE IT ALREADY HAS.
  // This is the whole point of the scope: its saved picture is carried onto the item (so the page
  // builder recognises it as this card's own) and the search and the generator are both skipped.
  // A card the merchant did name is allowed through even when it already has a picture, because
  // that is the card whose photo they asked to change.
  const pictureLocked = !inPhotoScope(rawName);
  if (pictureLocked) {
    const ownSaved = [].concat(Array.isArray(product.images) ? product.images : [], product.img, product.image, product.image_urls)
      .map(u => (isUsableImage(u) ? String(u).trim() : ''))
      .find(Boolean) || '';
    if (ownSaved) { finalImage = ownSaved; skipSearch = true; }
  }
  // A CARD THAT ALREADY SITS ON A SAVED SHOP KEEPS ITS PICTURE, WHATEVER THIS MESSAGE IS ABOUT.
  // Pictures are the merchant's property. Once a card has a picture and the message did not bring
  // a photo for it, that card is not searched again and not redrawn - not on a price change, not on
  // an item added to the catalogue, not on a rebuild. The old behaviour re-searched on every save
  // (which froze in the wrong pictures and cost seconds per build) or redrew them (which replaced
  // pictures the merchant had chosen). A searched picture is only ever a substitute for a picture
  // that does not exist yet, which is the first build case above.

  const cleanName = rawName.replace(/[\(\)\[\]\{\}]/g, ' ').replace(/\s+/g, ' ').trim();
  // SEARCH FOR THE ITEM, NOT FOR A PHOTOGRAPHER.
  // The query used to carry "retail product package studio photography" (or "fresh appetizing food
  // photography", or "professional corporate commercial photography"). Google Images reads those as
  // a description of the WEBSITE being looked for, so it answered with studios advertising their
  // services: the Rhymer Pods search came back with "Coffee Product Photography", "AI product
  // photography API for beauty brands", "Studio Product Photography" and gallery sites - none of
  // them the product, so the strict title gate then refused every one and the card kept no picture.
  // The item name alone returns the item: jbl.com, the brand shop, the retail listing.
  // The category is added only when the item name is a single vague word ("Bags", "Shoes"), so the
  // engine knows what kind of picture is wanted without being told to look for a studio.
  const categoryWord = String(parsedData.business_category || '').replace(/[^A-Za-z0-9& ]+/g, ' ').trim();
  let query = cleanName;
  if (cleanName.split(/s+/).filter(Boolean).length <= 1 && categoryWord) {
    query = cleanName + ' ' + categoryWord;
  }

  return {
    json: {
      ...inputJson,
      ...product,
      cleanName: cleanName,
      searchQuery: query,
      productIndex: index,
      productImage: finalImage,
      userPhotoOnThisCard: userPhotoOnThisCard,
      skipSearch: skipSearch,
      // True only for a card this edit never named: it is drawn with the picture it already has.
      pictureLocked: pictureLocked,
      // A saved shop whose card already carries a picture: the inspector must not hand it to the
      // search or to the generator, whatever else this message changes.
      keepSavedPicture: pictureLocked || Boolean(finalImage) && !improveThisCard,
      // A card redrawn because the merchant's own picture was too poor to print. The inspector
      // sends it straight to the generator, and the captured file is kept only as a reference.
      improvePhoto: improveThisCard,
      improvePhotoReason: improveThisCard ? improvementReason : '',
      photoReference: improveThisCard ? userUploadedImage : '',
      shopKind: shopKind,
      shopPlace: shopPlace,
      aiPrompt: 'E-commerce product photograph of ' + cleanName + ' from ' + shopKind + (shopPlace ? ' in ' + shopPlace : '') +
        '. The ' + cleanName + ' is the only subject, centred, complete and fully in frame, shown at a natural three-quarter angle. ' +
        'Soft diffused studio light from the upper left, gentle shadow under it, seamless very light grey studio backdrop, ' +
        'true-to-life colours, sharp focus across the whole item, honest proportions, square composition with even margins. ' +
        'No people, no hands, no text, no lettering, no logo, no watermark, no collage, no borders, not a screenshot.'
    }
  };
});

// ── The shop's OWN front page picture ─────────────────────────────────────────
// The homepage and the products are two different pictures. The front page carries ONE
// photograph of the business itself, and a product photo is never printed there - that is what
// made a merchant's home page show a single product and made it impossible to change. This item
// travels through the same image pipeline as a product, but it is marked isHomepage with
// productIndex -1, so the inspector never accepts a searched stranger's premises for it and the
// compiler keeps it out of every product card.
const ownedPhotos = new Set();
for (const candidate of uploadCandidates) {
  if (isUsableImage(candidate)) ownedPhotos.add(String(candidate).trim());
}
try {
  const archived = $('Extract Vision Text1').first().json.uploadedImageUrls;
  if (Array.isArray(archived)) archived.forEach(u => { if (isUsableImage(u)) ownedPhotos.add(String(u).trim()); });
} catch (e) {}
try {
  const mine = ownArchivedPhotos;
  if (Array.isArray(mine)) mine.forEach(u => { if (isUsableImage(u)) ownedPhotos.add(String(u).trim()); });
} catch (e) {}

// ── THE FRONT PAGE PICTURE IS NEVER A PRODUCT PICTURE ────────────────────────
// A merchant who sends photos of their goods must be able to do that all day without one of them
// becoming their homepage. Only a picture we know is the SHOP ITSELF - a premises/counter shot, or
// a picture the merchant explicitly assigned to the front page - may fill this slot. Anything
// identified as a product photo is refused here, and so is anything unclassified that is already
// pinned to a product's card or came in with this message as a product shot.
// Did the merchant ASK for the front page picture? "use this as my home page", "change the picture
// at the top", "make this my banner". Their own words are the deciding signal: without them a
// product photo must never become the banner, and with them it must - that is the difference
// between the agent quietly filling a field and the merchant giving an instruction.
const asksForFrontPagePicture = (() => {
  const t = String(inputJson.extractedMessage || '').toLowerCase();
  if (!t) return false;
  const place = /(home ?page|homepage|banner|cover (photo|picture|image)|hero|front page|top of (the|my) (page|site|website|shop)|header (photo|picture|image))/.test(t);
  const verb = /(use|put|make|set|change|replace|apply|upload|add|swap|update|move)/.test(t);
  const picture = /(photo|picture|image|pic|shot)/.test(t);
  return place && (verb || picture);
})();

const shopPhotoForHomepage = (() => {
