const shopKind = String(parsedData.business_category || '').trim() || 'local business';
const shopPlace = String(parsedData.location || '').trim();
const homepagePrompt = 'A warm, inviting wide photograph of the premises of ' + String(parsedData.merchant_name || 'a local business') +
  ', a ' + shopKind + (shopPlace ? ' in ' + shopPlace : '') +
  '. Show the real shop itself: its frontage, counter or shelves and the way it is lit. No people, no hands, no text, no logos, no watermark, photorealistic, bright daylight, wide 16:9 composition.';

const homepageItem = {
