  uploadedPhotoIsProduct: uploadedPhotoIsProduct,
  name: 'Shop front page',
  cleanName: String(parsedData.merchant_name || 'shop') + ' shop interior',
  // The shop's own front page is accepted only when the answer's title names the business, so
  // this query has to be the business name itself - adding "shop premises" pushed the answer
