  searchQuery: String(parsedData.merchant_name || 'shop'),
  productImage: homepagePhoto,
  merchant_supplied_image: homepagePhoto,
  userPhotoOnThisCard: Boolean(homepagePhoto),
  // A real photograph of their own shop skips the pipeline and is used as it is. With none the
