  frontPageName: String(parsedData.merchant_name || '').trim()
};

// The front page item travels in the same batch as the products so one image pipeline keeps
// working, and it is always present so the shop can never end up without its own picture slot.
//
// AT LEAST ONE ITEM ALWAYS TRAVELS THE PICTURE PIPELINE.
// An edit that names no picture locks every card, so every product would skip the search branch
// and the picture stage downstream (which the page builder reads) would have nothing to run on.
// The front page item is the one that keeps that path alive: it still carries its saved picture
// and is marked locked, so the inspector hands the picture straight back without ever generating
// a replacement. Nothing on the shop changes - the pipeline simply still runs.
if (!productItems.some(it => it.json.skipSearch === false)) {
  homepageItem.skipSearch = false;
