const items = $input.all();
const allProductNodes = $('Needs Image Search?').all();
const searchNodes = allProductNodes.filter(n => n.json.skipSearch === false);

// Searches now run concurrently and can finish out of order, so a result must never be paired
// with a product by position alone.
//   1. a response that carries productIndex is matched on it;
//   2. otherwise the search query echoed back by the engine names the product (the query always
//      starts with that product's clean name), which survives any ordering;
//   3. positional pairing stays as the last resort for a fixture with neither.
const byIndex = new Map();
const byQuery = new Map();
const unindexed = [];
const queryKey = (q) => String(q || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
for (const n of searchNodes) {
  const key = queryKey(n.json.cleanName);
  if (key && !byQuery.has(key)) byQuery.set(key, n.json.productIndex);
}
for (const it of items) {
  const j = (it && it.json) || {};
