const BAD_URL = /(lookaside|instagram|shutterstock|alamy|gettyimages|istockphoto|watermark|placehold|stock)/i;

// Global dedup ledger: seed it with every image already claimed upstream (merchant uploads and
// saved product images) so a searched image can never repeat one that is already on a card.
const usedUrls = new Set();
for (const n of allProductNodes) {
  const claimed = normalizeUrl(n.json.productImage);
  if (claimed) usedUrls.add(claimed);
}

// NO PICTURE TWICE, ACROSS SHOPS. A search engine answers "Samsung Galaxy S26 Ultra" with the
// same handful of pictures whoever asks, so ten tech shops on this platform all ended up showing
// one identical photograph. Every search picture this platform has already printed is remembered
// here, for every merchant, and is refused the second time. A refused card is generated instead,
// so each shop gets its own picture even when the product is the same.
const IMAGE_LEDGER = 'usedSearchImages';
let ledger = [];
let ledgerSet = new Set();
try {
  const sd = $getWorkflowStaticData('global');
  sd[IMAGE_LEDGER] = Array.isArray(sd[IMAGE_LEDGER]) ? sd[IMAGE_LEDGER] : [];
  ledger = sd[IMAGE_LEDGER];
  ledgerSet = new Set(ledger);
} catch (e) { ledger = []; ledgerSet = new Set(); }
for (const u of ledgerSet) usedUrls.add(u);
const rememberImage = (url) => {
  if (!url) return;
  try {
    const sd = $getWorkflowStaticData('global');
    const list = Array.isArray(sd[IMAGE_LEDGER]) ? sd[IMAGE_LEDGER] : [];
    if (list.indexOf(url) < 0) list.push(url);
    // Bounded so a long-running platform cannot grow this without limit.
