    }
    if (shopPhoto) {
      usedUrls.add(shopPhoto);
      rememberImage(shopPhoto);
      results.push({ json: { ...product, finalImageUrl: shopPhoto, needsAiGeneration: false, imageCheck: 'SEARCHED_SHOP_PHOTO' } });
    } else {
      results.push({ json: { ...product, finalImageUrl: '', needsAiGeneration: false, imageCheck: 'NO_SHOP_PHOTO' } });
    }
    continue;
  }
  if (frontPage) {
    results.push({ json: { ...product, finalImageUrl: '', needsAiGeneration: false, imageCheck: 'NO_SHOP_PHOTO' } });
    continue;
  }
  // A CARD WHOSE OWN PHOTO WAS TOO POOR TO PRINT IS CLEANED UP, NEVER ASKED FOR AGAIN.
  // This is the one job the picture generator keeps: the merchant's blurred, dark or
  // screen-captured picture still names the item, so a pixel-clear picture of THAT item is drawn
  // from their own file. No searched picture is accepted here - somebody else's stock photo is not
  // a repair - and the merchant is never told to send the picture again.
  if (product.improvePhoto === true && mayImproveOwnPhoto) {
    results.push({
      json: {
        ...product,
        finalImageUrl: '',
        needsAiGeneration: true,
        imageCheck: 'IMPROVE_PHOTO',
        photoReference: String(product.photoReference || product.productImage || ''),
        aiPrompt: product.aiPrompt || ('A clean, sharp e-commerce product photograph of ' + String(product.cleanName || 'the item') +
          '. The item is the only subject, centred, complete and fully in frame, shown at a natural three-quarter angle. ' +
          'Soft diffused studio light from the upper left, gentle shadow under it, seamless very light grey studio backdrop, ' +
          'true-to-life colours, sharp focus across the whole item, honest proportions, square composition with even margins. ' +
          'No people, no hands, no text, no lettering, no logo, no watermark, no collage, no borders, not a screenshot.')
      }
    });
    continue;
  }
  let validUrl = '';

  // Text match: a result that shares no meaningful word with the product name is very likely
  // wrong - a brand campaign banner, or a different product entirely.
  const productWords = words(product.cleanName || product.name);
  const sharesWord = (title) => {
    const tw = words(title);
    for (const w of tw) {
      for (const pw of productWords) {
        if (w === pw) return true;
        // Accept substring overlap for compound words (e.g. smartphone vs phone).
        if ((w.length >= 4 && pw.includes(w)) || (pw.length >= 4 && w.includes(pw))) return true;
      }
    }
    return productWords.length === 0;
  };

  for (const img of images) {
    const title = String(img.title || '');
    const w = Number(img.original_width || img.width || 0);
    const h = Number(img.original_height || img.height || 0);
    // Only the full-size original is usable; a thumbnail URL is refused outright.
    const url = normalizeUrl(img.original);
    if (!url || !url.startsWith('https://')) continue;
    if (BAD_URL.test(url)) continue;
    const lower = url.toLowerCase();
    let badToken = false;
    for (const token of BAD_URL_TOKENS) { if (lower.includes(token)) { badToken = true; break; } }
    if (badToken) continue;
    if (usedUrls.has(url)) continue;
    if (BAD_TITLE.test(title)) continue;
    if (w > 0 && h > 0) {
      if (w < MIN_SIDE || h < MIN_SIDE) continue;
      if (w / h > MAX_WIDE || h / w > MAX_TALL) continue;
    } else if (!sharesWord(title)) {
      // No size information and no title match: too risky to print on a shop.
      continue;
    }
    // The picture has to be this product: the engine says so, or the title names it.
    if (!(img.is_product || sharesWord(title))) continue;
    validUrl = url;
    break;
  }

  if (validUrl) {
    usedUrls.add(validUrl);
    // Remembered platform-wide, so no other shop is ever given this same photograph.
    rememberImage(validUrl);
    results.push({ json: { ...product, finalImageUrl: validUrl, needsAiGeneration: false } });
  } else if (product.userPhotoOnThisCard) {
    // THIS product's picture is the merchant's own photo. It is never replaced by a searched or
    // generated stranger's image: the card keeps their photo, and a poor one is cleaned up rather
    // than swapped so the shop still shows what they actually sell.
    results.push({
      json: {
        ...product,
        finalImageUrl: product.productImage,
        needsAiGeneration: false,
        imageCheck: 'MERCHANT_PHOTO'
      }
    });
  } else {
    // NO SEARCHED PICTURE FOR THIS CARD, AND NOTHING DRAWN IN ITS PLACE.
    // This used to hand every unsatisfied card to the picture generator, so a first build full of
    // products nobody had photographed filled up with invented pictures. A card with no honest
    // photograph now keeps an empty picture slot: the page prints the item's initials tile, and the
    // merchant can send a real photograph of that item whenever they want it filled. Generation is
    // reserved for cleaning up a photo they actually sent (the IMPROVE_PHOTO path above).
    results.push({
      json: {
        ...product,
        finalImageUrl: '',
        needsAiGeneration: false,
        imageCheck: 'NO_IMAGE_FOUND',
        aiPrompt: ''
      }
    });
  }
}
return results;

