parameters.jsCode:
// The product this generated image is for. "Read Image Check" is not a node in this workflow;
// reading it threw, which killed the whole run whenever a product needed a generated picture.
// Which item this generated picture belongs to. Read from the inspector by PRODUCT INDEX, not
// by position: with batching the generator, the download and the re-host each run once per item,
// and pairing them on index is the only way a picture cannot land on the wrong card - or be
// dropped because the run order shifted.
// ONE OUTPUT PER INPUT. This node used to return a single item no matter how many pictures were
// generated, so every card except one lost its picture AND the shop's front-page item disappeared
// from the stream altogether - which is why the homepage fell back to a product photo. The picture
// belongs to whichever item asked for it, so every item that came in goes back out.
// Which item each picture is for is read POSITIONALLY from the batch that requested generation:
// n8n keeps the input order through the generator, the download and the re-host, and an item whose
// generation failed still occupies its place in the stream.
let requested = [];
try { requested = $('Needs AI Generation?').all(); } catch (e) { requested = []; }
let inspected = [];
try { inspected = $('AI Image Inspector & Fallback Router1').all(); } catch (e) { inspected = []; }
// The picture the generator itself returned. That link is served straight from Meta's own CDN and
// needs no upload step, so a picture still shows when the image host is down (imgbb returns 503)
// instead of the card silently losing its photo.
let generated = [];
try { generated = $('Download Generated Image').all(); } catch (e) { generated = []; }

const incoming = $input.all();
if (!incoming.length) return [];

const results = [];
for (let i = 0; i < incoming.length; i++) {
  const src = (incoming[i] && incoming[i].json) || {};
  let hosted = '';
  // THE REHOSTED COPY WINS OVER META'S OWN LINK.
  // Meta returns the picture on fbcdn behind a signature that expires, so a card saved with
  // that address shows a broken image a few hours later. The permanent rehost is what the shop can
  // actually keep, so it is preferred; Meta's link is only the fallback for when rehosting failed.
  // THE HOST ANSWER IS NESTED ONE LEVEL DEEPER THAN IT LOOKS.
  // freeimage.host (and imgbb) reply with status_code, success and image at the top of the body,
  // while imgbb wraps the same fields one level down under "data". Reading only the wrapped form
  // therefore always found nothing, so even a perfectly uploaded copy was thrown away and the card
  // fell back to Meta's expiring fbcdn link - which is exactly the broken picture the shop showed.
  // Every level is tried now, so a successful upload is never mistaken for a failed one.
  try {
    // imgbb wraps its answer in a data field; freeimage.host does not - it puts status_code,
    // image straight on the body. Reading only the wrapped form therefore found nothing for every
    // freeimage.host upload, which is every generated picture, so the card fell back to Meta's
    // expiring fbcdn link. Both shapes are read here.
    const d = (src.data && typeof src.data === 'object') ? src.data : src;
    const inner = (d.image && typeof d.image === 'object') ? d.image : {};
    const up = (d.success && d.success.image && typeof d.success.image === 'object') ? d.success.image : {};
    hosted = String(
      d.display_url || up.display_url || inner.display_url ||
      (typeof d.image === 'string' ? d.image : '') ||
      d.url || up.url || inner.url ||
      (d.thumb && d.thumb.url) || (up.thumb && up.thumb.url) || ''
    ).trim();
  } catch (e) { hosted = ''; }
  // Declared here as well because a Code node cannot see another node's variables.
  const isExpiringLink = (u) => /[?&]oe=[0-9A-F]+/i.test(String(u || '')) || /fbcdn[.]net/i.test(String(u || ''));
  if (!hosted || isExpiringLink(hosted)) {
    let permanent = '';
    try {
      const g = (generated[i] && generated[i].json) || {};
      const first = (g.data && g.data[0]) || {};
      permanent = String(first.url || (g.image && g.image.url) || '').trim();
    } catch (e) { permanent = ''; }
    if (permanent && !isExpiringLink(permanent)) hosted = permanent;
  }
  if (!hosted) {
    try {
      const g = (generated[i] && generated[i].json) || {};
      const first = (g.data && g.data[0]) || {};
      hosted = String(first.url || (first.b64_json ? '' : '') || '').trim();
    } catch (e) { hosted = ''; }
  }
  // inspector, then the picture's own echoed data. Never leave the item without its identity -
  // losing it is what dropped the front-page slot and let a product photo fill the banner.
  let prev = (requested[i] && requested[i].json) || (inspected[i] && inspected[i].json) || {};
  results.push({
    json: {
      ...prev,
      ...src,
      ...prev,
      finalImageUrl: hosted,
      needsAiGeneration: false,
      generationFailed: hosted ? false : true,
      imageCheck: hosted ? 'GENERATED' : 'GENERATION_FAILED',
      generatedImageTip: hosted ? '' : 'the picture generator could not be reached - try again in a moment'
    }
  });
}
return results;

const res = $input.first().json || {};

// A rate is only usable when it is a real, positive number. Anything else means no rate.
const clean = (v) => {
  const n = Number(v);
  return (isFinite(n) && n > 0) ? n : 0;
};

let source = {};
try { source = (res && res.data && res.data.rates) ? res.data.rates : (res.rates || {}); } catch (e) { source = {}; }
const rates = {};
for (const code in source) {
  const v = clean(source[code]);
  if (v > 0) rates[String(code).toUpperCase()] = v;
}

const ugx = clean(rates.UGX);
const updated = String(res.time_last_update_utc || res.date || '').trim();

// What the page falls back to when ITS OWN fetch cannot run (a buyer's phone on a bad network, or a
// privacy setting that blocks the request): the same published figure this build just read. That is
// the whole point of fetching here - the page starts from a real rate instead of a number in code.
const fallbackRates = {};
// Only the currencies PayPal settles in are needed on the page before its own fetch answers.
['USD','EUR','GBP','AUD','CAD','CHF','HKD','JPY','MXN','NOK','PHP','PLN','SEK','SGD','THB','CZK','DKK','HUF','ILS','MYR','BRL','NZD','TWD','RUB'].forEach((c) => {
  if (rates[c] > 0) fallbackRates[c] = rates[c];
});

return [{
  json: {
    ugx_per_usd: ugx,
    usd_rates: rates,
    fallback_rates: fallbackRates,
    rates_updated: updated,
    rates_ok: ugx > 0,
    rates_note: ugx > 0
      ? ('Live rate: 1 USD = ' + ugx.toLocaleString('en-US') + ' UGX' + (updated ? ' (published ' + updated + ')' : ''))
      : 'No usable exchange rate was published just now, so the last recorded rate is used. No rate is ever guessed.'
  }
}];

// THE PICTURE IS READ FROM WHATEVER ARRIVES HERE.
// Normally this is the pixel-clear copy made by "Make Photo Pixel Clear1". If that image tool is
// unavailable on the host it hands its own input straight on instead, so the bytes on this item
// are then the merchant's original download. Either way the picture is read exactly once, and the
// download is used as the last resort so a photo message can never be lost to an image step.
let imageBuffer = null;
try {
  imageBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) { imageBuffer = null; }
if (!imageBuffer || !imageBuffer.length) {
  const fallbackSources = ['Make Photo Pixel Clear1', 'Download Image Binary1'];
  for (const name of fallbackSources) {
    try {
      const bin = $(''.concat(name)).first().binary;
      const raw = bin && (bin.data || bin[Object.keys(bin || {})[0]]);
      if (raw && raw.data) { imageBuffer = Buffer.from(String(raw.data), 'base64'); break; }
    } catch (e) {}
  }
}
if (!imageBuffer || !imageBuffer.length) {
  throw new Error('The merchant photo could not be read from the message.');
}
const base64 = imageBuffer.toString('base64');
// The Meta vision model reads the picture from these bytes. A hosted link (imgbb) is refused
// with media_url_not_fetchable, so the image itself is carried forward as a data URL and every
// later image step uses this instead of a URL.
const sniff = imageBuffer.slice(0, 12);
let detectedMime = '';
if (sniff[0] === 0xFF && sniff[1] === 0xD8) detectedMime = 'image/jpeg';
else if (sniff.slice(0, 8).toString('hex') === '89504e470d0a1a0a') detectedMime = 'image/png';
else if (sniff.slice(0, 4).toString('ascii') === 'RIFF' && sniff.slice(8, 12).toString('ascii') === 'WEBP') detectedMime = 'image/webp';
else if (sniff.slice(0, 3).toString('ascii') === 'GIF') detectedMime = 'image/gif';
$input.item.json.imageBase64 = base64;
$input.item.json.imageMime = detectedMime || 'image/jpeg';
$input.item.json.imageDataUrl = 'data:' + (detectedMime || 'image/jpeg') + ';base64,' + base64;
$input.item.json.imageBytes = imageBuffer.length;
return $input.item;

// The picture itself, carried forward from Convert Image to Base1. It is the truth about this
// message: if these bytes exist the photo WAS read, whatever the image hosts did.
let base = {};
try { base = $('Convert Image to Base1').first().json || {}; } catch (e) { base = {}; }
const hasBytes = Boolean(base.imageDataUrl);

// Every hosted address attempted, from either host, in order of preference.
const candidates = [];
const collect = (nodeName) => {
  try {
    $(nodeName).all().forEach((n) => {
      const j = (n && n.json) || {};
      const d = j.data || j;
      const img = (d && d.image) || {};
      const thumb = (d && d.thumb) || {};
      candidates.push(d.display_url, img.url, d.url, thumb.url);
    });
  } catch (e) {}
};
collect('Upload Merchant Photo1');
collect('Upload Merchant Photo Backup1');

const hosted = candidates.map(u => (typeof u === 'string' ? u.trim() : '')).find(u => /^https?:\/\//i.test(u) && !u.includes('placehold')) || '';

return [{ json: {
  ...base,
  // Kept so every later step sees the same field it always read.
  hostedPhotoUrl: hosted,
  // True when the photo was read from its own bytes even though no host gave us a link.
  photoHosted: Boolean(hosted),
  photoReadable: hasBytes,
  photoHostingFailed: hasBytes && !hosted,
  display_url: hosted,
  url: hosted,
  data: { display_url: hosted, url: hosted }
} }];

const originalText = $('Parse WhatsApp Message').first().json.extractedMessage || 'No caption provided';
let aiAnalysis = 'No Vision Output';
try {
  if ($json.choices && $json.choices[0] && $json.choices[0].message && typeof $json.choices[0].message.content === 'string') {
    aiAnalysis = $json.choices[0].message.content;
  } else if (typeof $json.output_text === 'string') {
    aiAnalysis = $json.output_text;
  }
} catch (e) {}

const prev = $('Parse WhatsApp Message').first().json;
const phone = String(prev.senderPhone || 'unknown');

// The photo the merchant just sent, now hosted. This URL is what must end up on the product
// card, so it is put in front of the agent instead of being guessed at later.
let hostedUrl = '';
try {
  // The address from either image host. Empty when both hosts are down, in which case the picture
  // is still READ from its bytes below - it simply has no public link to print.
  const up = $('Settle Photo Hosting1').first().json || {};
  const d = up.data || up;
  hostedUrl = String(up.hostedPhotoUrl || d.display_url || d.url || (d.image && d.image.url) || (d.thumb && d.thumb.url) || '').trim();
} catch (e) {
  try {
    const up = $('Upload Merchant Photo1').first().json || {};
    const d = up.data || up;
    hostedUrl = String(d.display_url || d.url || (d.image && d.image.url) || (d.thumb && d.thumb.url) || '').trim();
  } catch (e2) {}
}

// Photos arrive one WhatsApp message at a time, so they are collected per SHOP here.
// The archive is keyed on the NUMBER AND THE SHOP, never the number alone: a merchant running
// several businesses on one number keeps a separate photo archive for each, so a picture sent for
// one shop can never surface on another shop's cards or front page.
const archiveKey = (() => {
  let shopSlug = '';
  try {
    const rowsC = $('Lookup Saved Catalogue1').all().map(r => r.json || {});
    const mine = rowsC.filter(r => String(r.store_slug || '').trim() && String(r.merchant_phone || '').replace(/[^0-9]/g, '').slice(-9) === String(phone).replace(/[^0-9]/g, '').slice(-9));
    let hinted = '';
    try { hinted = String($('Lookup Store By Phone1').first().json.slug || '').trim(); } catch (e) {}
    // A PHOTO SENT WHILE A SECOND WEBSITE IS BEING BUILT BELONGS TO THAT WEBSITE.
    // The shop slug came from whatever the last save recorded, so a picture sent as part of
    // building business number two was filed into business number one's archive - and then came
    // back as the other shop's banner or gallery. A build that is explicitly a NEW site has no
    // address yet, so its photos wait under the number for this build only.
    let buildingNew = false;
    try { buildingNew = $('Validate & Route Intent').first().json.isNewSiteBuild === true; } catch (e) {}
    if (buildingNew) shopSlug = '';
    if (!shopSlug && hinted && mine.some(r => String(r.store_slug).trim() === hinted)) shopSlug = hinted;
    if (!shopSlug) {
      const sdA = $getWorkflowStaticData('global');
      const cur = String(sdA && sdA.merchants && sdA.merchants[phone] && sdA.merchants[phone].currentSlug || '').trim();
      if (cur && mine.some(r => String(r.store_slug).trim() === cur)) shopSlug = cur;
    }
    if (!shopSlug && mine.length === 1) shopSlug = String(mine[0].store_slug).trim();
  } catch (e) {}
  return String(phone).replace(/[^0-9]/g, '') + (shopSlug ? '|' + shopSlug : '');
})();
let uploadedImages = [];
try {
  const staticData = $getWorkflowStaticData('global');
  staticData.merchantPhotos = staticData.merchantPhotos || {};
  const list = Array.isArray(staticData.merchantPhotos[archiveKey]) ? staticData.merchantPhotos[archiveKey] : [];
  if (hostedUrl && list.indexOf(hostedUrl) < 0) list.push(hostedUrl);
  while (list.length > 12) list.shift();
  staticData.merchantPhotos[archiveKey] = list;
  uploadedImages = list.slice();
} catch (e) {
  if (hostedUrl) uploadedImages = [hostedUrl];
}

// What the photo actually is. A single picture of one item is a PRODUCT photo; a poster, menu or
// logo is a design reference. This is what stops a merchant's own product shot from being treated
// as decoration and then replaced by a stock picture on their card.
const visionText = String(aiAnalysis || '');
// The label is the model's own JSON key, so it is matched literally (the space in "BUSINESS NAME"
// is a space) and the value stops at the end of its line. The old patterns carried the extra
// escaping a template literal adds, so at runtime they searched for a double backslash and never
// matched: PRODUCT_NAME, PHOTO_QUALITY and IMAGE_TYPE always came back empty, so every photo was
// filed with no product name and no quality verdict.
// The label is the model's own JSON key, so it is matched literally (the space in "BUSINESS NAME"
// is a space) and the value stops at the end of its line. The old patterns carried the extra
// escaping a template literal adds, so at runtime they searched for a double backslash and never
// matched: PRODUCT_NAME, PHOTO_QUALITY and IMAGE_TYPE always came back empty, so every photo was
// filed with no product name and no quality verdict.
const readField = (label) => {
  let m = visionText.match(new RegExp('"?' + label + '"?\\s*[:=]\\s*"?([^"\\n,}]+)', 'i'));
  if (!m) m = visionText.match(new RegExp(label + '\\s*[:=]\\s*(.+)', 'i'));
  if (!m) return '';
  const value = String(m[1]).replace(/^"|"$/g, '').trim();
  return /^(null|none|unknown|undefined)$/i.test(value) ? '' : value;
};const declaredType = readField('IMAGE_TYPE').toUpperCase();
const looksLikeDesign = /FLYER|LOGO|MENU|POSTER/.test(declaredType) || /\bMENU\b|PRICE LIST|BUSINESS CARD/.test(visionText.toUpperCase());
const visionProductName = readField('PRODUCT_NAME');
const declaredQuality = readField('PHOTO_QUALITY').toUpperCase();
// A picture sent with no words, showing one thing, is a product photo of that thing - even when
// the model did not name the type. Anything that reads as a poster or a logo is never claimed.
// A PICTURE OF A SCREEN IS NOT A PRODUCT PHOTO. Screenshots of a phone, a website, a chat, an
// admin table or a receipt were being accepted as product photos and printed on a merchant's
// card. They are never printed: the item is still identified (so the card can be improved by
// generation), but the raw capture itself is kept off the shop.
const isScreenshot = !looksLikeDesign && declaredType === 'SCREENSHOT';
const isProductPhoto = !looksLikeDesign && !isScreenshot && (declaredType === 'PRODUCT_PHOTO' || !declaredType);
const isDesignImage = looksLikeDesign || declaredType === 'LOGO' || declaredType === 'FLYER';
const photoQuality = declaredQuality.indexOf('POOR') >= 0 ? 'POOR' : (declaredQuality.indexOf('GOOD') >= 0 ? 'GOOD' : '');
const productLabel = (visionProductName && visionProductName.toUpperCase() !== 'UNKNOWN') ? visionProductName : '';
// SHOULD THIS PICTURE BE IMPROVED BEFORE IT IS PUT ON THE SHOP?
// The merchant's photo is never thrown away on a guess, but a picture the vision step found poor -
// blurred, too dark, taken from a screen, or a screenshot of the item - is not good enough to be
// the face of their shop. It still NAMES the item, so the card it belongs to is upgraded with a
// clean generated picture of that same item, which is then what buyers see. A good photo is
// always kept exactly as the merchant sent it.
// WAS THE PICTURE ACTUALLY READ? The bytes are the proof, not the link. When both image hosts are
// down the file still reads fine, but there is no URL to print - so the card must be redrawn from
// the item the picture showed instead of being told to keep a picture that has no address.
let photoReadable = false;
try { photoReadable = Boolean($('Settle Photo Hosting1').first().json.photoReadable); } catch (e) { photoReadable = false; }
const photoUnhosted = photoReadable && !hostedUrl;
const needsPhotoImprovement = isScreenshot || photoQuality === 'POOR' || photoUnhosted;
const improvementReason = isScreenshot ? 'screenshot' : (photoQuality === 'POOR' ? 'low quality' : (photoUnhosted ? 'the picture could not be uploaded to a hosting service' : ''));

// Every hosted photo, paired with the product it shows. One photo per WhatsApp message, so this
// is the only place that knows which upload belongs to which item.
let photoRecords = [];
try {
  const staticData = $getWorkflowStaticData('global');
  staticData.merchantPhotoRecords = staticData.merchantPhotoRecords || {};
  const known = Array.isArray(staticData.merchantPhotoRecords[archiveKey]) ? staticData.merchantPhotoRecords[archiveKey] : [];
  // A SCREENSHOT IS NEVER FILED AS A SHOP PICTURE.
  // It used to be recorded with whatever IMAGE_TYPE the vision step read, and a SCREENSHOT fell
  // through to role OTHER - which is exactly the role the page builder accepts as the shop's own
  // front page picture. That is how a capture of a Baserow table (rows 119/120, a column called
  // merchant_name) ended up as the banner of a pharmacy whose real building was never photographed.
  // A capture off a screen is filed as SCREENSHOT, which nothing may use as a shop picture.
  const freshRole = isDesignImage ? declaredType : (isScreenshot ? 'SCREENSHOT' : (isProductPhoto ? 'PRODUCT_PHOTO' : 'OTHER'));
  const fresh = { url: hostedUrl, product: productLabel, quality: photoQuality, role: freshRole, added: new Date().toISOString() };
  photoRecords = known.filter(r => r && r.url && r.url !== hostedUrl).concat(hostedUrl ? [fresh] : []);
  while (photoRecords.length > 12) photoRecords.shift();
  staticData.merchantPhotoRecords[archiveKey] = photoRecords;
} catch (e) {
  photoRecords = hostedUrl ? [{ url: hostedUrl, product: productLabel, quality: photoQuality, role: isProductPhoto ? 'PRODUCT_PHOTO' : 'OTHER' }] : [];
}

// The caption the merchant typed with the picture, and what the picture shows. The agent needs
// both: the photo supplies the item and its picture, the caption supplies what they want done.
const captionText = String(prev.imageCaption || '').trim();
const imageFact = 'A photo was sent with this message. It is a ' + (isDesignImage ? 'flyer/logo (a design reference - never a product photo)' : 'PRODUCT_PHOTO of ' + (productLabel || 'the item shown') + (photoQuality === 'POOR' ? ', and the photo is POOR QUALITY' : '')) + '. The photo was READ successfully - the merchant does NOT need to send it again.' + (hostedUrl ? ' Its hosted URL is ' + hostedUrl + '.' : ' It has no public link yet, so it cannot be printed directly.') + ' ' + (needsPhotoImprovement
  ? 'It is NOT printable as it is (' + improvementReason + '), so the card it names is given a clean, sharp picture of that same item instead, and this file is kept only as the reference.'
  : 'It belongs on that product card and must never be replaced by a searched or generated image.');
// ── WHICH SLOT DOES THIS PICTURE BELONG TO? ──────────────────────────────────
// The compiler reads photo roles from merchantPhotoRecords under the SHOP-SCOPED key it computes
// from the catalogue slug, not under the key written above (which cannot know the slug yet when
// the shop has no row). When the two keys differ the role was never seen, so every product photo
// fell through to the "their own shop picture" path and was printed at the top of the page -
// exactly the "I send a product picture and it lands on the homepage" complaint.
// The role is therefore written under BOTH keys, and under the plain number as well.
const productPhotoSlot = Boolean(isProductPhoto && hostedUrl && !isDesignImage);
try {
  const sdSlot = $getWorkflowStaticData('global');
  sdSlot.merchantPhotoRoles = sdSlot.merchantPhotoRoles || {};
  // The role recorded under every key. A screen capture is never OTHER either - OTHER is the role
  // the hero path trusts as "this is the shop itself", and a screenshot of a table is not a shop.
  const roleEntry = { url: hostedUrl, role: productPhotoSlot ? 'PRODUCT_PHOTO' : (isDesignImage ? 'OTHER' : (isScreenshot ? 'SCREENSHOT' : 'OTHER')), product: productLabel, added: new Date().toISOString() };
  const roleKeys = [archiveKey];
  if (hostedUrl) {
    Object.keys(sdSlot.merchantPhotoRecords || {}).forEach((k) => {
      const list = sdSlot.merchantPhotoRecords[k];
      if (Array.isArray(list) && list.some((r) => r && String(r.url || '') === hostedUrl)) roleKeys.push(k);
    });
  }
  roleKeys.forEach((k) => {
    const known = Array.isArray(sdSlot.merchantPhotoRoles[k]) ? sdSlot.merchantPhotoRoles[k] : [];
    const kept = known.filter((r) => r && r.url !== hostedUrl);
    kept.push(roleEntry);
    while (kept.length > 24) kept.shift();
    sdSlot.merchantPhotoRoles[k] = kept;
  });
} catch (e) {}

const combinedText = [
  captionText ? '[Customer Typed]: ' + captionText : '[Customer Typed]: (nothing - the photo alone is the message)',
  '[Image fact]: ' + imageFact,
  '[Image/OCR Detected Verification Context]: ' + aiAnalysis
].join(String.fromCharCode(10));

return [{ json: {
  ...prev,
  extractedMessage: combinedText,
  uploaded_image_url: hostedUrl,
  uploadedImageUrls: uploadedImages,
  // The photo itself, identified: which product it shows and whether it is usable as it stands.
  // A poor picture or a screenshot still says WHICH item it is, so the card it belongs to can be
  // given a clean generated picture of that item - it just never goes on the shop as it is.
  uploadedProductPhoto: ((isProductPhoto || isScreenshot) && hostedUrl) ? hostedUrl : '',
  uploadedProductName: productLabel,
  uploadedPhotoQuality: photoQuality,
  // Set when this picture must be redrawn before it reaches a card: a poor photo, or a capture
  // off a screen. The item name above is what the generator is asked to draw.
  uploadedPhotoNeedsImprovement: needsPhotoImprovement,
  uploadedPhotoImprovementReason: improvementReason,
  // Same rule as the photo record above: a screen capture is labelled SCREENSHOT, never OTHER, so
  // no later step can mistake it for the merchant's own shop photograph.
  imageRole: isDesignImage ? declaredType : (isScreenshot ? 'SCREENSHOT' : (isProductPhoto ? 'PRODUCT_PHOTO' : 'OTHER')),
  merchantPhotoRecords: photoRecords,
  image_summary: aiAnalysis.slice(0, 400)
} }];

const rawItems = $input.all();

// The merges keep the storefront build moving when one side is empty, but that means a product can
// arrive twice: once passed through untouched and once produced by the image branch. Collapse those
// to exactly one card per product, preferring the copy that actually carries a real image.
const usableScore = (j) => {
  const real = (u) => (typeof u === 'string' && u.trim() && !u.includes('placehold') ? 1 : 0);
  return real(j.finalImageUrl) * 2 + real(j.productImage) * 2 + real(j.data && Array.isArray(j.data) && j.data[0] && j.data[0].url ? j.data[0].url : '');
};
const byProduct = new Map();
const passthrough = [];
for (const item of rawItems) {
  const j = (item && item.json) || {};
  const idx = typeof j.productIndex === 'number' ? j.productIndex : null;
  // The shop's front page picture is not a product: it is never grouped, never collapsed into a
  // card, and never renamed. It goes straight through so the compiler can claim it as the hero
  // before any product card is drawn.
  if (j.isHomepage === true || j.isHomepageImage === true || idx === -1) {
    passthrough.push(item);
    continue;
  }
  if (idx === null) {
    passthrough.push(item);
    continue;
  }
  const existing = byProduct.get(idx);
  if (!existing || usableScore(j) >= usableScore(existing.json || {})) byProduct.set(idx, item);
}
const items = [...byProduct.values()].concat(passthrough);
const result = [];
const seenUrls = new Set();
for (const item of items) {
  const data = item.json;
  let resolvedUrl = '';

  if (data.data && Array.isArray(data.data) && data.data[0]?.url) {
    resolvedUrl = data.data[0].url;
  } else if (data.finalImageUrl) {
    resolvedUrl = data.finalImageUrl;
  } else if (typeof data.productImage === 'string' && data.productImage.trim()) {
    // A product passed straight through the merges keeps the image it already had (saved card or
    // merchant upload); only a genuinely image-less product falls through to a placeholder.
    resolvedUrl = data.productImage;
  } else if (data.output) {
    resolvedUrl = data.output;
  } else if (data.productImage) {
    resolvedUrl = data.productImage;
  }

  resolvedUrl = typeof resolvedUrl === 'string' ? resolvedUrl.trim() : '';

  // The front page picture is claimed FIRST, so no product card can ever take it for itself.
  // That single line is what keeps the homepage and the products from showing the same photo.
  const isHome = data.isHomepage === true || data.isHomepageImage === true || data.productIndex === -1;
  if (isHome) {
    const homeUrl = (typeof resolvedUrl === 'string' ? resolvedUrl.trim() : '');
    const homeOk = Boolean(homeUrl) && !homeUrl.includes('placehold') && !seenUrls.has(homeUrl);
    if (homeOk) seenUrls.add(homeUrl);
    result.push({
      json: {
        ...data,
        isHomepage: true,
        homepageImage: homeOk ? homeUrl : '',
        homepageImageUrl: homeOk ? homeUrl : '',
        productImage: homeOk ? homeUrl : '',
        hasImage: homeOk
      }
    });
    continue;
  }

  // Zero repetition, and no invented picture. A card never reuses a URL another card already
  // took, and a card with no real picture stays EMPTY - the compiler then draws its own branded
  // tile. This used to hand a grey placeholder URL to every image-less card, and that placeholder
  // is the "default picture" that showed up on every new shop and could never be removed.
  if (resolvedUrl.includes('placehold') || seenUrls.has(resolvedUrl)) {
    resolvedUrl = '';
  }
  if (resolvedUrl) seenUrls.add(resolvedUrl);

  result.push({
    json: {
      ...data,
      productImage: resolvedUrl,
      hasImage: Boolean(resolvedUrl)
    }
  });
}
return result;

// Where the shop actually is. Nothing here guesses a neighbourhood: a point is either the pin
// the merchant dropped, the point already saved for this shop, or a real map result for the
// place they named. If none of those is true the shop is held back and the merchant is asked.
const inputItems = $input.all();
if (!inputItems.length) return [];
const first = inputItems[0].json || {};
const safe = (fn, fallback) => { try { const v = fn(); return v === undefined ? fallback : v; } catch (e) { return fallback; } };

// The image pipeline can hand this node the shop's picture slot on its own - and that item has no
// parsedData on it. Read the shop from the routing node in that case, so the address the merchant
// actually typed is never lost and the shop is not held back for a place it was already given.
const parsedData = (first.parsedData && Object.keys(first.parsedData).length)
  ? first.parsedData
  : (safe(() => $('Validate & Route Intent').first().json.parsedData, {}) || {});

let phone = String(safe(() => $('Validate & Route Intent').first().json.senderPhone, '') || '').replace(/[^0-9]/g, '');
if (!phone) phone = String(first.senderPhone || '').replace(/[^0-9]/g, '');

const merchantName = String(parsedData.merchant_name || first.merchant_name || 'Merchant').trim();
const statedLocation = String(parsedData.location || first.location || first.shopPlace || '').trim();

// The pin the merchant physically dropped in this chat.
const pin = safe(() => $('Prepare Agent Input').first().json.customerLocationPin, null);

const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : null; };

let lat = null, lng = null;
let locationSource = 'NONE';
let locationLabel = statedLocation;
let accuracy = '';
let problem = '';

// ── 1. A real dropped pin wins outright. Nothing downstream moves it. ──
if (pin && num(pin.lat) !== null && num(pin.lng) !== null) {
  lat = num(pin.lat); lng = num(pin.lng);
  locationSource = 'PIN';
  accuracy = 'exact';
  if (pin.name) locationLabel = String(pin.name);
  else if (pin.address) locationLabel = String(pin.address);
  else if (!locationLabel) locationLabel = 'Shared location';
}

// ── 2. The point this shop already had, so editing a price never moves the shop. ──
if (lat === null) {
  const savedLat = num(parsedData.latitude);
  const savedLng = num(parsedData.longitude);
  if (savedLat !== null && savedLng !== null && savedLat !== 0 && savedLng !== 0) {
    lat = savedLat; lng = savedLng;
    locationSource = 'SAVED';
    accuracy = 'shop';
  }
}

// ── 3. The place the merchant named, verified on a real map. ──
const norm = (v) => String(v || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const STOP = ['the','and','near','opposite','behind','next','to','at','in','along','road','rd','street','st','avenue',
  'ave','close','lane','plaza','arcade','building','bldg','floor','shop','no','number','uganda','kampala','city','town',
  'centre','center','branch','main','old','new','off','on','of','for','my','our','we','here','there','this','that'];
const tokensOf = (v) => norm(v).split(' ').filter(w => w.length > 2 && STOP.indexOf(w) < 0);

const queries = [];
const seenQueries = {};
const addQuery = (q) => { const k = norm(q); if (k && !seenQueries[k]) { seenQueries[k] = true; queries.push(q); } };
if (statedLocation) {
  addQuery(statedLocation + ', Kampala, Uganda');
  addQuery(statedLocation);
  statedLocation.split(',').map(p => p.trim()).filter(Boolean).forEach(part => addQuery(part + ', Kampala, Uganda'));
}

// A shop that names another town must not be pulled back to Kampala.
const saysKampala = /kampala/i.test(statedLocation + ' ' + merchantName);
const region = saysKampala ? 'kampala' : '';
const wanted = tokensOf(statedLocation).filter(w => norm(merchantName).indexOf(w) < 0);

let best = null;
const consider = (cLat, cLng, cName, cAddress) => {
  const n = num(cLat), g = num(cLng);
  if (n === null || g === null || n === 0 || g === 0) return;
  const hay = norm(String(cName || '') + ' ' + String(cAddress || ''));
  if (region && hay.indexOf(region) < 0) return;
  // A candidate that does not contain the area the merchant named is a different place.
  const hitTokens = wanted.filter(w => hay.indexOf(w) >= 0);
  if (wanted.length > 0 && hitTokens.length === 0) return;
  const nameHits = tokensOf(merchantName).filter(w => hay.indexOf(w) >= 0).length;
  const score = hitTokens.length * 2 + nameHits;
  if (!best || score > best.score) best = { lat: n, lng: g, name: cName, score, exactArea: hitTokens.length > 0 };
};

// A failed call and an empty answer are different things: an unreachable map service must never
// stop a merchant's shop, while a place the map genuinely cannot find has to be asked for.
let lookupReachable = false;
const request = async (options) => {
  try {
    const res = await this.helpers.httpRequest(options);
    lookupReachable = true;
    return res;
  } catch (e) { return null; }
};

if (lat === null && queries.length > 0) {
  for (const q of queries) {
    if (best) break;

    // OpenStreetMap Nominatim: full addresses, country restricted to Uganda.
    const nomi = await request({
      url: 'https://nominatim.openstreetmap.org/search',
      qs: { q: q, format: 'jsonv2', addressdetails: 1, limit: 5, countrycodes: 'ug', 'accept-language': 'en' },
      headers: { 'User-Agent': 'X-Link-Storefront-Builder/1.0 (https://xlinkug.com)' },
      timeout: 2500,
      json: true
    });
    if (Array.isArray(nomi)) nomi.forEach(r => consider(r.lat, r.lon, r.name || '', r.display_name || ''));

    if (best) break;

    // Photon: a free second opinion on the same map data when Nominatim has nothing.
    const photon = await request({
      url: 'https://photon.komoot.io/api/',
      qs: { q: q, limit: 5, lang: 'en' },
      timeout: 2500,
      json: true
    });
    const features = (photon && Array.isArray(photon.features)) ? photon.features : [];
    features.forEach(f => {
      const pr = f.properties || {};
      const cc = String(pr.countrycode || '').toUpperCase();
      if (cc && cc !== 'UG') return;
      const co = (f.geometry && Array.isArray(f.geometry.coordinates)) ? f.geometry.coordinates : [];
      const addr = [pr.name, pr.street, pr.locality, pr.district, pr.city, pr.state, pr.country].filter(Boolean).join(', ');
      consider(co[1], co[0], pr.name || '', addr);
    });
  }

  if (best) {
    lat = best.lat; lng = best.lng;
    locationSource = 'MAP';
    accuracy = 'area';
  }
}

// A point outside Uganda is refused rather than published on the wrong continent.
if (lat !== null && (lat < -1.6 || lat > 4.4 || lng < 29.4 || lng > 35.2)) {
  problem = 'point_outside_uganda';
  lat = null; lng = null;
  locationSource = 'NONE';
  accuracy = '';
}

const hasPoint = lat !== null && lng !== null;
const finalLat = hasPoint ? Number(lat.toFixed(6)) : null;
const finalLng = hasPoint ? Number(lng.toFixed(6)) : null;
const mapsUrl = hasPoint ? ('https://www.google.com/maps/search/?api=1&query=' + finalLat + ',' + finalLng) : '';

// What still has to be asked. The registration check reads this, and it is never a silent guess.
//   location_required      - no usable place at all, so ask the merchant for it
//   confirm_exact_point    - the area is known but not the building, so offer to refine it
let locationAsk = '';
if (!hasPoint) {
  // The map could not be reached at all. The shop is still built and shows the merchant's own
  // words, with no pin, rather than being held up by a third-party outage.
  if (statedLocation && !lookupReachable) locationAsk = 'pin_pending';
  else locationAsk = 'location_required';
} else if (accuracy === 'area') locationAsk = 'confirm_exact_point';

const displayLocation = statedLocation || locationLabel || '';

return inputItems.map((item, index) => {
  const j = item.json || {};
  const itemParsed = j.parsedData || parsedData;
  return {
    json: {
      ...j,
      // THE FRONT PAGE PICTURE IS READ FROM THE PICTURE'S OWN SLOT, NEVER FROM A PRODUCT ITEM.
      // This used to be filled from whichever item happened to sit at index 0 - normally the first
      // PRODUCT of the shop. Two things followed from that, and both are visible on a real shop:
      //   1. the page builder treats a picture arriving in the front-page slot as the banner, so
      //      product #1's shopping photo was printed across the top of the whole shop; and
      //   2. that picture was then claimed by the banner before the cards were drawn, so product #1
      //      was left with no picture of its own and drew an empty frame while the other cards were
      //      fine. A merchant reads that as "the images are not being applied properly".
      // A front page picture is only ever the shop's own chosen/generated premises shot, carried by
      // the dedicated slot (productIndex -1). A product card's picture stays on that card.
      // THE LOCATION FIELDS ARE THE SHOP'S, SO EVERY ITEM CARRIES THEM.
      // These used to be set on item 1 only. The location check downstream is an IF on
      // "location_ask", so item 1 matched on its own and was pulled down the "ask for the pin"
      // branch while every other item built the page - and item 1 is the FIRST PRODUCT, not the
      // front page slot. The shop was therefore built without that product: its card printed an
      // empty frame while the cards around it kept their pictures. A merchant sees their first
      // item's image disappear and reports "the images are not being applied properly".
      // Every item now holds the same answer, so the whole run takes ONE branch together.
      // The fields below are plain members of the item json. They used to sit inside a bare
      // block ('{ ... }') with no key, which is not valid JavaScript: the node threw
      // "Unexpected token '{'" and every shop build died here.
        // The phone number and the front page picture belong to the run, not to a product card, so
        // they are restored here as well: when the shop has no priced items the only item that
        // reaches this node is the picture slot, and a missing number means the merchant is never
        // replied to at all.
        senderPhone: String(first.senderPhone || safe(() => $('Validate & Route Intent').first().json.senderPhone, '') || ''),
        businessPhone: String(first.businessPhone || safe(() => $('Validate & Route Intent').first().json.businessPhone, '') || ''),
        ...(() => {
          // Only the run's own front-page slot may fill this. It is the item marked isHomepage /
          // productIndex -1, and its picture can never be one that already belongs to a card.
          const frontSlot = (() => {
            try {
              const found = inputItems.find((it) => {
                const j = (it && it.json) || {};
                return j.isHomepage === true || j.isHomepageImage === true || j.productIndex === -1;
              });
              return (found && found.json) || {};
            } catch (e) { return {}; }
          })();
          const slotUrl = String(
            frontSlot.homepageImageUrl || frontSlot.homepageImage ||
            frontSlot.finalImageUrl || frontSlot.productImage || ''
          ).trim();
          return { homepageImage: slotUrl, homepageImageUrl: slotUrl };
        })(),
        latitude: finalLat,
        longitude: finalLng,
        has_location_pin: hasPoint,
        location_source: locationSource,
        location_accuracy: accuracy,
        location_ask: locationAsk,
        location_problem: problem,
        location_lookup_reachable: lookupReachable,
        google_maps_url: mapsUrl,
        location: displayLocation,
      parsedData: {
        ...itemParsed,
        latitude: finalLat,
        longitude: finalLng,
        location: displayLocation,
        location_source: locationSource
      }
    }
  };
});

const first = $('Resolve Shop Location1').first().json || {};
const parsed = first.parsedData || {};
const name = String(parsed.merchant_name || first.merchant_name || 'your shop').trim();
const stated = String(first.location || parsed.location || '').trim();
const reason = String(first.location_problem || '');

// Ask for the real point, and say plainly why it is needed. The button that comes with this
// message opens WhatsApp's own location sender, so the merchant never has to type coordinates.
let body;
if (reason === 'point_outside_uganda') {
  body = 'That pin is outside Uganda, so I have not put it on ' + name + '.' + String.fromCharCode(10) + String.fromCharCode(10) +
    'Tap the button below and share the real location of ' + name + ' - the location button sends the exact spot, so nothing has to be typed.';
} else if (stated) {
  body = 'I could not find "' + stated + '" on the map, so I will not guess where ' + name + ' is.' + String.fromCharCode(10) + String.fromCharCode(10) +
    'Tap the button below and share the exact location, or reply with the area and a landmark near you - for example "Banda, next to the mosque".';
} else {
  body = 'Before I put ' + name + ' on the map, I need your exact location.' + String.fromCharCode(10) + String.fromCharCode(10) +
    'Tap the button below and share the exact location - it is one tap and no typing - or reply with the area and a landmark near you.';
}

return [{
  json: {
    ...first,
    senderPhone: first.senderPhone || '',
    locationAskText: body,
    whatsapp_reply: body
  }
}];

