function escapeHtml(str) { 
  if (!str) return ''; 
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#039;'); 
}

const inputItems = $input.all();
const parsedData = inputItems[0].json.parsedData || {};
let phone = String(inputItems[0].json.senderPhone || '').replace(/[^0-9]/g, '');
// The OWNER's own number. It is the number this site belongs to, and it is the one every chat
// button on the page opens. Read from the routing node if this item lost it, so the shop is
// never published without a way for a buyer to reach its owner.
if (!phone) { try { phone = String($('Validate & Route Intent').first().json.senderPhone || '').replace(/[^0-9]/g, ''); } catch (e) {} }
let intent = inputItems[0].json.intent || 'BUILD_STORE';
// THE MERCHANT'S OWN WORDS HAVE TO REACH THIS NODE.
// The image pipeline items carry the shop's parsed data but not always the typed message, so
// reading it from the first item alone can produce an empty string and every "use this as my
// homepage picture" is then silently ignored at the last gate. It is read from the nodes that hold
// it by name, and the item is only the last resort.
const userMessage = String((() => {
  const tryNode = (name) => { try { return String($(name).first().json.extractedMessage || ''); } catch (e) { return ''; } };
  return String(inputItems[0].json.extractedMessage || '')
    || tryNode('Extract Vision Text1')
    || tryNode('Parse WhatsApp Message')
    || '';
})()).toLowerCase();

const rawName = String(parsedData.merchant_name || 'Official Storefront').trim();
const isEnterprise = parsedData.site_tier === 'ENTERPRISE';
// THE PLACE NAME ON THE PAGE HAS TO BE A PLACE, NOT A COORDINATE.
// A pin handed to the agent as "lat,lng" was sometimes repeated back as the shop's location, and
// the badge then read "Live on X-Link Map (0.3447626)". Anything that is only digits, signs and
// dots is a coordinate, not an area, so it is dropped here rather than printed to buyers.
const looksLikeCoords = (v) => {
  const s = String(v || '').trim();
  if (!s) return false;
  if (/[a-zA-Z]/.test(s)) return false;
  const parts = s.split(/[,|;]+/).map(p => p.trim()).filter(Boolean);
  if (!parts.length) return false;
  for (const p of parts) {
    let ok = p.length > 0;
    for (let i = 0; i < p.length; i++) {
      const c = p.charCodeAt(i);
      const allowed = (c >= 48 && c <= 57) || c === 45 || c === 43 || c === 46 || c === 176 || c === 32 || c === 44;
      if (!allowed) { ok = false; break; }
    }
    if (!ok) return false;
  }
  return true;
};
const rawLocationText = String(parsedData.location || '').trim();
const locationInfo = escapeHtml(looksLikeCoords(rawLocationText) ? 'Kampala, Uganda' : (rawLocationText || 'Kampala, Uganda'));
const locationShort = locationInfo.split(',')[0].trim();
const defaultCategory = String(parsedData.business_category || 'Commercial Trade').replace(/&amp;/g, '&').replace(/&/g, '&');
const flyerHeadline = escapeHtml(parsedData.hero_headline || rawName);
const rawProducts = Array.isArray(parsedData.products_and_services) ? parsedData.products_and_services : [];
// ── THIS SHOP'S OWN PHOTO ARCHIVE ────────────────────────────────────────────
// A Code node cannot see another Code node's variables. This used to read ownArchivedPhotos /
// ownArchivedRecords, which are declared in Prepare Product Search Queries - so every read threw
// a ReferenceError inside a try/catch and returned nothing. The compiler therefore never saw which
// archived photo was a product shot, and treated them all as shop pictures: that is why a product
// photo kept being promoted to the front page. The archive is now built here, per SHOP.
// NOTE: the run's own slug variable is declared further down, so it is not read here - reading it
// before its declaration would throw. The catalogue's own slug is the same value by this point.
// THIS SHOP'S OWN ADDRESS. previous_slug is the address a shop REPLACED, so it belongs to a
// different shop's archive - reading it first is how one shop's photos reached another.
const photoScopeSlug = String(
  (parsedData && (parsedData.slug || parsedData.previous_slug)) ||
  (inputItems[0].json && (inputItems[0].json.slug || inputItems[0].json.previous_slug)) || ''
).trim();
// Both keys are read for CARD pictures: a photo is filed under the bare number while the shop has no
