  const n = pName.toLowerCase();
  if (/earbud|headset|airpod|audio|speaker|sound|headphone/i.test(n)) return 'Audio & Sound';
  if (/charger|power bank|adapter|cable|battery/i.test(n)) return 'Chargers & Power';
  if (/glass|protector|film/i.test(n)) return 'Screen Protectors';
  if (/case|cover|housing|pouch/i.test(n)) return 'Phone Protection';
  if (/iphone|samsung|galaxy|tecno|infinix|oppo|phone|smartphone|series/i.test(n)) return 'Smartphones & Mobile';
