  // roles were recorded fits through that gap, so the same archived product photo came back as the
  // banner on every rebuild and the merchant could not get rid of it. A stored picture now has to
  // be one the record calls the shop itself, or the shop's own generated premises shot (which
  // arrives in the front-page slot above) - a product photo, or anything of unknown role, is not
  // a banner.
  const shopOnly = (u) => {
    const url = isUsableImage(u) ? String(u).trim() : '';
