const products = rawProducts.map((p, index) => {
  // A missing price stays missing. Substituting a default is what produced three
  // identical fake prices on a real storefront.
  // Prices arrive as numbers most of the time, but "5k" or "25,000" can reach this line as text,
  // and Number("5k") is NaN - which printed "USh 0" and "Ask the merchant for the price" on a shop
  // whose prices were perfectly clear.
  // ONE PRICE READER, THE SAME ONE THE ROUTER USES.
  // This reader used to keep a trailing k or m and nothing else, so "50 thousand" - a perfectly
  // ordinary way to price something - came out as 50 and the card advertised USh 50 for a product
  // the merchant had priced at fifty thousand. It now understands the figure, a multiplier word
  // (k / thousand / m / million), a dot used as a thousands separator (50.000 and 85.000), a
  // grouping space (1 500 000), a range (50-60k reads as its lower end) and a price spelled out in
  // words ("fifty thousand"). Both halves of the workflow now agree on what a price is.
  const parsePrice = (v) => {
    if (typeof v === 'number') return isFinite(v) ? v : 0;
    let s = String(v == null ? '' : v).toLowerCase().replace(/\u00a0/g, ' ').replace(/,/g, '');
    if (!s.trim()) return 0;
