    .concat(Array.isArray(p.images) ? p.images : [], p.img, p.image)
    .concat([freshPhotoUrl])
    .concat([imageByProductIndex[index]])
    .concat([existingProductsMap[pNameLower]]);
  // A picture sent with this message is placed only on the card the vision step matched it to.
  // Every other card sees nothing, so one photo can never fan out across the catalogue.
  // THIS CARD'S OWN LISTED PICTURES ARE ITS OWN, when the merchant is changing THIS card.
  // The merchant's newly sent photo only reaches here inside the card's own image list - the
