    .map(u => (isUsableImage(u) ? String(u).trim() : ''))
    .filter(u => trustedCardImage(u) || ownListedImage(u))
    .filter(u => !(freshPhotoCandidate && u === freshPhotoCandidate && !cardOwnsFreshPhoto))
    .find(u => u && !usedImageUrls.has(u));
