    .find(u => u && !usedImageUrls.has(u)) || '';
  const keepSavedPicture = !cardInPhotoScope(p.name) && Boolean(savedCardPicture);

  // Which picture belongs to WHICH item is now the whole rule. A saved card picture, a searched
  // image the router produced for this card, or this item's own photo goes on it. A picture that
  // is known to belong to a DIFFERENT product is never printed here, however empty this card is -
  // that shared pool is what put the same photo on card after card, and the same photo on two
  // different shops. A card with nothing of its own draws the shop's own branded tile instead.
  const knownOtherImage = (u) => {
    if (!u) return false;
    // A picture sent with this message is somebody else's only when this card does not own it.
