  // photograph. hasImage=false is what tells the renderer to do that, so no placeholder URL -
  // and therefore no repeated picture - exists anywhere in the page.
  const hasImage = Boolean(finalImg && (finalImg.startsWith('http') || finalImg.startsWith('data:')));
  if (!hasImage) finalImg = '';
  if (hasImage) usedImageUrls.add(finalImg);

  // A merchant may send several photos for one item. Keep every usable one, main picture first,
  // so the shop can show them all instead of throwing the extras away. The same provenance rule
  // applies: a URL nobody can vouch for never reaches the gallery either.
  const extraImages = [];
  const addExtra = (u) => {
    const url = isUsableImage(u) ? String(u).trim() : '';
    if (!url || url === finalImg || extraImages.indexOf(url) >= 0) return;
    if (!trustedCardImage(url)) return;
