  var PAYPAL_CURRENCIES = { USD: 1, EUR: 1, GBP: 1, AUD: 1, CAD: 1, CHF: 1, HKD: 1, JPY: 1, MXN: 1, NZD: 1, NOK: 1, PHP: 1, PLN: 1, RUB: 1, SEK: 1, SGD: 1, THB: 1, TWD: 1, CZK: 1, DKK: 1, HUF: 1, ILS: 1, MYR: 1, BRL: 1 };
  function currencySymbol(code) {
    return CURRENCY_SYMBOLS[code] || (code + ' ');
  }
  // The same for a named currency, so the shop's own money can be written without changing what
  // the visitor's currency currently is.
  function symbolFor(code) {
    var sym = currencySymbol(String(code || 'UGX').toUpperCase());
    return (sym.charAt(sym.length - 1) === ' ' ? sym : sym + ' ');
  }
  // One space between the symbol and the figure, whether or not the symbol already ends in one
  // ("USh " + "5,000" must not become "USh  5,000").
  function withSymbol(amountText) {
    var sym = currencySymbol(userCurrency);
    return (sym.charAt(sym.length - 1) === ' ' ? sym : sym + ' ') + amountText;
  }
  // A price is never rounded away. Rounding every figure to whole units turned a 2,000 shilling
  // chapati roll into "$ 0" for a visitor whose money is worth more per unit - the buyer read the
  // item as free. Small amounts keep their cents; large ones stay whole.
  function fmtAmount(v) {
    var n = Number(v) || 0;
    if (n > 0 && n < 10) return n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    return Math.round(n).toLocaleString('en-US', { maximumFractionDigits: 0 });
  }
  // An amount held in USD, written in the visitor's own money. Before the rates load - or when
  // there is no network - it is written in the shop's own shillings, never in a bare dollar figure
  // the buyer cannot place.
  function showMoney(amountUsd) {
    var usd = Number(amountUsd) || 0;
    // With no rate yet the shop's own shilling figure is used, but never with the visitor's symbol
    // in front of it: a visitor in Europe was shown "€ 3,700" for a 5,000 shilling item when a
    // slow network left the rates unloaded. The code that matches the figure is used instead.
    if (!(userRate > 0)) return symbolFor(DEFAULT_MONEY) + fmtAmount(usd * ugxPerUsd);
    return withSymbol(fmtAmount(usd * userRate));
  }
  // The money the buyer reads on the page, in the money the CARD is charged in. PayPal settles
  // only in the currencies on its list, so a visitor in Uganda sees the exact USD figure their
  // card will be charged beside their own shillings - the conversion is stated, never hidden.
  function chargeMoneyText(amountUsd) {
    var f = paypalFigure(amountUsd);
    return symbolFor(f.code) + f.value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  // What PayPal is actually told to charge: the visitor's currency when PayPal accepts it,
  // otherwise the USD equivalent, flagged so the page can say so plainly before the buyer pays.
  function paypalFigure(amountUsd) {
    var local = String(userCurrency || 'USD').toUpperCase();
    var code = PAYPAL_CURRENCIES[local] ? local : 'USD';
    var rate = (userRate > 0) ? userRate : 0;
    var value = (code === local && rate > 0) ? (Number(amountUsd) * rate) : Number(amountUsd);
    // The merchant's margin, when they set one: applied to the figure the card is charged and
    // disclosed on the page, because a processor's spread is what it covers. At 0 this is a no-op.
    if (value > 0 && FX_MARGIN_PERCENT > 0) value = value * (1 + (FX_MARGIN_PERCENT / 100));
    if (!(value > 0)) value = 0;
    return { code: code, value: Math.round(value * 100) / 100, converted: code !== local, margin: FX_MARGIN_PERCENT };
  }
  async function localizeCurrency() {
    try {
      var geoData = {};
      try {
        geoData = await xlinkGeo() || {};
      } catch (e) { geoData = {}; }
      var detected = String(geoData.currency || '').toUpperCase();

      let rates = {};
      try {
        const rateRes = await fetch('https://open.er-api.com/v6/latest/USD');
        const rateData = await rateRes.json();
        rates = (rateData && rateData.rates) ? rateData.rates : {};
      } catch (e) { rates = {}; }
      // The page's own lookup failed (offline buyer, blocked request). Fall back to the published
      // figures this build already had - never to a number this file made up.
      for (const c in SEEDED_RATES) { if (!(rates[c] > 0) && SEEDED_RATES[c] > 0) rates[c] = SEEDED_RATES[c]; }
      // The live shilling rate is used for the conversion too, so the USD figure behind a card and
      // the USD figure charged by PayPal are the same one.
      // A live figure always wins over the seeded one, but the seeded figure is a REAL published
      // rate rather than a number typed into the code.
      if (rates.UGX > 0) ugxPerUsd = rates.UGX;
      // The visitor's OWN currency, only when its rate is actually known. This used to fall back to
      // the dollar, which is what printed US$ prices on a shop that never quoted dollars: a visitor
      // whose currency could not be detected (or has no published rate) is shown the merchant's own
      // money instead, and the checkout still states the exact dollar figure the card is charged.
      if (detected && rates[detected] > 0) {
        userCurrency = detected;
        userRate = rates[detected];
      } else if (detected === 'USD' && rates.USD > 0) {
        userCurrency = 'USD';
        userRate = 1;
      } else {
        userCurrency = DEFAULT_MONEY;
        userRate = 0;
      }

      // WHAT ONE SHILLING BUYS IN THE VISITOR'S MONEY - AND IT IS 1 WHEN THEY ARE SHOPPING AT HOME.
      // This line used to divide by the dollar rate and multiply by the visitor rate. A visitor whose
      // currency could not be detected keeps the merchant's own money and a rate of 0, so the
      // multiplier collapsed to 1 / 4092 and every card was divided by the dollar rate: a 100,000
      // shilling kitenji dress printed "USh 24" straight over the price the merchant typed. That
      // is a number nobody charged and no merchant set. The shillings rate cancels itself out
      // when the visitor is spending the shop's own money, so the figure is shown untouched.
      // A genuine foreign visitor gets a real conversion, and only once their rate is known - an
      // unknown rate now leaves the built price alone instead of shrinking it to a fraction.
      const isOwnMoney = (String(userCurrency || '').toUpperCase() === String(DEFAULT_MONEY || '').toUpperCase());
      const ugxToUserRate = isOwnMoney ? 1 : ((userRate > 0 && ugxPerUsd > 0) ? (userRate / ugxPerUsd) : 0);
      document.querySelectorAll('.product-price').forEach(el => {
        // A card may hold a local price or a foreign-currency price. Both are converted into the
        // visitor's own money; a card with no price at all keeps saying "ask the merchant".
        const baseUgx = parseFloat(el.getAttribute('data-base-ugx')) || 0;
        const baseUsd = parseFloat(el.getAttribute('data-base-usd')) || 0;
        let converted = 0;
        if (baseUgx > 0) {
          // A rate of 0 means the conversion is not known, so the price the build printed stays.
          converted = ugxToUserRate > 0 ? (baseUgx * ugxToUserRate) : baseUgx;
        } else if (baseUsd > 0) {
          // A dollar-priced card: the visitor's rate, or the shop's own shillings when unknown.
          converted = baseUsd * (userRate > 0 ? userRate : ugxPerUsd);
        } else {
          return;
        }
        // Never print an unreadable figure: a price only changes when there is a real one.
        if (!(converted > 0)) return;
        el.innerText = withSymbol(fmtAmount(converted));
      });
    } catch(e) {
      console.log("Currency localization fallback active.");
    }
    renderOrderTotal();
  }
  // The cart total in the order form, in the same money as the cards, plus what the card payment
  // will be settled in so the buyer is never surprised on the PayPal page.
  function renderOrderTotal() {
    var valueEl = document.getElementById('orderTotalValue');
    var noteEl = document.getElementById('orderTotalNote');
    if (!valueEl) return;
    var totalLocal = cart.reduce(function (sum, i) { return sum + (Number(i.priceLocal) || 0) * i.qty; }, 0);
    var totalUsdFallback = cart.reduce(function (sum, i) { return sum + (Number(i.priceUsd) || 0) * i.qty; }, 0);
    var totalUsd = totalLocal > 0 ? (totalLocal / ugxPerUsd) : totalUsdFallback;
    if (!(totalUsd > 0)) {
      valueEl.innerText = t('askPrice') || 'Ask the merchant for the price';
      if (noteEl) noteEl.innerText = '';
      return;
    }
    valueEl.innerText = showMoney(totalUsd);
    if (noteEl) {
      // Always stated, whether or not a conversion happens: the buyer must know the exact figure
      // their card is charged before they pay, and it must be the same figure that is sent.
      var f = paypalFigure(totalUsd);
      var shown = showMoney(totalUsd);
      noteEl.innerText = f.converted
        ? ('Card / PayPal charges ' + chargeMoneyText(totalUsd) + ' - the exact amount of ' + shown + ' at the live rate' + (FX_MARGIN_PERCENT > 0 ? ' plus the ' + FX_MARGIN_PERCENT + '% exchange margin this shop set' : '') + '. Cash and Mobile Money stay in ' + shown + '.')
        : ('Card / PayPal and cash are both ' + shown + (FX_MARGIN_PERCENT > 0 ? ' (card adds the ' + FX_MARGIN_PERCENT + '% exchange margin this shop set)' : '') + '.');
    }
  }
  // NOTHING ON FIRST PAINT WAITS FOR A NETWORK CALL.
  // This used to fire three separate lookups on load: a geo lookup for the language, then a
  // SECOND geo lookup plus an exchange-rate download for the currency. Each one is a separate
  // third-party host (ipapi.co, open.er-api.com) and the page sat on "Loading" while they
  // answered - which is why a shop got slower to open the more was added to it. Now the English
  // page and the prices it was built with paint first, and the two lookups run afterwards, idle,
  // sharing ONE geo response between the language and the currency.
  var XLINK_GEO = null;
  var xlinkGeoOnce = null;
  function xlinkGeo() {
    if (XLINK_GEO) return Promise.resolve(XLINK_GEO);
    if (!xlinkGeoOnce) {
      xlinkGeoOnce = fetch('https://ipapi.co/json/', { cache: 'force-cache' })
        .then(function (r) { return r.json(); })
        .then(function (g) { XLINK_GEO = g || {}; return XLINK_GEO; })
        .catch(function () { XLINK_GEO = {}; return XLINK_GEO; });
    }
    return xlinkGeoOnce;
  }
  function xlinkAfterPaint(fn) {
    try {
      if (window.requestIdleCallback) { window.requestIdleCallback(fn, { timeout: 1500 }); return; }
    } catch (e) {}
    setTimeout(fn, 60);
  }
  window.addEventListener('DOMContentLoaded', function () {
    // The parts that need no network happen at once, so the page is usable and switchable now.
    captureEnglish();
    try { autoLanguage(); } catch (e) {}
    xlinkAfterPaint(function () {
      try {
        var p = localizeCurrency();
        // A failed lookup must never leave the price lines unreadable.
        if (p && p.catch) p.catch(function () {});
      } catch (e) {}
    });
  });

  // sendLocalOrder (the cash / Mobile Money recorder) is deleted: the order form only takes
  // card/PayPal now, and placeCashOrder is gone with the cash card, so nothing could ever call it.


  // Every buyer facing chat link is built here, from THIS shop's line. A shop whose line is not
  // known gets no link at all rather than a link to somebody else's business.
  function businessLinkFor(text) {
    var target = Business_WHATSAPP || '';
    if (!target) { return ''; }
    return 'https://wa.me/' + target + (text ? ('?text=' + encodeURIComponent(text)) : '');
  }

  // The order is already recorded. This card hands the buyer straight into the business WhatsApp
  // thread with the order id in the message, so the conversation is traceable and no private
  // number is ever handed out.
  function showOrderConfirm(orderId, payNote) {
    var id = String(orderId || '');
    var text = 'Order Confirmed - ID: ' + id;
    var chat = '${businessChatLink}' + '?text=' + encodeURIComponent(text);
    var el = document.getElementById('orderConfirmModal');
    if (!el) { return; }
    var idEl = document.getElementById('confirmOrderId');
    if (idEl) { idEl.innerText = id; }
    var payEl = document.getElementById('confirmPayNote');
    if (payEl) { payEl.innerText = String(payNote || ''); }
    var numEl = document.getElementById('confirmNumberText');
    if (numEl) { numEl.innerText = BUSINESS_NUMBER || '-'; }
    var chatEl = document.getElementById('confirmWaLink');
    if (chatEl) { chatEl.setAttribute('href', chat); }
    // The number itself is the link too: tapping it opens this shop's own WhatsApp thread.
    var linkEl = document.getElementById('confirmNumberLink');
    if (linkEl) { linkEl.setAttribute('href', chat); }
    var callEl = document.getElementById('confirmCallLink');
    // Call dials the shop's own number directly, and the chat button opens that same shop thread.
    if (callEl) { callEl.setAttribute('href', 'tel:+' + String(BUSINESS_NUMBER || '').replace(/[^0-9]/g, '')); }
    var videoEl = document.getElementById('confirmVideoLink');
    if (videoEl) {
      videoEl.setAttribute('href', 'https://wa.me/' + (CALLABLE_NUMBER || BUSINESS_NUMBER || '').replace(/[^0-9]/g, ''));
    }
    el.style.display = 'flex';
  }
  function closeOrderConfirm() {
    var el = document.getElementById('orderConfirmModal');
    if (el) { el.style.display = 'none'; }
    window.location.href = '#offerings';
  }

  // THE RECEIPT IS THE BUYER'S PROOF THAT THE ORDER EXISTS, AND THE MERCHANT'S PROOF OF WHAT TO BRING.
  // Every line shown here is the cart that was just written to the order table, priced with the
  // same figures the page showed a moment earlier. Nothing on it is invented.
  function showReceipt(orderId, lines, totalLocal, sentTo) {
    var el = document.getElementById('receiptModal');
    if (!el) return;
    var shopEl = document.getElementById('rcptShop');
    if (shopEl) shopEl.textContent = '${rawName}';
    var sentEl = document.getElementById('rcptSent');
    if (sentEl) sentEl.textContent = sentTo ? (fmt('receiptSent', {}) || 'Sent to the merchant on WhatsApp') : '';
    var box = document.getElementById('rcptLines');
    if (box) {
      // Built with DOM nodes rather than HTML, so an item name can never inject markup.
      box.textContent = '';
      (lines || []).forEach(function (l) {
        var row = document.createElement('div');
        row.className = 'receipt-line';
        var nm = document.createElement('span');
        nm.textContent = l.name + ' x' + l.qty;
        var am = document.createElement('span');
        am.textContent = l.amount;
        row.appendChild(nm);
        row.appendChild(am);
        box.appendChild(row);
      });
    }
    var totalEl = document.getElementById('rcptTotal');
    if (totalEl) totalEl.textContent = 'USh ' + money(totalLocal);
    var refEl = document.getElementById('rcptRef');
    if (refEl) refEl.textContent = String(orderId || '-');
    var noteEl = document.getElementById('rcptNote');
    if (noteEl) noteEl.textContent = fmt('receiptBody', {}) || 'This is your receipt. The merchant has been told to bring the goods and collect the cash, and will mark it paid once they receive it.';
    el.style.display = 'flex';
  }
  function closeReceipt() {
    var el = document.getElementById('receiptModal');
    if (el) { el.style.display = 'none'; }
    window.location.href = '#offerings';
  }

  // CASH ON DELIVERY IS A WHOLE ORDER, NOT A SLOWER PAYMENT STEP.
  // The cart is written through the payment workflow, which is what messages the merchant
  // ("this buyer is paying cash - bring the goods and collect on arrival") and returns the order
  // id. The buyer gets the receipt, the cart is cleared, and the order waits as AWAITING_PAYMENT
  // until the merchant taps the confirm link to mark it paid.
  async function submitCashOrder() {
    if (!cart || cart.length === 0) {
      alert(fmt('emptyCart', {}) || 'Your cart is empty! Add items from the catalogue.');
      return;
    }
    var NL = String.fromCharCode(10);
    // The receipt is drawn from this snapshot, so clearing the cart below cannot empty it.
    var snapshot = cart.map(function (i) { return { name: i.name, qty: i.qty, priceLocal: Number(i.priceLocal) || 0 }; });
    var totalLocal = snapshot.reduce(function (sum, i) { return sum + (i.priceLocal * i.qty); }, 0);
    var lines = snapshot.map(function (i) {
      return { name: i.name, qty: i.qty, amount: (i.priceLocal > 0 ? ('USh ' + money(i.priceLocal * i.qty)) : (t('askPrice') || 'price on request')) };
    });
    var plainLines = snapshot.map(function (i) {
      return '- ' + i.name + ' x' + i.qty + ' = ' + (i.priceLocal > 0 ? ('USh ' + money(i.priceLocal * i.qty)) : (t('askPrice') || 'price on request'));
    });
    var notesEl = document.getElementById('cNotes');
    var notes = notesEl && notesEl.value ? String(notesEl.value).trim() : '';
    var summary = plainLines.join(' | ') + (totalLocal > 0 ? (' | Total: USh ' + money(totalLocal)) : '') + (notes ? (' | Notes: ' + notes) : '');
    var btn = document.getElementById('actionSubmitBtn');
    if (btn) { btn.disabled = true; btn.innerText = fmt('openingCheckout', {}) || 'Opening secure checkout...'; }
    var placed = {};
    try {
      var res = await fetch('${localOrderWebhookUrl}', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          slug: '${slug}',
          merchant_name: '${rawName}',
          // The order goes to the SHOP's own line - the same number every other button uses.
          merchant_phone: '${businessWaNumber}',
          buyer_name: 'Customer',
          buyer_phone: '',
          amount_local: totalLocal,
          amount_usd: (ugxPerUsd > 0 ? Number((totalLocal / ugxPerUsd).toFixed(2)) : 0),
          currency: '${String(pricingCurrency || "UGX").toUpperCase()}',
          display_currency: userCurrency,
          payment_method: 'CASH_ON_DELIVERY',
          items_summary: summary
        })
      });
      placed = await res.json();
    } catch (err) {
      console.log('Cash order could not be recorded:', err);
    }
    if (btn) { btn.disabled = false; }
    choosePayTile('cod');
    if (placed && placed.order_id) {
      cart = [];
      updateCartUI();
      var notesBox = document.getElementById('cNotes');
      if (notesBox) notesBox.value = '';
      showReceipt(placed.order_id, lines, totalLocal, true);
      return;
    }
    // Nothing was written, so the buyer is never told an order exists. The shop's own WhatsApp
    // thread carries the same list and the same choice instead.
    var msgCash = 'Hello *${escapeHtml(rawName)}*, I would like to order:' + NL + NL + plainLines.join(NL) + (notes ? (NL + NL + notes) : '') + NL + NL + 'Payment Choice: *CASH ON DELIVERY*' + NL + 'I will pay the merchant when the goods arrive.';
    var link = businessLinkFor(msgCash);
    if (link) window.open(link, '_blank');
  }

  function showSuccessModal(customerName) {
    document.getElementById('successCustomerName').innerText = customerName;
    document.getElementById('customSuccessModal').style.display = 'flex';
  }
  function closeSuccessModal() {
    document.getElementById('customSuccessModal').style.display = 'none';
    window.location.href = '#offerings';
  }

  async function submitOrder(e) {
    if (e && e.preventDefault) e.preventDefault();
    // THE BUTTON DOES WHAT THE TILE UNDER IT SAYS.
    //   Pay on delivery -> the menu asking digital or cash, never a silent card charge.
    //   Mobile Money    -> it is not switched on yet, so it says so and charges nothing.
    //   Card or PayPal  -> the checkout below.
    const chosen = String(payChoice || 'card');
    if (chosen === 'cod') { openPayStep(); return; }
    if (chosen === 'mobile') {
      var soon = document.getElementById('paySoonNotice');
      if (soon) soon.style.display = 'block';
      alert(fmt('soonTitle', {}) || 'Mobile Money is still under development');
      return;
    }
    // The name field is gone, so the order is not tagged with a name the buyer never typed; the
    // merchant gets the order itself and the buyer's delivery notes.
    const name = 'Valued Customer';
    const details = document.getElementById('cNotes').value;
    {
      // Real checkout: create the order, then hand the buyer to PayPal.
      const btn = document.getElementById('actionSubmitBtn');
      if (btn) { btn.disabled = true; btn.innerText = fmt('openingCheckout', {}) || 'Opening secure checkout...'; }

      let totalLocal = cart.reduce((sum, i) => sum + (i.priceLocal * i.qty), 0);
      // A cart where the merchant never gave a price cannot be charged a guessed amount. The
      // buyer is sent to the merchant to agree it, which is also what the card says.
      if (!(totalLocal > 0)) {
        if (btn) { btn.disabled = false; btn.innerText = fmt('btnPayPal', {}) || 'Pay securely with PayPal'; }
        alert(t('noPriceCheckout') || 'These items do not have a fixed price yet. Please message the merchant and you will agree the price, then pay.');
        var msgNoPrice = 'Hello *${escapeHtml(rawName)}*, I am ' + name + '. I want to order:\\n\\n' + details + '\\n\\nPlease confirm the price and availability.';
        window.open(businessLinkFor(msgNoPrice), '_blank');
        return;
      }
      // The card price is the money the buyer just read in the cart. It is charged in their own
      // currency when PayPal accepts it, and otherwise in the exact USD equivalent - never in a
      // silent figure that differs from what the shop showed them.
      const totalUsd = totalLocal / ugxPerUsd;
      const pay = paypalFigure(totalUsd);

      let checkout = {};
      try {
        const res = await fetch('https://orchid-frigatebird.pikapod.net/webhook/xlink-checkout', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            slug: '${slug}',
            merchant_name: '${rawName}',
            buyer_name: name,
            buyer_phone: '${phone}',
            amount_usd: pay.value,
            amount_local: totalLocal,
            display_currency: userCurrency,
            display_amount: showMoney(totalUsd),
            currency: pay.code,
            // The conversion the page used, and the shop's own pricing currency. With these the
            // payment workflow can never mistake a shilling total for a dollar amount: the figure
            // charged is the one this page showed, and nothing is silently re-converted.
            // The rate the page actually used, plus the moment it was published, so a charge can
            // always be traced back to a real published figure.
            ugx_per_usd: ugxPerUsd,
            rate_published: RATES_PUBLISHED,
            fx_margin_percent: FX_MARGIN_PERCENT,
            shop_currency: '${String(pricingCurrency || "UGX").toUpperCase()}',
            items_summary: details || cart.map(i => i.name).join(', ')
          })
        });
        checkout = await res.json();
      } catch (err) {
        checkout = {};
      }

      if (checkout && checkout.approve_url) {
        // Order stored as PENDING. Send the buyer to PayPal to approve the payment.
        window.location.href = checkout.approve_url;
        return;
      }

      if (btn) { btn.disabled = false; btn.innerText = fmt('btnPayPal', {}) || 'Authorize & Pay Securely with PayPal'; }
      alert(fmt('payFailed', {}) || 'We could not start the payment right now. Please try again in a moment.');
      return;
    }
  }
`;

let compiledHtml = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(rawName)} | Secure Portal</title>
  <!-- THE PAGE MUST PAINT BEFORE ANY NETWORK HOP.
       The web font used to be a blocking stylesheet in the head: the browser downloaded a
       third-party CSS file, then five font files, and showed NOTHING until that finished. On a
       phone on mobile data that alone was seconds of blank screen, and it grew with every
       rebuild. It is now loaded after the first paint, with the system font shown immediately
       and swapped in when it arrives, so the shop appears at once and no third-party outage can
       hold it back. -->
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" media="print" onload="this.media='all'">
  <style>
    /* Every colour below was measured against the colour behind it, so lettering stays visible
       whatever background or brand colour the merchant chose. */
    :root { ${themeVars} }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif; background: var(--page-bg); color: var(--page-ink); line-height: 1.6; scroll-behavior: smooth; }
    a { text-decoration: none; color: inherit; }
    header.site-nav { position: absolute; top: 0; left: 0; width: 100%; display: flex; justify-content: space-between; align-items: center; padding: 1.6rem 6vw; z-index: 100; background: linear-gradient(180deg, rgba(2,6,23,0.55) 0%, rgba(2,6,23,0.28) 62%, rgba(2,6,23,0) 100%); }
    .brand-logo { font-size: 1.35rem; font-weight: 800; letter-spacing: -0.02em; text-transform: uppercase; color: #ffffff; text-shadow: 0 2px 10px rgba(2,6,23,0.85); }
    .nav-links { display: flex; gap: 2.2rem; list-style: none; align-items: center; }
    /* The nav sits on the picture, so the letters carry their own shadow - readable on a white
       product shot and on a dark one. */
    .nav-links a { color: #ffffff; font-size: 0.88rem; font-weight: 700; text-shadow: 0 1px 6px rgba(2,6,23,0.95), 0 0 2px rgba(2,6,23,0.9); }
    .btn-nav-wa { background: var(--primary-green) !important; color: var(--wa-ink) !important; padding: 9px 22px !important; border-radius: 999px !important; font-weight: 800 !important; font-size: 0.82rem !important; }
    @media(max-width: 860px) { .nav-links { display: none; } }
    /* The hero fills the whole screen, and the merchant's own picture is shown at full strength
       rather than faded to ghost. The dark scrim under the words is what keeps the headline
       readable on a light photo and on a dark one. */
    .hero { position: relative; width: 100%; min-height: 100vh; min-height: 100svh; display: flex; align-items: center; justify-content: center; text-align: center; padding: 130px 6vw 70px; background: var(--page-bg); overflow: hidden; }
    .hero.hero-has-image { background: var(--page-bg); }
    .hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: center center; opacity: 1; z-index: 1; }
    .hero-no-image { display: none; }
    /* A flyer used as the full-screen banner is softened: its small print would look broken if
       blown up sharp, and the same flyer is shown sharp on its card above. */
    .hero-img-soft { filter: blur(7px) saturate(1.05); transform: scale(1.08); }
    .hero-overlay { position: absolute; inset: 0; background: var(--hero-scrim); z-index: 2; }
    .hero-content { position: relative; z-index: 3; max-width: 980px; width: 100%; margin: 0 auto; }
    .hero-tag { display: inline-block; font-size: 0.78rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.16em; color: #ffffff; background: rgba(2,6,23,0.78); backdrop-filter: blur(8px); border: 1px solid rgba(255,255,255,0.28); padding: 7px 20px; border-radius: 999px; margin-bottom: 1.5rem; }
    .hero h1 { font-size: clamp(2.6rem, 6.4vw, 4.8rem); font-weight: 800; line-height: 1.1; letter-spacing: -0.035em; color: #ffffff; margin-bottom: 1.2rem; text-shadow: 0 2px 8px rgba(2,6,23,0.9), 0 4px 26px rgba(2,6,23,0.75); }
    /* A flyer or logo is the merchant's mark: shown whole on its own card so its small print is
       readable, never stretched behind the headline. */
    .hero-map-pill { display: inline-flex; align-items: center; gap: 12px; background: rgba(15, 23, 42, 0.88); border: 1px solid rgba(56, 189, 248, 0.45); padding: 9px 20px; border-radius: 999px; backdrop-filter: blur(12px); box-shadow: 0 4px 20px rgba(0,0,0,0.5); margin-bottom: 2.2rem; }
    .live-dot { width: 8px; height: 8px; border-radius: 50%; background: #22c55e; box-shadow: 0 0 10px #22c55e; }
    .map-pill-text { font-size: 0.85rem; font-weight: 600; color: #f8fafc; }
    .hero-no-image + .hero-content .hero-map-pill, .hero.hero-has-image .hero-map-pill { background: rgba(2,6,23,0.86); }
    .map-pill-btn { background: #38bdf8; color: #0f172a; font-weight: 800; font-size: 0.78rem; padding: 6px 14px; border-radius: 999px; text-decoration: none; }
    .hero-btns { display: flex; gap: 1.2rem; justify-content: center; flex-wrap: wrap; }
    /* The shop's own line, printed on the page. A buyer who taps through to WhatsApp can still
       see which number they are on, and nobody has to guess it. */
    .hero-contact { margin-top: 1.1rem; font-size: 0.88rem; font-weight: 600; color: #f8fafc; text-shadow: 0 2px 10px rgba(0,0,0,0.55); }
    .hero-contact a { color: #ffffff; font-weight: 800; text-decoration: underline; text-underline-offset: 3px; }
    /* Two pills under the hero buttons, carrying the shop's own number - tappable on a phone. */
    .hero-contact-pills { display: flex; flex-wrap: wrap; gap: 0.5rem; margin-top: 1.1rem; }
    .hero-contact-pill { display: inline-flex; align-items: center; gap: 6px; padding: 0.7rem 1.15rem; border-radius: 999px; font-size: 0.86rem; font-weight: 800; text-decoration: none; background: rgba(2,6,23,0.62); color: #ffffff; border: 1px solid rgba(255,255,255,0.38); backdrop-filter: blur(6px); }
    @media (max-width: 520px) { .hero-contact-pills { gap: 0.45rem; } .hero-contact-pill { padding: 0.62rem 0.95rem; font-size: 0.8rem; } }
    .btn-hero-dark { background: var(--brand); color: var(--on-brand); padding: 1rem 2.5rem; border-radius: 999px; font-weight: 800; font-size: 0.95rem; box-shadow: 0 10px 28px rgba(2,6,23,0.35); }
    .btn-hero-outline { background: rgba(255,255,255,0.92); backdrop-filter: blur(8px); border: 1px solid #ffffff; color: #0b1220; padding: 1rem 2.2rem; border-radius: 999px; font-weight: 800; font-size: 0.95rem; }
    section.catalog { background: var(--page-bg); color: var(--page-ink); padding: 7rem 6vw; max-width: 1280px; margin: 0 auto; }
    .catalog-toolbar { display: flex; flex-direction: column; gap: 1.2rem; margin-bottom: 3.5rem; align-items: center; }
    .search-input-box { width: 100%; max-width: 600px; padding: 14px 22px; border-radius: 999px; border: 1px solid var(--surface-border); font-family: inherit; font-size: 0.95rem; outline: none; background: var(--surface-2); color: var(--surface-ink); box-shadow: 0 4px 20px rgba(0,0,0,0.04); }
    .search-input-box::placeholder { color: var(--surface-muted); }
    .category-menu-bar { display: flex; gap: 10px; flex-wrap: wrap; justify-content: center; max-width: 900px; }
    .menu-pill { background: var(--surface-2); color: var(--surface-ink); border: 1px solid var(--surface-border); padding: 7px 16px; border-radius: 999px; font-size: 0.82rem; font-weight: 700; text-transform: uppercase; cursor: pointer; }
    .menu-pill:hover, .menu-pill.active-pill { background: var(--brand); color: var(--on-brand); border-color: var(--brand); }
    .safety-banner { background: var(--surface); border-left: 3px solid #f87171; padding: 13px 17px; margin-bottom: 3rem; color: var(--surface-ink); font-size: 0.88rem; border-radius: 6px; }
    .promo-banner { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; background: var(--brand-tint); border-left: 4px solid var(--brand); padding: 14px 18px; margin-bottom: 1.75rem; color: var(--page-ink); font-size: 0.95rem; border-radius: 4px; }
    .promo-tag { background: var(--brand); color: var(--on-brand); font-size: 0.7rem; font-weight: 800; letter-spacing: 0.09em; padding: 4px 10px; border-radius: 999px; }
    .promo-text { font-weight: 600; }
    .product-row { display: grid; grid-template-columns: 1.4fr 1fr; gap: 3.5rem; align-items: center; border-top: 1px solid var(--surface-border); padding: 3rem 0; }
    @media (max-width: 860px) { .product-row { grid-template-columns: 1fr; gap: 1.8rem; } }
    .product-meta { font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em; color: var(--brand-dark); text-transform: uppercase; margin-bottom: 0.4rem; }
    .product-title { font-size: clamp(1.4rem, 2.5vw, 1.9rem); font-weight: 700; line-height: 1.2; letter-spacing: -0.02em; margin-bottom: 0.6rem; color: var(--page-ink); }
    .product-desc { font-size: 1rem; color: var(--page-muted); margin-bottom: 1.2rem; line-height: 1.6; max-width: 520px; }
    .product-price { font-size: 1.35rem; font-weight: 800; color: var(--brand-dark); margin-bottom: 0.5rem; }
    .btn-primary-cart { display: inline-flex; align-items: center; justify-content: center; gap: 8px; width: 100%; max-width: 260px; background: var(--brand); color: var(--on-brand); border: none; border-radius: 999px; padding: 12px 18px; font-family: inherit; font-size: 0.95rem; font-weight: 800; cursor: pointer; box-shadow: 0 6px 18px rgba(0,0,0,0.14); }
    .btn-primary-cart:hover { filter: brightness(1.06); }
    .btn-primary-cart:active { transform: translateY(1px); }
    /* The product-card payment tiles and the "how would you like to pay" pop-up are deleted, so
       their rules are deleted with them. */
    .stock-note { font-size: 0.78rem; font-weight: 700; color: var(--brand-dark); margin-bottom: 0.6rem; }
    .stock-note.stock-out { color: #b42318; }
    .product-actions { display: flex; flex-direction: column; gap: 8px; align-items: flex-start; }
    .action-link { display: inline-flex; align-items: center; gap: 6px; font-size: 0.92rem; font-weight: 700; color: var(--page-ink); border-bottom: 2px solid var(--page-ink); padding-bottom: 2px; }
    .mini-actions { display: flex; gap: 8px; margin-top: 8px; flex-wrap: wrap; align-items: center; }
    .mini-actions .btn-subtle { text-decoration: none; display: inline-flex; align-items: center; }
    .btn-subtle { background: var(--surface-2); border: 1px solid var(--surface-border); color: var(--surface-ink); font-size: 0.75rem; font-weight: 700; padding: 4px 10px; border-radius: 4px; cursor: pointer; }
    .product-img-wrap { width: 100%; border-radius: 12px; background: var(--surface-2); box-shadow: 0 6px 20px rgba(0,0,0,0.06); border: 2px solid var(--brand); overflow: hidden; }
    /* A product picture is shown whole. Cropping it cut the top off bottles and the bottom off
       shoes, so the card keeps the entire picture on a background that matches the page. */
    .product-img-wrap img { background: var(--surface-2); }
    #main-pg0, .product-img-wrap > img { display: block; width: 100%; height: 320px; object-fit: contain; }
    /* An item with no usable photo shows the shop's own branded tile with the item's initials -
       never a stock or placeholder picture, and never the same image as another product. */
    .img-empty { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; width: 100%; height: 320px; background: linear-gradient(150deg, var(--brand-tint) 0%, var(--surface-2) 100%); color: var(--surface-ink); text-align: center; padding: 20px; }
    .img-empty-mark { display: inline-flex; align-items: center; justify-content: center; width: 78px; height: 78px; border-radius: 50%; background: var(--brand); color: var(--on-brand); font-size: 1.8rem; font-weight: 800; letter-spacing: -0.02em; }
    .img-empty-text { font-size: 0.78rem; font-weight: 700; color: var(--surface-muted); text-transform: uppercase; letter-spacing: 0.08em; }
    .gallery-strip { display: flex; gap: 6px; padding: 6px; overflow-x: auto; background: var(--surface-2); border-top: 1px solid var(--surface-border); }
    .gallery-thumb { flex: 0 0 auto; width: 52px; height: 52px; padding: 0; border: 2px solid rgba(127,127,127,0.35); border-radius: 8px; background: var(--surface-2); cursor: pointer; overflow: hidden; }
    .gallery-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
    .gallery-thumb.active-thumb { border-color: var(--brand); box-shadow: 0 0 0 2px rgba(0,0,0,0.06); }

    .custom-modal-overlay { display: none; position: fixed; inset: 0; background: rgba(14, 23, 42, 0.75); z-index: 99999; align-items: center; justify-content: center; backdrop-filter: blur(8px); animation: fadeIn 0.3s ease; }
    /* The two pop-ups are deliberately white cards. Their own text colour is set here so it does
       not inherit the page's light-on-dark ink, which made the small print invisible on a dark
       shop. */
    .custom-modal-box { background: #ffffff; color: #101828; padding: 2.5rem; border-radius: 20px; width: 90%; max-width: 440px; box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.3); text-align: center; border: 1px solid rgba(0,48,135,0.1); transform: translateY(0); animation: slideUp 0.3s ease; }
    .custom-modal-icon { width: 64px; height: 64px; border-radius: 50%; background: #e0f2fe; color: #0284c7; display: flex; align-items: center; justify-content: center; font-size: 1.8rem; margin: 0 auto 1.2rem; box-shadow: 0 0 20px rgba(2, 132, 199, 0.2); }
    .custom-modal-title { font-size: 1.35rem; font-weight: 800; color: #0f172a; margin-bottom: 0.5rem; }
    .custom-modal-text { font-size: 0.95rem; color: #475569; line-height: 1.5; margin-bottom: 1.8rem; }
    .custom-modal-btn { background: var(--paypal-blue); color: var(--on-brand); border: none; padding: 0.9rem 2rem; border-radius: 999px; font-weight: 700; font-size: 0.95rem; cursor: pointer; width: 100%; box-shadow: 0 4px 15px rgba(0,48,135,0.3); transition: background 0.2s; }
    .custom-modal-btn:hover { background: var(--paypal-accent); }
    /* ONE contact card, used inside the order confirmation. The number is shown in full, and
       text / call / video sit right under it. */
    .contact-card { background: rgba(15,23,42,0.04); border: 1px solid var(--card-border); border-radius: 18px; padding: 1rem 1rem 0.9rem; margin: 0 0 0.9rem; }
    .contact-label { font-size: 0.72rem; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; color: var(--surface-muted); margin-bottom: 0.35rem; }
    .contact-number { font-size: 1.12rem; font-weight: 800; letter-spacing: 0.02em; color: var(--page-ink); margin-bottom: 0.75rem; }
    .contact-action { display: block; text-align: center; text-decoration: none; padding: 0.75rem 1rem; border-radius: 999px; font-weight: 800; font-size: 0.92rem; background: var(--primary-green); color: var(--wa-ink); margin-bottom: 0.5rem; }
    .contact-wa { display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; padding: 12px 18px; margin: 0 0 0.6rem; border-radius: 999px; font-size: 0.95rem; font-weight: 800; text-decoration: none; background: var(--primary-green); color: var(--wa-ink); }
    #confirmCallLink { background: #0f172a; color: #ffffff; }
    #confirmVideoLink { background: transparent; color: var(--page-ink); border: 1px solid var(--card-border); }
    .contact-alt { font-size: 0.8rem; font-weight: 600; color: var(--surface-muted); margin-top: 0.5rem; border-top: 1px solid var(--card-border); padding-top: 0.55rem; word-break: break-word; }
    .footer-contact h3 { color: var(--footer-ink-strong); font-size: 1.05rem; font-weight: 800; margin-bottom: 0.6rem; }
    .footer-number { display: inline-block; font-size: 1.1rem; font-weight: 800; letter-spacing: 0.02em; margin-bottom: 0.6rem; }
    /* Footer contact: one tappable WhatsApp button carrying the shop's own number, and a Call
       link that dials that same number. Both are full-width pills so a phone thumb hits them. */
    .footer-chat-btn, .footer-call-link { display: flex; align-items: center; justify-content: center; gap: 6px; width: 100%; max-width: 320px; padding: 12px 18px; border-radius: 999px; font-size: 0.92rem; font-weight: 800; text-decoration: none; margin-bottom: 0.55rem; }
    .footer-chat-btn { background: var(--primary-green); color: var(--wa-ink); border: 1px solid rgba(255,255,255,0.35); }
    .footer-call-link { background: rgba(255,255,255,0.10); color: var(--footer-ink-strong); border: 1px solid rgba(255,255,255,0.35); }

    @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
    @keyframes slideUp { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }

    .modal-overlay { display: none; position: fixed; inset: 0; background: rgba(0,0,0,0.7); z-index: 9999; align-items: center; justify-content: center; backdrop-filter: blur(4px); }
    .modal-box { background: #ffffff; color: #101828; padding: 2rem; border-radius: 16px; width: 90%; max-width: 440px; box-shadow: 0 20px 40px rgba(0,0,0,0.3); text-align: center; }
    .modal-input { width: 100%; padding: 12px 16px; background: #ffffff; color: #101828; border: 2px solid rgba(15,23,42,0.18); border-radius: 10px; font-size: 1.1rem; font-weight: 700; text-align: center; margin-bottom: 1.2rem; outline: none; }
    .modal-btns { display: flex; gap: 10px; }
    .modal-btn-submit { flex: 1; background: #0ea5e9; color: #06202f; border: none; padding: 12px; border-radius: 10px; font-weight: 700; cursor: pointer; }
    .modal-btn-cancel { flex: 1; background: #e2e8f0; color: #1e293b; border: none; padding: 12px; border-radius: 10px; font-weight: 700; cursor: pointer; }
    section.about-section { background: var(--page-bg); color: var(--page-ink); padding: 5rem 6vw 7rem; }
    .about-grid { max-width: 1280px; margin: 0 auto; text-align: center; }
    .about-text h2 { font-size: clamp(1.8rem, 3.2vw, 2.7rem); font-weight: 700; margin-bottom: 1.5rem; color: var(--brand-dark); }
    .about-text p { font-size: 1.05rem; color: var(--page-muted); line-height: 1.75; max-width: 800px; margin: 0 auto 2rem; }
    section.order-wrapper { background: var(--surface); color: var(--surface-ink); padding: 7rem 6vw; }
    .order-grid { max-width: 980px; margin: 0 auto; display: grid; grid-template-columns: 1fr 1.3fr; gap: 4.5rem; }
    @media (max-width: 860px) { .order-grid { grid-template-columns: 1fr; gap: 2.5rem; } }
    .order-text h2 { font-size: clamp(2rem, 3.5vw, 2.8rem); font-weight: 700; margin-bottom: 1rem; color: var(--surface-ink); }
    .order-text p { font-size: 1rem; color: var(--surface-muted); }
    .form-fields { display: flex; flex-direction: column; gap: 1.25rem; }
    .field-group { display: flex; flex-direction: column; gap: 0.35rem; }
    .field-group label { font-size: 0.8rem; font-weight: 700; color: var(--surface-muted); text-transform: uppercase; }
    .field-group input, .field-group select, .field-group textarea { width: 100%; padding: 0.85rem 1.1rem; background: var(--surface-2); color: var(--surface-ink); border: 1px solid var(--surface-border); border-radius: 10px; font-family: inherit; font-size: 0.95rem; outline: none; }
    .field-group input::placeholder, .field-group textarea::placeholder { color: var(--surface-muted); opacity: 1; }

    /* TWO ways to settle in the order form: pay digitally now (Card or PayPal), or order it on
       cash and pay the merchant on arrival. It was three cards, and the third repeated what the
       cash card already said, so the buyer had to pick between options that meant the same thing. */
    /* The merchant's own layout: the two DIGITAL doors stand SIDE BY SIDE - Card or PayPal on the
       left, Mobile Money (not switched on) on the right - and Pay on delivery runs the full width
       underneath them, because it is the one that needs the whole row to explain itself. */
    .payment-options-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; align-items: stretch; }
    /* The pay-on-delivery tile spans the row under both of them. */
    .payment-options-grid > #payCardCod { grid-column: 1 / -1; }
    /* Both top tiles stay the same height whatever the length of their wording. */
    .payment-options-grid > #payCardDigital, .payment-options-grid > #payCardMobile { height: 100%; }
    .pay-card-icon { font-size: 1.1rem; line-height: 1; }
    /* The "still under development" note sits under the tiles, not on top of them, so the two
       working choices stay visible and tappable while it explains itself. */
    .pay-notice { display: none; flex-direction: column; gap: 2px; margin-top: 10px; padding: 12px 14px; border-radius: 10px; background: #fff7ed; border: 1px solid #fdba74; color: #7c2d12; font-size: 0.82rem; line-height: 1.5; }
    .pay-notice strong { font-size: 0.85rem; font-weight: 800; }
    /* The pay-on-delivery question: two big, obvious choices, each naming what happens next. */
    .pay-step-grid { display: grid; grid-template-columns: 1fr; gap: 10px; margin-top: 6px; }
    .pay-step-btn { display: flex; flex-direction: column; gap: 3px; align-items: flex-start; text-align: left; width: 100%; padding: 14px 16px; border-radius: 12px; border: 1px solid var(--surface-border); background: var(--surface-2); color: var(--surface-ink); cursor: pointer; font-family: inherit; transition: all 0.2s ease; }
    .pay-step-btn:hover { border-color: var(--brand); background: var(--brand-tint); }
    .pay-step-name { font-size: 0.95rem; font-weight: 800; }
    .pay-step-sub { font-size: 0.78rem; font-weight: 500; color: var(--surface-muted); }
    /* The receipt is a plain white card: the buyer may screenshot it or read it out to the shop. */
    .receipt-box { text-align: left; }
    .receipt-lines { display: flex; flex-direction: column; gap: 6px; margin: 12px 0 10px; padding: 12px 0; border-top: 1px dashed rgba(15,23,42,0.18); border-bottom: 1px dashed rgba(15,23,42,0.18); }
    .receipt-line { display: flex; justify-content: space-between; gap: 12px; font-size: 0.86rem; color: var(--page-ink); }
    .receipt-line span:last-child { font-weight: 700; white-space: nowrap; }
    .receipt-total { display: flex; justify-content: space-between; align-items: baseline; font-size: 0.9rem; font-weight: 800; color: var(--page-ink); }
    .receipt-total strong { font-size: 1.05rem; }
    .receipt-ref { display: flex; justify-content: space-between; align-items: baseline; margin-top: 6px; font-size: 0.8rem; font-weight: 600; color: var(--surface-muted); letter-spacing: 0.06em; text-transform: uppercase; }
    .receipt-ref strong { font-size: 0.9rem; color: var(--page-ink); letter-spacing: 0.04em; }
    .receipt-method { margin-top: 12px; font-size: 0.82rem; font-weight: 700; color: var(--page-ink); }
    .receipt-note { margin-top: 4px; font-size: 0.78rem; line-height: 1.5; color: var(--surface-muted); }
    .receipt-box .custom-modal-btn { margin-top: 16px; }
    .pay-card { position: relative; display: flex; flex-direction: column; padding: 16px; background: var(--surface-2); color: var(--surface-ink); border: 1px solid var(--surface-border); border-radius: 12px; cursor: pointer; transition: all 0.2s ease; box-shadow: 0 1px 3px rgba(15,23,42,0.05); }
    .pay-card:hover { border-color: var(--brand); background: var(--brand-tint); }
    .pay-card:has(input:checked) { border-color: var(--brand); box-shadow: 0 0 0 2px var(--brand) inset; }
    .pay-card input[type="radio"] { position: absolute; top: 14px; right: 14px; accent-color: var(--paypal-blue); }
    .pay-card-header { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; }
    .pay-card-title { font-size: 0.92rem; font-weight: 800; color: var(--surface-ink); }
    .pay-card-sub { font-size: 0.78rem; color: var(--surface-muted); font-weight: 500; }

    .paypal-badge-svg { display: inline-flex; align-items: center; font-weight: 800; font-style: italic; font-size: 0.95rem; letter-spacing: -0.5px; color: var(--surface-ink); }
    .paypal-badge-svg span { color: var(--brand-dark); }

    .card-fields-container { display: flex; flex-direction: column; gap: 10px; background: var(--surface-2); color: var(--surface-ink); padding: 18px; border-radius: 12px; border: 1px solid var(--surface-border); margin-top: 5px; box-shadow: inset 0 2px 4px rgba(0,0,0,0.02); }
    .security-badge-row { display: flex; align-items: center; gap: 6px; font-size: 0.75rem; font-weight: 700; color: var(--surface-ink); text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 2px; }

    /* The total the buyer is about to pay, in the same money as the cards, with the settlement
       currency spelled out underneath when PayPal cannot charge in the visitor's own currency. */
    .order-total-row { display: flex; flex-direction: column; gap: 2px; background: var(--surface-2); border: 1px solid var(--surface-border); border-radius: 10px; padding: 12px 14px; }
    .order-total-value { font-size: 1.25rem; font-weight: 800; color: var(--brand-dark); }
    .order-total-note { font-size: 0.78rem; font-weight: 600; color: var(--surface-muted); }
    .btn-submit { background: var(--brand); color: var(--on-brand); border: none; padding: 1.1rem; border-radius: 999px; font-size: 1rem; font-weight: 800; cursor: pointer; width: 100%; margin-top: 0.5rem; display: block; box-shadow: 0 6px 20px rgba(0,0,0,0.18); transition: background 0.2s; }
    .btn-submit:hover { background: var(--brand-hover); color: var(--on-brand); }

    footer { background: var(--bg-dark); color: var(--footer-ink); padding: 4.5rem 6vw 3rem; font-size: 0.88rem; }
    .footer-grid { max-width: 1280px; margin: 0 auto 3rem; display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 3.5rem; }
    .footer-map-link { display: inline-block; margin-top: 8px; font-size: 0.82rem; font-weight: 700; color: var(--footer-ink-strong); border-bottom: 1px solid currentColor; padding-bottom: 1px; }
