    @media (max-width: 860px) { .footer-grid { grid-template-columns: 1fr; } }
    .footer-brand h3 { color: var(--footer-ink-strong); font-size: 1.3rem; font-weight: 800; margin-bottom: 0.75rem; }
    .footer-bottom { max-width: 1280px; margin: 0 auto; padding-top: 2rem; border-top: 1px solid rgba(255,255,255,0.16); display: flex; justify-content: space-between; }
    .cart-widget { display: none; position: fixed; bottom: 22px; right: 22px; background: var(--primary-green); color: var(--wa-ink); padding: 13px 22px; border-radius: 999px; font-weight: 800; font-size: 0.95rem; cursor: pointer; box-shadow: 0 8px 25px rgba(37,211,102,0.45); z-index: 999; align-items: center; justify-content: center; gap: 6px; -webkit-tap-highlight-color: transparent; }
    .cart-widget:active { transform: scale(0.98); }
    /* A short confirmation the item really went in, so a buyer on a phone is never left
       wondering whether the tap registered. */
    #cartToast { display: none; position: fixed; left: 50%; transform: translateX(-50%); bottom: 92px; background: #0f172a; color: #ffffff; padding: 10px 18px; border-radius: 999px; font-size: 0.85rem; font-weight: 700; z-index: 1000; opacity: 0; transition: opacity 0.35s ease; max-width: 88vw; text-align: center; box-shadow: 0 10px 24px rgba(0,0,0,0.35); }
    /* Status chips carry their own light background so they stay readable on a dark page too. */
    .stock-note { display: inline-block; font-size: 0.78rem; font-weight: 700; color: #14532d; background: #dcfce7; border: 1px solid #86efac; border-radius: 999px; padding: 3px 10px; margin-bottom: 0.7rem; }
    .stock-note.stock-out { color: #7f1d1d; background: #fee2e2; border-color: #fca5a5; }

    /* One layout system for every screen. Sizes are fluid rather than fixed, so a laptop, a
       tablet held either way, and a phone all get a page that fits without zooming or
       overlapping. Tap targets stay at least 44px on touch screens. */
    html { -webkit-text-size-adjust: 100%; }
    img, svg, video { max-width: 100%; }
    /* The first screen is the merchant's picture, full height on every device. */
    .hero { height: auto; min-height: 100vh; min-height: 100svh; }
    /* Extra shop photos sit in one tidy band under the hero so a merchant's own pictures are
       seen immediately instead of being buried inside the catalogue. */
    .hero-strip { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 0; background: var(--page-bg); }
    .hero-strip img { width: 100%; height: 170px; object-fit: cover; display: block; }
    @media (max-width: 1100px) {
      header.site-nav { padding: 1.6rem 4vw; }
      section.catalog, section.about-section, section.order-wrapper { padding-left: 4vw; padding-right: 4vw; }
      .product-row { gap: 2.2rem; }
      .order-grid { gap: 2.5rem; }
      .footer-grid { gap: 2rem; }
    }
    /* Tablets in portrait: the two-column product layout is too tight, so it stacks. */
    @media (max-width: 900px) and (min-width: 641px) {
      .product-row { grid-template-columns: 1fr; gap: 1.6rem; }
      .product-img-wrap { order: -1; }
