      .nav-links { gap: 1.4rem; }
    }
    /* Phones: single column, full-width controls, nothing overlapping. */
    @media (max-width: 640px) {
      /* Two narrow tiles side by side become unreadable on a phone, so they stack - and the
         pay-on-delivery tile keeps spanning the (single) column it now sits in. */
      .payment-options-grid { grid-template-columns: 1fr !important; }
      .payment-options-grid > #payCardCod { grid-column: auto; }
      .pay-step-btn { min-height: 56px; }
      .pay-card { min-height: 64px; }
      .btn-submit, .modal-btn-submit, .modal-btn-cancel { min-height: 48px; }
      .field-group input, .field-group select, .field-group textarea { font-size: 16px; }
      #cartToast { bottom: 84px; }
    }
    @media (hover: none) {
