    }

    /* Sizes scale with the screen instead of fighting for space. On a phone the shop is
       one column, nothing overflows, buttons are full width and big enough to tap. */
    body { overflow-x: hidden; }
    @media (max-width: 640px) {
      header.site-nav { padding: 0.9rem 4vw; position: absolute; }
      .brand-logo { font-size: 1rem; max-width: 52vw; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
      #langSelect { padding: 6px 10px !important; font-size: 0.7rem !important; margin-right: 6px !important; max-width: 30vw; }
      .btn-nav-wa { padding: 7px 14px !important; font-size: 0.7rem !important; }
      .hero { min-height: 100vh; min-height: 100svh; height: auto; padding: 96px 5vw 44px; }
      .hero-strip img { height: 110px; }
      .hero-content { width: 100%; }
      .hero h1 { font-size: clamp(1.5rem, 7.2vw, 2.1rem); line-height: 1.2; }
      .hero-tag { font-size: 0.6rem; letter-spacing: 0.1em; padding: 5px 12px; }
      .hero-map-pill { flex-wrap: wrap; justify-content: center; gap: 8px; padding: 8px 12px; }
      .map-pill-text { font-size: 0.72rem; }
      .map-pill-btn { font-size: 0.7rem; padding: 5px 10px; }
      .hero-btns { flex-direction: column; align-items: stretch; gap: 0.6rem; }
      .btn-hero-dark, .btn-hero-outline { padding: 0.85rem 1rem; font-size: 0.88rem; text-align: center; width: 100%; }
      section.catalog { padding: 2.5rem 4vw; }
