// The hand-off message names what actually happened: a brand-new shop, or the change the
// merchant asked for. A promotion, when they set one, is repeated back so they can see it took.
const isEdit = intent === 'UPDATE_STORE';
// THE STATIC EDIT CONFIRMATION WINS.
// The merchant asked to be told the same way every time: what was applied, and whether anything
// went wrong. That text is built from a real before/after comparison in Validate & Route Intent,
// so it is used verbatim here instead of a freshly phrased sentence that could contradict it.
const staticEditReply = String(inputItems[0].json.editConfirmReply || '').trim();
const promoLine = promotionText ? `\\n\\n🏷️ *Promotion live:* ${promotionText}` : '';
let whatsappReply = (isEdit && staticEditReply.length > 10)
  ? staticEditReply
  : (isEdit
  ? `✅ *${rawName} is updated.*\\n\\nYour shop now shows ${products.length} item${products.length === 1 ? '' : 's'} at the prices you gave.${promoLine}\\n\\n🌐 *Your shop:*\\n${liveStoreUrl}\\n\\nSend another message any time to change a price, add an item, or run a promotion.`
  : `🎉 *Congratulations ${rawName}!*\\n\\nYour official X-Link Digital Storefront is live with active cart checkout, native card processing, and global currency localization.${promoLine}\\n\\n🌐 *View your storefront here:*\\n${liveStoreUrl}\\n\\n💡 *Tip:* Send a message any time to change a price, add an item, or run a promotion. Type *“insights”* to see your sales.`);

// The record is built here, before the return, because the caller reads it: the saved catalogue
// and the stored page must both carry the products exactly as they were rendered.
let record = {
  slug: slug,
  parsedData: { ...parsedData, products_and_services: products }
};

globalThis.xLinkStores = globalThis.xLinkStores || {};
globalThis.xLinkStores[slug] = compiledHtml;
try {
  const staticData = $getWorkflowStaticData('global');
  staticData.stores = staticData.stores || {};
  staticData.stores[slug] = compiledHtml;
  staticData.merchants = staticData.merchants || {};
  staticData.merchants[phone] = staticData.merchants[phone] || {};
  const existing = Array.isArray(staticData.merchants[phone].stores) ? staticData.merchants[phone].stores : [];
  // The shop's front page picture is saved WITH the catalogue. Without it every later edit had to
  // guess the hero again, and a product photo sent in the meantime could take the slot.
  record = { slug, parsedData: { ...parsedData, products_and_services: products, homepage_image: homepageImageUrl || String(parsedData.homepage_image || '') } };
  const idx = existing.findIndex((st) => st.slug === slug);
  // One entry per business: update this business's own entry, never another one's.
  if (idx >= 0) existing[idx] = record; else existing.push(record);
  staticData.merchants[phone].stores = existing;
  // The business this number is currently working on. A later edit reads this first, so it
  // can never land on another merchant's shop.
  staticData.merchants[phone].currentSlug = slug;
  staticData.merchants[phone].catalogue = record.parsedData;
  staticData.merchants[phone].brandColor = brandColor;
} catch(e) {}

// ── PAGE WEIGHT ──────────────────────────────────────────────────────────────
// Every comment in this file used to be printed into the delivered page, because the CSS and the
// script are one big template literal and its comments travel with it. That is roughly 14 KB of
// English explanation sitting in front of a visitor on a phone before anything they can read - on
// every rebuild, on every shop - and it is also the whole implementation of the shop handed to
// anyone who opens the page source. The comments belong here, in the source, not in the product.
// They are removed once, at build time, on the finished string:
//   * CSS comments are dropped (no CSS string value in this page contains a slash-star pair).
//   * JavaScript comments are dropped ONLY inside the single page script, and never from a string
//     literal, so a URL that happens to contain "//" and every quote inside a message stay intact.
// Blank lines and leading indentation go too - the layout is CSS, not whitespace.
try {
  const stripPageWeight = (html) => {
    const commentsLike = new RegExp('/' + String.fromCharCode(92) + '*' + '[^]*?' + String.fromCharCode(92) + '*' + '/', 'g');
    let out = String(html || '').replace(commentsLike, '');
    out = out.replace(new RegExp('<script>([^]*?)</' + 'script>', 'g'), (whole, body) => {
      let kept = '';
      let i = 0;
      let quote = '';
      while (i < body.length) {
        const ch = body.charAt(i);
        const next = body.charAt(i + 1);
        if (quote) {
          kept += ch;
          if (ch === String.fromCharCode(92)) { kept += next; i += 2; continue; }
          if (ch === quote) quote = '';
          i += 1;
          continue;
        }
        if (ch === '"' || ch === String.fromCharCode(39) || ch === String.fromCharCode(96)) { quote = ch; kept += ch; i += 1; continue; }
        if (ch === '/' && next === '/') {
          while (i < body.length && body.charAt(i) !== String.fromCharCode(10)) i += 1;
          continue;
        }
        if (ch === '/' && next === '*') {
          i += 2;
          while (i < body.length && !(body.charAt(i) === '*' && body.charAt(i + 1) === '/')) i += 1;
          i += 2;
          continue;
        }
        kept += ch;
        i += 1;
      }
      return '<script>' + kept.split(String.fromCharCode(10)).map((line) => line.replace(/^[ 	]+/, '')).filter((line) => line.trim() !== '').join(String.fromCharCode(10)) + '</script>';
    });
    return out;
  };
  compiledHtml = stripPageWeight(compiledHtml);
} catch (e) {}

return [{
  json: {
    slug: slug,
    html_content: String(compiledHtml)
      .split('@VIDEOBTN@').join(videoBtnHtml)
      .split('@ALTERNATE@').join(contactAltHtml)
      .split('@FOOTERVIDEO@').join(footerVideoHtml)
      .split('@FOOTERALT@').join(footerAltHtml),
    live_store_url: liveStoreUrl,
    whatsapp_reply: whatsappReply,
    // Passed through untouched so the delivered message is the static comparison of what
    // changed, not a re-worded version of it.
    editConfirmReply: staticEditReply,
    editConfirmIssue: String(inputItems[0].json.editConfirmIssue || ''),
    editConfirmLines: Array.isArray(inputItems[0].json.editConfirmLines) ? inputItems[0].json.editConfirmLines : [],
    // The shop's own front page picture, kept separate from every product photo.
    homepage_image: homepageImageUrl,
    merchant_name: rawName,
    senderPhone: phone,
    // The RESOLVED products, not the raw agent payload. Their own photos, the amount in stock and
    // the bargaining flag live only on the resolved cards, so returning the raw payload here is
    // what saved a catalogue with no pictures in it - and the next edit then rebuilt the shop
    // without them, swapping the merchant's photos for searched ones.
    parsedData: record.parsedData,
    intent: intent,
    latitude: null,
    longitude: null
  }
}];

const geoData = $('Resolve Shop Location1').first().json;
const dbData = $input.first().json;

// The freshly compiled page. It is copied onto this item explicitly because the write below
// sends the whole item: without html_content the row kept whatever page it had the first time
// the shop was created, so every later edit (cart fix, layout fix, price change) never reached
// the live site. This is the line that makes a rebuild actually appear for buyers.
const site = (function () { try { return $('Storefront Compiler & UX Features3').first().json || {}; } catch (e) { return {}; } })();
const parsed = site.parsedData || {};

// Was this page built as a brand-new, separate website? Read from the routing step by name, so a
// second business on the same number creates its OWN row instead of rewriting the first shop's.
const newSite = (() => {
  try { return $('Validate & Route Intent').first().json.isNewSiteBuild === true; } catch (e) { return false; }
})();
const row = {
  ...geoData,
  slug: String(site.slug || geoData.slug || ''),
  // The address this shop used to live at, so the storefront can still serve a link that was
  // already handed out before the address was corrected to the business's own name.
  // A shop built as a SECOND, SEPARATE business never points at the address of the first one:
  // previous_slug is what makes the store row of shop A answer for shop B, so the new page would
  // be written over the old one and the two businesses would share a site.
  previous_slug: newSite ? '' : String(parsed.previous_slug || geoData.previous_slug || ''),
  html_content: String(site.html_content || ''),
  live_store_url: String(site.live_store_url || ''),
  merchant_name: String(site.merchant_name || parsed.merchant_name || ''),
  hero_headline: String(parsed.hero_headline || ''),
  // The merchant's chosen look is part of the saved shop, so a later edit that only changes a
  // price cannot silently drop the background colour or banner they picked.
  background_color: String(parsed.background_color || ''),
  brand_color: String(parsed.brand_color || ''),
  hero_image: String(parsed.hero_image || ''),
  business_category: String(parsed.business_category || ''),
  location: String(parsed.location || ''),
  site_tier: String(parsed.site_tier || 'MICRO'),
  senderPhone: String(site.senderPhone || geoData.senderPhone || '')
};

// If Baserow found an ID, we merge it with our fresh HTML and trigger an UPDATE.
// If it found nothing, we trigger a CREATE.
// ONE ROW PER WEBSITE. The store table holds a row per shop, so the row this page belongs to is
// chosen by its own address - never by "the first row for this phone". Without this, building a
// second shop updated the first shop's page and the two businesses merged into one.
const normSlug = (v) => { let t = String(v || '').trim().toLowerCase(); while (t.charAt(t.length - 1) === '/') t = t.slice(0, -1); return t; };
const wantSlug = normSlug(row.slug);
const prevSlug = normSlug(row.previous_slug);
const rowSlugOf = (r) => normSlug(r && (r.slug || r.field_slug));
let allRows = [];
try { allRows = $input.all().map((i) => i.json || {}).filter((r) => r && r.id); } catch (e) { allRows = []; }
if (!allRows.length && dbData && dbData.id) allRows = [dbData];
const anySlugField = allRows.some((r) => String(rowSlugOf(r) || '') !== '');
const match = newSite
  ? (allRows.find((r) => wantSlug && rowSlugOf(r) === wantSlug) || null)
  : (anySlugField
    ? (allRows.find((r) => wantSlug && (rowSlugOf(r) === wantSlug || (prevSlug && rowSlugOf(r) === prevSlug))) || null)
    : (allRows.length === 1 ? allRows[0] : null));
if (match && match.id) {
  return [{ json: { ...row, id: match.id, db_action: 'UPDATE' } }];
} else {
  return [{ json: { ...row, db_action: 'CREATE' } }];
}

