parameters.jsCode:
const safe = (fn) => { try { return fn(); } catch (e) { return null; } };
const site = safe(() => $('Storefront Compiler & UX Features3').first().json) || {};
const shortener = safe(() => $('HTTP Request2').first().json) || {};
const slug = String(site.slug || '').trim();
const liveUrl = 'https://orchid-frigatebird.pikapod.net/webhook/storefront?slug=' + slug;

// A build that produced no page must never be announced as live. The compiler emits nothing when
// it cannot make a site, and this guard is what stops the merchant being congratulated over a
// shop that opens empty. Nothing is saved and the reason is stated in plain words.
const pageHtml = String(site.html_content || '').trim();
if (!slug || pageHtml.length < 500) {
  return [{ json: {
    slug: slug,
    storeUrl: '',
    liveStoreUrl: '',
    shortenerOk: false,
    buildFailed: true,
    siteReplyText: 'I could not finish your website just now, so nothing was saved and no link was sent. ' +
      'Please send your business name and the items you sell again in one line - for example "Chips 5000, Soda 2000" - and I will build it right away.'
  } }];
}

// Prefer the short branded link. When the shortener is down or refuses the request, still hand
// the merchant a working link instead of dropping the message entirely.
const shortUrl = String(shortener.shortURL || shortener.secureShortURL || '').trim();
const looksLikeLink = shortUrl.startsWith('http://') || shortUrl.startsWith('https://');
// A short link is only handed out when it genuinely points at THIS shop. The shortener also
// returns links left over from earlier runs (and, while unmocked, an empty-slug link), and
// those open a 404 - so the destination is checked against the slug before it is trusted.
const shortenerTarget = String(shortener.originalURL || shortener.original_url || '');
const pointsAtThisShop = looksLikeLink && (!slug || shortenerTarget.indexOf(slug) >= 0);
const link = pointsAtThisShop ? shortUrl : liveUrl;
const shortenerOk = pointsAtThisShop;

// The hand-off text is built by the storefront compiler and passed straight through, so the
// link and the message can never drift apart and no field is read from the wrong node.
let siteReply = '';
// A static edit confirmation is delivered exactly as it was assembled - no location line and no
// re-wording - so the merchant always reads the same honest report of what changed.
let staticEdit = '';
try { staticEdit = String(site.editConfirmReply || '').trim(); } catch (e) { staticEdit = ''; }
if (!staticEdit) {
try {
  siteReply = String(site.whatsapp_reply || '')
    // The compiler stores the hand-off text with escaped line breaks; turn them into real
    // newlines so WhatsApp renders the message instead of showing a literal backslash-n.
    .replace(/\\n/g, String.fromCharCode(10))
    .replace(/\n/g, String.fromCharCode(10))
    .trim();
} catch (e) {}
}

// Tell the merchant where the shop was actually placed, so a wrong pin is caught by the person
// who knows the street rather than discovered by a buyer standing in the wrong place.
const pinLabel = String(site.location || '').trim();
const pinMapsUrl = String(site.google_maps_url || '').trim();
let locationLine = '';
if (site.has_location_pin === true && site.location_accuracy === 'exact') {
  locationLine = String.fromCharCode(10) + String.fromCharCode(10) + '📍 Shop pinned at ' + (pinLabel || 'the location you shared') +
    (pinMapsUrl ? String.fromCharCode(10) + pinMapsUrl : '') +
    String.fromCharCode(10) + 'If that is not exactly your door, share your live location here and it moves with one tap.';
} else if (site.has_location_pin === true) {
  locationLine = String.fromCharCode(10) + String.fromCharCode(10) + '📍 Placement: ' + (pinLabel || 'your area') +
    (pinMapsUrl ? String.fromCharCode(10) + pinMapsUrl : '') +
    String.fromCharCode(10) + 'That is the area, not your exact door. Share your live location here and I will move the pin to your shop.';
}
if (locationLine && !staticEdit) siteReply = (siteReply + locationLine).trim();

return [{ json: { slug: slug, storeUrl: link, liveStoreUrl: liveUrl, shortenerOk: shortenerOk, siteReplyText: staticEdit || siteReply } }];

const item = $input.first().json || {};
let site = {};
try { site = $('Storefront Compiler & UX Features3').first().json || {}; } catch (e) { site = {}; }

const slugify = (v) => String(v || '').toLowerCase().replace(/&/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

// The address has to be the shop's own name. A shop saved before the address rule was fixed is
// still sitting on another merchant's slug; this compares the two and corrects it once.
const currentSlug = String(site.slug || item.slug || '').trim();
const nameSlug = slugify(site.merchant_name || (site.parsedData && site.parsedData.merchant_name) || '');
const phone = String(item.merchant_phone || item.senderPhone || '').replace(/[^0-9]/g, '');
const wanted = nameSlug ? (nameSlug + (phone ? '-' + phone.slice(-4) : '')) : currentSlug;

// "Contains" is enough to know the address already belongs to this business.
const nameWords = nameSlug.split('-').filter(w => w.length > 2);
const alreadyOwned = currentSlug && (currentSlug === wanted || (nameWords.length > 0 && nameWords[0] && currentSlug.indexOf(nameWords[0]) >= 0));

if (!currentSlug || alreadyOwned || !wanted) {
  return [{ json: { ...item } }];
}

return [{
  json: {
    ...item,
    slug: wanted,
    live_store_url: 'https://orchid-frigatebird.pikapod.net/webhook/storefront?slug=' + wanted,
    previous_slug: currentSlug,
    whatsapp_reply: String(item.whatsapp_reply || '').split(currentSlug).join(wanted)
  }
}];

const site = $('Storefront Compiler & UX Features3').first().json || {};
let phone = '';
try { phone = String($('Validate & Route Intent').first().json.senderPhone || '').replace(/[^0-9]/g, ''); } catch (e) {}
if (!phone) { try { phone = String($('Parse WhatsApp Message').first().json.senderPhone || '').replace(/[^0-9]/g, ''); } catch (e) {} }

// The whole shop as it was actually built: name, story, location, products and any promotion.
// A later edit reads this back, so a merchant never starts their shop again to change a price.
const catalogue = (site.parsedData && typeof site.parsedData === 'object') ? site.parsedData : {};
const slug = String(site.slug || '');

// ONE ROW PER WEBSITE, even when the shop's address changes.
// The row key is number|slug, so a corrected address used to INSERT a second row for the same
// business - the merchant then saw the same shop twice in "which website do you want to change?",
// and an edit could land on the stale copy. When this message was about a shop that already has a
// catalogue row, that row is updated in place and its slug moves with it.
let priorKey = '';
let priorSlug = '';
let priorName = '';
try {
  const ss = ($('Attach Saved Shop1').first().json || {}).savedShop || {};
  priorKey = String(ss.catalogue_row_key || '');
  priorSlug = String(ss.catalogue_slug || '');
  priorName = String(ss.merchant_name || '');
} catch (e) { priorKey = ''; priorSlug = ''; priorName = ''; }
// Only the SAME business may move its row to a new address. A merchant adding a SECOND business on
// the same number keeps its own row: the names must match for a row to be reused.
const nameKey = (v) => String(v || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const newNameKey = nameKey(site.merchant_name || catalogue.merchant_name || '');
const oldNameKey = nameKey(priorName);
const sameBusiness = !oldNameKey || !newNameKey || newNameKey === oldNameKey
  || newNameKey.indexOf(oldNameKey) >= 0 || oldNameKey.indexOf(newNameKey) >= 0;
const sameShop = Boolean(priorKey) && Boolean(priorSlug) && Boolean(slug)
  && priorSlug !== slug
  && sameBusiness
  && priorKey.indexOf(String(phone) + '|') === 0;
// A SECOND, SEPARATE WEBSITE ALWAYS GETS ITS OWN ROW. Reusing the prior key here is what merged a
// new business into the website that already existed: the new items were written over the old
// shop's catalogue. The key is number|slug, so the two sites can never share a row.
const newSiteBuild = (() => {
  try { return $('Validate & Route Intent').first().json.isNewSiteBuild === true; } catch (e) { return false; }
})();
const rowKey = (!newSiteBuild && sameShop) ? priorKey : (phone + '|' + slug);

return [{
  json: {
    row_key: rowKey,
    merchant_phone: phone,
    store_slug: slug,
    merchant_name: String(site.merchant_name || catalogue.merchant_name || ''),
    // The rate this page was built with is remembered with the shop, so a later build whose feed
    // is unreachable still uses a real published figure instead of inventing one.
    catalogue_json: JSON.stringify(Object.assign({}, catalogue, {
      ugx_per_usd: (() => { try { const r = Number($('Read USD Rates1').first().json.ugx_per_usd); return r > 0 ? r : undefined; } catch (e) { return undefined; } })()
    })),
    promotion: String(catalogue.promotion || ''),
    updated_date: new Date().toISOString()
  }
}];

const site = $('Storefront Compiler & UX Features3').first().json || {};
const html = String(site.html_content || '');

// Strip the page down to readable text so the reviewer judges content, not markup.
const text = html
  .replace(/<style[^]*?<\/style>/gi, ' ')
  .replace(/<script[^]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 1600);

const instructions = [
  'You are a web quality reviewer. Judge only the PAGE CONTENT below.',
  '',
  'Reply with JSON only, in this exact shape:',
  '{ "ok": true|false, "score": 0-10, "problems": ["..."], "fixes": ["..."] }',
  '',
  'Set ok to false and list a problem when any of these is true:',
  '- the business name is missing or nonsense',
  '- the headline is empty, all-caps gibberish, or a slogan used as a title',
  '- a product has no description',
  '- a product price is 0, says "Ask the merchant", or is clearly a placeholder',
  '- the same price is repeated for every product',
  '- text is duplicated',
  '- the about section is empty or only repeats the business name',
  '',
  'Be strict but fair. If it reads like a real shop a customer could use, ok is true.',
  '',
  'PAGE CONTENT:',
  text
].join('\n');

return [{
  json: {
    ...site,
    // No max_tokens on purpose: this model spends most of its budget on reasoning, and a tight
    // cap made it finish on length with an empty answer, so the review silently lost its verdict.
    metaPayload: {
      model: 'muse-spark-1.3',
      messages: [{ role: 'user', content: instructions }]
    }
  }
}];

const site = $('Storefront Compiler & UX Features3').first().json || {};
let raw = '';
try {
  const c = $json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content;
  raw = typeof c === 'string' ? c : '';
} catch (e) { raw = ''; }

let verdict = {};
try {
  const a = raw.indexOf('{');
  const b = raw.lastIndexOf('}');
  verdict = (a !== -1 && b > a) ? JSON.parse(raw.substring(a, b + 1)) : {};
} catch (e) { verdict = {}; }

const problems = Array.isArray(verdict.problems) ? verdict.problems : [];
const fixes = Array.isArray(verdict.fixes) ? verdict.fixes : [];
const ok = verdict.ok === true;
const score = typeof verdict.score === 'number' ? verdict.score : null;

return [{
  json: {
    ...site,
    reviewOk: ok,
    reviewScore: score,
    reviewProblems: problems,
    reviewFixes: fixes,
    reviewSummary: ok
      ? 'Site review passed (score ' + score + ').'
      : 'Site review flagged ' + problems.length + ' issue(s).',
    whatsapp_reply: (ok || problems.length === 0) ? site.whatsapp_reply : (site.whatsapp_reply + '\n\nReview before publishing:\n' + problems.map((p, i) => '- ' + p + (fixes[i] ? ' (fix: ' + fixes[i] + ')' : '')).join('\n'))
  }
}];
